insert into private.study_guides (guide, chunks, sha256) values ('study_guide_pul101', 42, 'c8613055f9811e17e7d8bb4918afbe8e121a477befa6061e52c3ec35809d42ea');
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 1, $study_guide${"guide":"study_guide_pul101","code":"PUL101","courseId":"4df568c2-4a68-52ab-80d6-380e5921d119","actor":"00000000-0000-4000-8000-000000000045","overview":{"itemId":"5aae98ed-05b3-594c-8229-85b162ad702f","create":true,"after":{"title":"Legal Methods I","body":"Every topic is examinable.","outcomes":["Define law, explain the schools of thought and assess their relevance today.","Explain the objectives of law, the meanings and types of justice, and the relationship between the state, rulers and citizens.","Classify law into its main divisions.","Explain the techniques by which law is used to control society, and their limits.","Explain how facts are found and disputes resolved, in court and outside it.","Use the language of legal reasoning: logic, rhetoric, principles, standards and precedent.","Describe how legislation is made, its types, and the rules of statutory interpretation with cases.","Identify and explain the sources of Nigerian law.","Carry out basic legal research and write a structured legal essay or problem answer."],"assessment":["Expect essay questions (for example, answer four out of six) and objective questions.","Essay questions often quote a jurist or judge and ask you to discuss, with authorities. Learn the definitions with who said them, the lists, and at least one case for each point."]}},"retire":[],"notes":[{"kind":"note","itemId":"f7cfebf5-5437-538a-8b29-c9b7eb6ca863","sourceKey":"guide-topic:1","position":1,"payload":{"title":"Law in Social Context","body":"What legal method is; the meaning, definitions and features of law; every school of thought (positivist, pure theory, natural law, historical, sociological, utilitarian, functional, realist, Marxist), its jurists, its criticisms and its relevance today; the evolution and functions of law; the four theories on the functions of law; law and morality.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"What legal method is; the meaning, definitions and features of law; every school of thought (positivist, pure theory, natural law, historical, sociological, utilitarian, functional, realist, Marxist), its jurists, its criticisms and its relevance today; the evolution and functions of law; the four theories on the functions of law; law and morality."}],"lessons":[{"number":"1.1","title":"Meaning, definitions and features of law","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Legal method:","bold":true},{"text":" an attempt to explain or analyse the technique of \"thinking like a lawyer\": studying the use and construction of legal rules to see how law is organised to achieve its objectives."}]},{"text":[{"text":"General sense of \"law\":","bold":true},{"text":" law of a club, law of God, law of demand and supply. "},{"text":"Technical sense:","bold":true},{"text":" the sense used in legal studies."}]},{"text":[{"text":"Working (institutional) definition:","bold":true},{"text":" \"a rule or body of rules made by institutions, bodies and persons vested with the power to make such rules which are binding and enforced among the members of a given state or society.\""}]}]},{"type":"table","header":[[{"text":"Jurist"}],[{"text":"Definition"}]],"rows":[[[{"text":"John Austin"}],[{"text":"\"A command set by a superior being to inferior beings and enforced by sanctions\""}]],[[{"text":"H.L.A. Hart"}],[{"text":"The union of primary rules of obligation and secondary rules of recognition"}]],[[{"text":"Cicero"}],[{"text":"The highest reason, rooted in nature, which commands what must be done and forbids the opposite"}]],[[{"text":"Thomas Aquinas"}],[{"text":"\"An ordinance of reason for the common good, made by him who has care of the community\""}]],[[{"text":"Aristotle"}],[{"text":"Reason without desire (free from passion)"}]],[[{"text":"Blackstone"}],[{"text":"\"A rule of action dictated by some superior being\"; municipal law is a rule of civil conduct prescribed by the supreme power in a state, commanding what is right and prohibiting what is wrong"}]],[[{"text":"Salmond"}],[{"text":"The body of principles recognised and applied by the state in the administration of justice (\"the rules recognised and acted on in courts of justice\")"}]],[[{"text":"Roscoe Pound"}],[{"text":"A social institution for satisfying human wants (social engineering)"}]],[[{"text":"O.W. Holmes Jr."}],[{"text":"The prediction (prophecy) of what the courts will do in fact"}]]]},{"type":"paragraph","text":[{"text":"6 features of law:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"A body of rules:","bold":true},{"text":" in many sources (Constitution, statutes, case law), not one book."}]},{"text":[{"text":"Man-made:","bold":true},{"text":" values (religion, morality, custom) are not law unless traceable to institutional sources: Constitution, statute, case law, delegated legislation."}]},{"text":[{"text":"Normative:","bold":true},{"text":" it guides what we may, ought or ought not to do (shared with moral and religious rules)."}]},{"text":[{"text":"Element of coercion:","bold":true},{"text":" breach is sanctioned through organised institutions (police, courts, prisons). This is the "},{"text":"main factor distinguishing law from moral or ethical rules","bold":true},{"text":", enforced only by social disapproval."}]},{"text":[{"text":"Territorial limitation:","bold":true},{"text":" binds only within its territory."}]},{"text":[{"text":"Dynamic:","bold":true},{"text":" it changes as social, political and economic conditions change."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A church in Ibadan that suspends members who refuse to fast has a sanction, but its rule is "},{"text":"not law in the technical sense","bold":true},{"text":" because it is not traceable to the Constitution, statutes or case law."}]},{"text":[{"text":"Territorial limitation:","bold":true},{"text":" in "},{"text":"Holman v Johnson","italic":true},{"text":" (1775), tea was sold in Dunki$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 2, $study_guide$rk to a buyer who planned to smuggle it into England. The seller recovered the price: \"no country ever takes notice of the revenue laws of another country.\" In Nigeria the Criminal Code applies in the South and the Penal Code in the North, so a Muslim from Kano who drinks alcohol in Lagos cannot be prosecuted under the Penal Code."}]},{"text":[{"text":"Dynamic:","bold":true},{"text":" colonial law differed from law after independence in 1960; military-era law differed from law under elected governments."}]},{"text":[{"text":"No final definition:","bold":true},{"text":" five blind men each touched a different part of an elephant and described it differently: all correct, yet wrong. Each definition of law is shaped by the definer's perspective (judge, legislator, accused). Okunniga: \"Nobody ... will ever be able to offer a definition of law to end all definitions.\" "}]},{"text":[{"text":"About the theories in general:","bold":true},{"text":" a jurist's ideas may embrace more than one theory; virtually all legal systems have applied the theories in varying degrees (so no theory belongs to one system alone); the theories are often "},{"text":"implicit","bold":true},{"text":", not explicit (\"the President has the power to introduce a fuel tax\" implicitly reflects Austin)."}]}]}]},{"number":"1.2","title":"Positivism, Hart and the Pure Theory of Law","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Positive law:","bold":true},{"text":" from \"posit\" (to put or place): law put or imposed by rulers: the Constitution, statutes, case law, administrative rules. Positivists separate law as it is from law as it ought to be; an unjust law properly made is still valid law."}]},{"text":[{"text":"John Austin","bold":true},{"text":" ("},{"text":"The Province of Jurisprudence Determined","italic":true},{"text":"): command theory. "},{"text":"3 elements:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"a "},{"text":"definite sovereign","bold":true},{"text":" (one person, a group or many);"}]},{"text":[{"text":"the sovereign is "},{"text":"without legal limitation","bold":true},{"text":", above the law: the "},{"text":"\"uncommanded commander\"","bold":true},{"text":" (the highest authority, subject to no one's command);"}]},{"text":[{"text":"the subjects are in the "},{"text":"habit of obeying","bold":true},{"text":" him because of his power to impose "},{"text":"sanctions","bold":true},{"text":"."}]}]}]},{"text":[{"text":"\"Law must agree with morality or natural justice\" is "},{"text":"not","bold":true},{"text":" an element."}]}]},{"type":"paragraph","text":[{"text":"4 criticisms of Austin:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Not all laws are commands: the law on "},{"text":"wills","bold":true},{"text":" does not compel anyone to make a will; one may marry under the Marriage Act or customary law."}]},{"text":[{"text":"Law is whatever the sovereign says, regardless of its goodness or the lawmaker's character, so it can justify "},{"text":"dictatorship","bold":true},{"text":"."}]},{"text":[{"text":"No one is above the law, even a military government: "},{"text":"Lakanmi v A.G. (Western State)","italic":true},{"text":" (1971), where the Supreme Court declared the Forfeiture of Assets (Validation) Decree No. 45 of 1968 null and void."}]},{"text":[{"text":"People do not obey only from fear of sanction: many do not smoke in public or kill because it is not their way of life."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"H.L.A. Hart","bold":true},{"text":" ("},{"text":"The Concept of Law","italic":true},{"text":", 1961): law = union of "},{"text":"primary rules","bold":true},{"text":" (rules of obligation: do not steal, pay tax) and "},{"text":"secondary rules","bold":true},{"text":" (rules about rules: "},{"text":"recognition","bold":true},{"text":", "},{"text":"change","bold":true},{"text":", "},{"text":"adjudication","bold":true},{"text":"). The constitutional rules on how a bill becomes an Act are secondary rules."}]},{"text":[{"text":"Hans Kelsen","bold":true},{"text":" (1881-1973), "},{"text":"Pure Theory of Law:","bold":true},{"text":" law is a "},{"text":"hierarchy of norms","bold":true},{"text":"; each norm is valid because a higher norm created it, up to the "},{"text":"grundnorm","bold":true},{"text":" (basic norm), which is presupposed, not enacted, and whose validity cannot be traced to any other norm. Law must be studied as a self-contained system, pure of morality, politics and sociology; the moral quality of a rule is irrelevant to its validity. Kelsen called the command theory nonsensical."}]},{"text":[{"text":"Kelsen's chain:","bold":true},{"text":" murder is forbidden because the Criminal Code says so; the Code is valid because the legislature enacted it (section 4, 1999 Constitution); the legislature is valid because it was constituted under the Constitution; the Constitution is valid because it was promulgated as the Act of the people."}]}]},{"type":"paragraph","text":[{"text":"3 criticisms of Kelsen:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It stresses "},{"text":"formal validity","bold":true},{"text":" rather than the content and effects of law; it can serve dictators."}]},{"text":[{"text":"The grundnorm is hard to identify (who made the Constitution: the military or the people?)."}]},{"text":[{"text":"After a successful coup, validity depends on the "},{"text":"effectiveness","bold":true},{"text":" of the new legal order, not the old Constitution ("},{"text":"The State v Dosso","italic":true},{"text":" (1958); later rejected in "},{"text":"Jilani v Government of Punjab","italic":true},{"text":" (1972)); a failed coup means treason charges."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Grossly unjust rules are not law\" is a "},{"text":"natural law","bold":true},{"text":" claim, $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 3, $study_guide$never Kelsen's or Austin's."}]},{"text":[{"text":"A properly enacted levy of ₦5,000 that only benefits the rich is, to a strict positivist, valid law though unjust."}]},{"text":[{"text":"Hart's "},{"text":"\"minimum content of natural law\"","bold":true},{"text":": rules every society needs because of human vulnerability, approximate equality, limited altruism, limited resources and limited understanding and strength of will."}]},{"text":[{"text":"Relevance today:","bold":true},{"text":" positivism explains why courts apply enacted law and why the Constitution is supreme; Kelsen explains the hierarchy of Constitution, Acts and subsidiary legislation, and how courts treated coups as creating a new grundnorm."}]}]}]},{"number":"1.3","title":"Natural law and the historical school","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Natural law:","bold":true},{"text":" at its simplest, what is "},{"text":"fair, just or right","bold":true},{"text":". There are objective principles in every person, whatever race or colour, telling them what is fair, just or right, deduced by "},{"text":"reason","bold":true},{"text":" from the nature of man, society and things, and existing irrespective of human enactment. Man-made law that conflicts with them should not command obedience: natural law tests the "},{"text":"validity","bold":true},{"text":" of man-made law."}]},{"text":[{"text":"Chief protagonists:","bold":true},{"text":" Zeno, Thomas Aquinas, Grotius (also Cicero)."}]},{"text":[{"text":"Okunniga's illustration:","bold":true},{"text":" ten men from different countries, put in separate rooms and asked in their own language whether stealing is good: most say no."}]},{"text":[{"text":"Historical school:","bold":true},{"text":" led by "},{"text":"Friedrich Carl von Savigny","bold":true},{"text":" (1779-1861), a German aristocrat with an interest in the status quo. Developed to "},{"text":"counter natural law","bold":true},{"text":", which was used in 17th and 18th century Europe to overthrow monarchs. Every people has a "},{"text":"volksgeist","bold":true},{"text":" (spirit of the people); for law to be valid it must accord with the history, customs and way of life of the people. Law should be a formal restatement of custom and should evolve, not come by revolution."}]}]},{"type":"paragraph","text":[{"text":"Criticisms of natural law:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It stresses what "},{"text":"ought","bold":true},{"text":" to be done, not what is done. Courts apply the formal sources; unless its principles are enacted into law, their violation cannot be legally penalised."}]},{"text":[{"text":"\"Right reason\" cannot be verified empirically, so the powerful interpret it."}]},{"text":[{"text":"Multiple conscience problem:","bold":true},{"text":" different people hold different ideas of what is fair or just on the same issue; it has defended tyranny, slavery, colonialism and apartheid as well as liberation (hence called \"a harlot\"), and could lead to anarchy."}]}]},{"type":"paragraph","text":[{"text":"Criticisms of the historical school:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It suggests the past, not the will and objectives of society, decides its law; it can block desirable radical reforms."}]},{"text":[{"text":"It assumes customs are rational and fair, yet some customs subject people to servitude and prejudice women in inheritance and labour."}]},{"text":[{"text":"Modern diverse societies need a force above custom to reconcile customs."}]}]},{"type":"paragraph","text":[{"text":"3 validity tests for customary law in Nigeria:","bold":true},{"text":" a rule must not be"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"repugnant to natural justice, equity and good conscience;"}]},{"text":[{"text":"contrary to public policy;"}]},{"text":[{"text":"incompatible, directly or by necessary implication, with any law for the time being in force."}]}]},{"type":"paragraph","text":[{"text":"(There is no requirement that it be written down, approved by the National Assembly, or match English law.)"}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Relevance today:","bold":true},{"text":" natural law is the basis of "},{"text":"equality, human rights and democracy","bold":true},{"text":": it was invoked in the American War of Independence, the French Revolution, African independence struggles, and by Niger Delta groups demanding a fairer share of oil revenue or resource control. Chapter IV (fundamental rights) of the 1999 Constitution reflects it."}]},{"text":[{"text":"Historical school in practice:","bold":true},{"text":" if a state suddenly bans a centuries-old burial custom, people will ignore it or find clever ways round it, exactly as Savigny predicted."}]}]}]},{"number":"1.4","title":"Sociological, utilitarian, functional and realist schools","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sociological school","bold":true},{"text":" (mid-19th to 20th century):"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Eugen Ehrlich","bold":true},{"text":" (1862-1922): law rests on the "},{"text":"\"facts of law\"","bold":true},{"text":", meaning "},{"text":"how people actually behave","bold":true},{"text":". Society's conduct determines the law, not the sovereign's rules; the "},{"text":"living law","bold":true},{"text":" dominates social life. \"The centre of gravity of legal development lies not in legislation nor juristic science nor in judicial decisions but the society itself.\""}]},{"text":[{"text":"Roscoe Pound","bold":true},{"text":", former Dean of Harvard Law School: law satisfies human wants by "},{"text":"balancing competing claims","bold":true},{"text":" to limited resources with the least harm or disruption to established institutions ("},{"text":"social engineering","bold":true},{"text":"); his main f$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 4, $study_guide$ocus was the courts."}]}]}]},{"text":[{"text":"Utilitarian school:","bold":true},{"text":" "},{"text":"Jeremy Bentham","bold":true},{"text":" (1748-1832): law should promote the "},{"text":"greatest good (happiness) of the greatest number","bold":true},{"text":". "},{"text":"4 utilities:","bold":true},{"text":" security, equality, liberty, abundance; "},{"text":"security first","bold":true},{"text":", liberty second. John Stuart Mill refined it (higher and lower pleasures)."}]},{"text":[{"text":"Functional school:","bold":true},{"text":" an outgrowth of the sociological school, founded on pragmatism. Law is what the court will do in a particular case. "},{"text":"O.W. Holmes Jr.","bold":true},{"text":" viewed law from the standpoint of the "},{"text":"\"bad man\"","bold":true},{"text":", who cares nothing for legal theory and wants only to know what the courts will do. It recognises judges' law-making power."}]},{"text":[{"text":"Realist school","bold":true},{"text":" (American; began in the 1920s, peaked in the 1930s): focused on "},{"text":"trial courts","bold":true},{"text":" to reform the judiciary. Judges and juries are influenced by "},{"text":"extralegal factors","bold":true},{"text":": way of life, social and educational background, likes and dislikes, dress, skin colour, age, attitude to precedent, and the personality of the accused and his lawyer. "},{"text":"Exponents:","bold":true},{"text":" Holmes, Jerome Frank, John Chipman Gray, Karl Llewellyn. "},{"text":"Main goal:","bold":true},{"text":" make judges conscious of their hidden prejudices. \"Law is the prediction of what the courts will do in fact.\""}]}]},{"type":"table","header":[[{"text":"School"}],[{"text":"Criticism"}]],"rows":[[[{"text":"Sociological (Ehrlich)"}],[{"text":"Law also shapes conduct (car owners register vehicles and stop at roadblocks because the law says so); hard to measure law's effect; denies formal sources creative value; \"everyone else is doing it\" is no defence"}]],[[{"text":"Pound"}],[{"text":"No method to identify and weigh interests; balances differently at different times; favours stability and short-run expediency (liberty may give way to security)"}]],[[{"text":"Utilitarian"}],[{"text":"Does not show how to balance individual and communal interests"}]],[[{"text":"Functional"}],[{"text":"Looks at courts alone and neglects the legislature and agencies, though courts are themselves created by law"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Ehrlich in Nigeria:","bold":true},{"text":" anti-corruption laws exist, yet some police officers openly collect money (₦100) from motorists at checkpoints; the Child's Rights Act 2003 has not ended child labour. To Ehrlich, the real law is what people do."}]},{"text":[{"text":"Utilitarian example:","bold":true},{"text":" searching every airport passenger without suspicion: a small loss of liberty buys greater security for all."}]},{"text":[{"text":"Realist examples:","bold":true},{"text":" a lawyer telling his \"area boy\" client to dress responsibly and drop his dark glasses in court; \"Mr A's case may be weak, but a celebrated human rights lawyer and a judge of his faith will make a difference.\""}]},{"text":[{"text":"Holmes appears in both the functional and realist schools. Savigny is never a realist."}]}]}]},{"number":"1.5","title":"Evolution, functions and theories on the functions of law","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Evolution:","bold":true},{"text":" a hermit needs no law, but once two people live together interests conflict. First "},{"text":"self-help","bold":true},{"text":" (reprisals, feuds; might was right); then customs administered by monarchs or elders with unorganised sanctions (ostracism, ridicule); today government administers law through courts, police and bureaucracy."}]}]},{"type":"paragraph","text":[{"text":"4 functions of law:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Definition and regulation of social relationships:","bold":true},{"text":" marriage is between a man and a woman; prolonged cohabitation does not make a couple husband and wife; freedom of association (section 40) is regulated (CAMA for companies)."}]},{"text":[{"text":"Identification and allocation of official authority:","bold":true},{"text":" sections 4, 5 and 6 of the 1999 Constitution vest legislative, executive and judicial powers."}]},{"text":[{"text":"Dispute settlement and remedies:","bold":true},{"text":" courts and tribunals; remedies for breach of contract (damages, specific performance, injunction, rescission, indemnity)."}]},{"text":[{"text":"Change of law:","bold":true},{"text":" section 9 (amending the Constitution), section 58 (making new laws), subsidiary legislation for minor changes."}]}]},{"type":"paragraph","text":[{"text":"(Other lists add crime prevention and control, business transactions and interstate engagement.)"}]},{"type":"paragraph","text":[{"text":"4 theories on the functions of law","bold":true},{"text":" (they focus on law's function, not its origin):"}]},{"type":"table","header":[[{"text":"Model"}],[{"text":"Core idea"}],[{"text":"Criticism"}]],"rows":[[[{"text":"Consensus","bold":true},{"text":" (Talcott Parsons)"}],[{"text":"Law protects values everyone shares; society is unitary; Parliament represents all; law is equal and just to all; conflicts are only personal"}],[{"text":"No society has one shared value system; \"consensus\" may hide sectional interests (oil revenue arrangements)"}]],[[{"text":"Conflict / pluralist","bold":true}],[{"text":"No shared values; competing groups with roughly "},{"text":"equal bargaining power","bold":true},{"text":"; the state is a "},{"text":"neutral arbiter","bold":true}],[{"text":"Groups are not equal (Pareto: 10% own 90% of resources); access to justice is skewed (lawyers are costly, courts seem elitist)"}]],[[{"text":"Open","bold":true},{"text":" (Dahrendorf)"}],[{"text":"Middl$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 5, $study_guide$e way: conflict continues but is resolved through legitimate processes: negotiation, arbitration, judicial decision, elections, strikes, "},{"text":"never revolution","bold":true}],[{"text":"(A middle position between the consensus and conflict extremes)"}]],[[{"text":"Marxist","bold":true},{"text":" (Karl Marx)"}],[{"text":"Stability comes from the capitalist class exploiting the working class; law is a tool of the ruling class"}],[{"text":"No guarantee that overthrowing the ruling class brings equality; an invitation to repeated revolution"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Dispute settlement varies with society.","bold":true},{"text":" In community-based societies relationships continue, so disputes end in "},{"text":"compromise","bold":true},{"text":". In a complex society, Mr A, paralysed by a stranger company's tanker, wants no future relationship, so the claim is settled on a "},{"text":"\"winner takes all\"","bold":true},{"text":" basis."}]},{"text":[{"text":"Why workers accept domination (Marx):","bold":true},{"text":" the ruling class controls (1) the instruments of "},{"text":"coercion","bold":true},{"text":" (army, police, law) and (2) the "},{"text":"dominant ideas","bold":true},{"text":": \"the ideas of the ruling class are in every epoch the ruling ideas.\""}]},{"text":[{"text":"Workers and employers who settle wage disputes by negotiation, strikes, arbitration, courts and elections, never revolution, fit the "},{"text":"open model","bold":true},{"text":"."}]}]}]},{"number":"1.6","title":"Law and morality","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Morality (Phil Harris):","bold":true},{"text":" \"code of beliefs, values, principles and standards of behaviour, some versions of which are found in all social groups.\" Moral standards are usually higher than legal ones."}]},{"text":[{"text":"Relativity of moral ideas:","bold":true},{"text":" groups differ on right and wrong; respect for elders is strict in villages but relaxed in Lagos and Port Harcourt."}]},{"text":[{"text":"Lord Devlin:","bold":true},{"text":" societies disintegrate when common morality is lost; \"The suppression of vice is as much the law's business as the suppression of subversive activities.\""}]},{"text":[{"text":"Crimes without victims","bold":true},{"text":" (drug addiction, abortion, homosexuality): the clash between individual liberty and public morality."}]},{"text":[{"text":"Shaw v DPP","bold":true,"italic":true},{"text":" [1962]: Shaw published \"The Ladies' Directory\" advertising prostitutes and was convicted of "},{"text":"conspiracy to corrupt public morals","bold":true},{"text":". Viscount Simonds: the court has \"a residual power to enforce the supreme and fundamental purpose of the law, to conserve not only the safety and order, but also the moral welfare of the State.\" The wrong was public advertisement, not prostitution itself."}]},{"text":[{"text":"Knuller v DPP","bold":true,"italic":true},{"text":" [1973]: the Sexual Offences Act 1967 decriminalised private homosexual acts between consenting adult males, but the House of Lords held it gave "},{"text":"no licence to publicly encourage","bold":true},{"text":" them (Lord Reid); the publishers of "},{"text":"International Times","italic":true},{"text":" were convicted."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Moral rules become law when pressure groups win over the legislature; the law must then be enforced, or the moral code is \"observed only in its breach\" (campus dress codes)."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Legal method = thinking like a lawyer; law in the technical sense comes from institutional sources."}]},{"text":[{"text":"Six features: body of rules, man-made, normative, coercive (main mark of law), territorial ("},{"text":"Holman v Johnson","italic":true},{"text":"), dynamic."}]},{"text":[{"text":"Austin: sovereign, no legal limitation, habit of obedience; refuted by wills, "},{"text":"Lakanmi","italic":true},{"text":", non-fearful obedience."}]},{"text":[{"text":"Hart: primary and secondary rules. Kelsen: hierarchy of norms to the grundnorm; formal, hard to locate, fails after coups."}]},{"text":[{"text":"Natural law: what is just, tested by reason; basis of human rights; multiple conscience problem."}]},{"text":[{"text":"Savigny: volksgeist; customary law tests: natural justice, public policy, incompatibility."}]},{"text":[{"text":"Ehrlich: facts of law, living law; Pound: balancing interests; Bentham: greatest happiness, security first."}]},{"text":[{"text":"Functional (Holmes's bad man) and realist (Frank, Llewellyn, Gray: extralegal factors)."}]},{"text":[{"text":"Functions: social relationships, official authority, disputes and remedies, change. Models: consensus, conflict, open, Marxist."}]},{"text":[{"text":"Devlin; "},{"text":"Shaw v DPP","italic":true},{"text":"; "},{"text":"Knuller v DPP","italic":true},{"text":"."}]}]}],"theory":{"itemId":"73f00702-90bb-546d-a270-d21a617d25c1","question":[{"type":"paragraph","text":[{"text":"\"Law is like the proverbial elephant; you can only describe it from the perspective you choose.\" Discuss the schools of thought on the meaning of law and their relevance today."}]}]},"practice":[{"topic":"Law in Social Context: Meaning, Definitions and Schools of Thought","named":false}]}},{"kind":"note","itemId":"1c56bef5-de85-5070-9032-4183ae931012","sourceKey":"guide-topic:2","position":2,"payload":{"title":"Objectives of Law, Law and Justice, Law and the State","body":"The objectives of law (order, justice, freedom); the definitions of justice and who gave them; every type of justice with examples; the state, its elements and government; ruler and citizens, sovereignty and legitimacy; the rule of law (Dicey) and other limits on state power.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"The objectives of law (order, justice, $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 6, $study_guide$freedom); the definitions of justice and who gave them; every type of justice with examples; the state, its elements and government; ruler and citizens, sovereignty and legitimacy; the rule of law (Dicey) and other limits on state power."}],"lessons":[{"number":"2.1","title":"Objectives of law: order and freedom","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Law and order:","bold":true},{"text":" the "},{"text":"classical function of any government","bold":true},{"text":" is to maintain law and order, protect lives and property and ward off external aggression: the foremost justification for modern government. The opposite of order is anarchy and chaos, caused mainly by "},{"text":"non-enforcement","bold":true},{"text":" of law, not its absence."}]},{"text":[{"text":"Even in "},{"text":"war","bold":true},{"text":", law (the Geneva Conventions) sets minimum standards: protection for religious houses, the aged, pregnant women, children, the Red Cross and UN relief workers."}]},{"text":[{"text":"Law and freedom:","bold":true},{"text":" the desire to be free is innate. Law recognises freedom and regulates it; unrestricted freedom would destroy others' freedom. There is an irreducible minimum of liberty: "},{"text":"fundamental human rights","bold":true},{"text":" (Chapter IV, 1999 Constitution)."}]},{"text":[{"text":"Rights are not absolute:","bold":true},{"text":" they are balanced against others' rights. Freedom of speech does not cover malicious falsehood (defamation)."}]}]},{"type":"paragraph","text":[{"text":"3 limits on freedom of contract:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"a contract is "},{"text":"void","bold":true},{"text":" if it contemplates a "},{"text":"crime","bold":true},{"text":" or is contrary to "},{"text":"public policy","bold":true},{"text":";"}]},{"text":[{"text":"the law may "},{"text":"control prices","bold":true},{"text":" of essential goods;"}]},{"text":[{"text":"a trader may be barred from a "},{"text":"trade name","bold":true},{"text":" or mark closely resembling an existing one."}]}]},{"type":"paragraph","text":[{"text":"3 limits on political freedom:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"some people may not vote, e.g. infants and lunatics (sections 77(2) and 117(2): only citizens aged "},{"text":"18","bold":true},{"text":" and above may register);"}]},{"text":[{"text":"criteria for registering political parties (section 222);"}]},{"text":[{"text":"disqualification from some offices (sections 66, 107, 137, 182)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Forcing anyone to accept a trader's offer is "},{"text":"not","bold":true},{"text":" a limit on freedom of contract; freedom includes the right to refuse."}]},{"text":[{"text":"Seventeen-year-old Ifeoma turned away at voter registration suffers a "},{"text":"lawful limitation on political freedom","bold":true},{"text":": naming \"citizens aged eighteen\" excludes those below ("},{"text":"expressio unius est exclusio alterius","italic":true},{"text":")."}]},{"text":[{"text":"The degree of freedom depends on the state's political and economic system (socialist or capitalist)."}]}]}]},{"number":"2.2","title":"Law and justice: meaning and definitions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Relationship:","bold":true},{"text":" in ordinary speech law and justice are synonyms, but "},{"text":"justice is the correct application of a law, as opposed to arbitrariness","bold":true},{"text":" (Ross). "},{"text":"Law is the means; justice is the end.","bold":true}]},{"text":[{"text":"A law may be "},{"text":"legal yet unjust","bold":true},{"text":": apartheid in South Africa; racial segregation laws in the US before 1964 (school segregation was declared unconstitutional in "},{"text":"Brown v Board of Education","italic":true},{"text":" (1954))."}]},{"text":[{"text":"Wole Soyinka:","bold":true},{"text":" justice is \"the first condition of humanity.\""}]},{"text":[{"text":"Emily Thorne:","bold":true},{"text":" justice, like beauty, is "},{"text":"in the eye of the beholder","bold":true},{"text":": the winner says justice was done, the loser calls it a miscarriage of justice."}]},{"text":[{"text":"Factors shaping a person's idea of justice:","bold":true},{"text":" home background, educational qualification, religious belief, enlightened self-interest, personal idiosyncrasies, socio-political affiliation."}]}]},{"type":"table","header":[[{"text":"Thinker"}],[{"text":"Justice is"}]],"rows":[[[{"text":"Ulpian (Roman jurist; Justinian's Institutes)"}],[{"text":"\"The constant and perpetual will to render to everyone his due\""}]],[[{"text":"Thomas Aquinas"}],[{"text":"A cardinal virtue: \"a habit whereby man renders to each one his due by a constant and perpetual will\""}]],[[{"text":"Aristotle"}],[{"text":"Following laid-down rules; two-fold: "},{"text":"conduct in agreement with law","bold":true},{"text":" and "},{"text":"equality","bold":true}]],[[{"text":"Plato"}],[{"text":"When each person does that for which he or she is "},{"text":"fitted or suited","bold":true}]],[[{"text":"John Rawls ("},{"text":"A Theory of Justice","italic":true},{"text":", 1971)"}],[{"text":"Fairness","bold":true},{"text":"; \"the first virtue of social institutions, as truth is of systems of thought\""}]],[[{"text":"Professor Bix"}],[{"text":"A subset of moral concepts connected with law and politics (Lasswell: politics is \"who gets what, when and how\")"}]],[[{"text":"Josiah v The State","italic":true},{"text":" [1985]"}],[{"text":"In criminal law, a "},{"text":"three-way traffic","bold":true},{"text":": justice to the "},{"text":"state (society)","bold":true},{"text":", the "},{"text":"victim","bold":true},{"text":" and the "},{"text":"accused","bold":true}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Justice as equality according to$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 7, $study_guide$ law:","bold":true},{"text":" treating like cases alike (legal proceedings, universal adult suffrage); it reduces discrimination. But strict equality can work injustice: a mother who shares exactly equally among three children, one physically challenged."}]},{"text":[{"text":"So "},{"text":"unequal treatment can itself be justice:","bold":true},{"text":" special treatment for insanity, infancy or poverty (legal aid for the poor; scholarships for the poorest). Justice as "},{"text":"fairness or equity","bold":true},{"text":" fixes this, but what is fair is subjective."}]},{"text":[{"text":"Plato's view abused:","bold":true},{"text":" India's caste system; the Osu system in Eastern Nigeria; claims of entitlement to rule; gender ideology."}]},{"text":[{"text":"Society cannot satisfy everyone; someone wins and someone loses. Law must choose which interest prevails and balance the rest (Pound's \"interests pressing for recognition\")."}]}]}]},{"number":"2.3","title":"Typologies of justice","mustKnow":[{"type":"table","header":[[{"text":"Type"}],[{"text":"Meaning"}],[{"text":"Example"}]],"rows":[[[{"text":"Commutative","bold":true},{"text":" (Aquinas)"}],[{"text":"Fairness in dealings between two persons; private law; voluntary transactions; "},{"text":"justice of coordination","bold":true}],[{"text":"Enforcing a contract"}]],[[{"text":"Distributive","bold":true},{"text":" (Aquinas, Aristotle)"}],[{"text":"State shares honours, rewards and common goods proportionately; public law; "},{"text":"justice of subordination","bold":true},{"text":"; "},{"text":"prospective","bold":true}],[{"text":"Federal Character (section 14(3)); fuel-subsidy palliatives; derivation; local government autonomy"}]],[[{"text":"Corrective","bold":true},{"text":" (Aristotle)"}],[{"text":"Rectifies a wrong where one took from or harmed another (contract, tort, crime); "},{"text":"retrospective","bold":true}],[{"text":"Return of a stolen generator plus penalty; King Solomon and the two women; "},{"text":"FRN v P&ID","italic":true},{"text":" [2023]"}]],[[{"text":"Procedural / technical","bold":true}],[{"text":"Fairness of the "},{"text":"process","bold":true},{"text":", not the outcome; \"justice must be seen to be done\""}],[{"text":"Fair hearing, section 36"}]],[[{"text":"Formal","bold":true}],[{"text":"Judge applies the law "},{"text":"strictly","bold":true},{"text":", ignoring extra-legal factors, with "},{"text":"no discretion to soften harshness","bold":true}],[{"text":"Awolowo treasonable felony trial: \"my hands are tied\""}]],[[{"text":"Substantive / substantial","bold":true}],[{"text":"Where strict law gives absurdity or injustice, judge considers extra-judicial factors for a just "},{"text":"result","bold":true}],[{"text":"Chinwendu v Mbamali","italic":true},{"text":": justice not sacrificed on the altar of technicalities"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Aquinas:","bold":true},{"text":" commutative and distributive. "},{"text":"Aristotle:","bold":true},{"text":" corrective and distributive."}]},{"text":[{"text":"Formal justice is justified because it:","bold":true},{"text":" (1) ensures "},{"text":"clarity and certainty","bold":true},{"text":" (Lord Eldon in "},{"text":"Sheddon v Goodrich","italic":true},{"text":" (1803): \"It is better that law should be certain than that every judge should speculate upon the improvement in it\"); (2) promotes "},{"text":"impartiality and independence","bold":true},{"text":" in adjudication."}]},{"text":[{"text":"Judicial activism:","bold":true},{"text":" a judge liberally interpreting the law to advance substantive justice. This attitude produced "},{"text":"equity","bold":true},{"text":"."}]},{"text":[{"text":"Dennis Lloyd's 3 ways to substantial justice:","bold":true},{"text":" judicial discretion; legislative reforms; political or affirmative action (gender mainstreaming, youth empowerment)."}]},{"text":[{"text":"Standard of substantial justice:","bold":true},{"text":" that of a "},{"text":"reasonable man","bold":true},{"text":" ("},{"text":"Isiyaku Mohammed v Kano Native Authority","italic":true},{"text":")."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Other types:","bold":true},{"text":" "},{"text":"natural justice","bold":true},{"text":" (the rules of fair hearing: "},{"text":"audi alteram partem","italic":true},{"text":", hear the other side; "},{"text":"nemo judex in causa sua","italic":true},{"text":", no one judges his own cause); "},{"text":"legal justice","bold":true},{"text":" (justice according to the law as it stands); "},{"text":"social justice","bold":true},{"text":" (a fair spread of welfare and opportunity in society; section 17 of the Constitution founds the social order on freedom, equality and justice)."}]},{"text":[{"text":"Traps:","bold":true},{"text":" letting the judge soften harshness is "},{"text":"not","bold":true},{"text":" a justification of formal justice. Chika, whose clear ₦450,000 claim is struck out for using the wrong form, is denied "},{"text":"substantive","bold":true},{"text":" justice. A customary court that convicts Emeka without telling him the charge breaches "},{"text":"section 36","bold":true},{"text":" (procedural justice)."}]},{"text":[{"text":"Procedural justice in Nigerian practice: long-running prosecutions such as Senator Danjuma Goje's, and locus standi challenges (the petition against Oshiomhole). "},{"text":"Amaechi v INEC","italic":true},{"text":" (2008) favours substantial over technical justice."}]},{"text":[{"text":"The classic Nigerian illustration of formal justice is the treasonable felony trial of Chief Obafemi Awolowo, a popular political leader of the old Western Region, where the trial judge said \"my hands are tied\": whatever his sympathies, the law compelled conviction."}]}]}]},{"number":"2.4","title":"Law and the state","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"State (Greig, adapting the Montevideo Convention 1933):"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 8, $study_guide$,"bold":true},{"text":" \"a territorial unit, containing a stable population under the authority of its government, and recognised as being capable of entering into relations with other entities with international personality.\""}]},{"text":[{"text":"4 elements:","bold":true},{"text":" (1) a definite "},{"text":"territory","bold":true},{"text":", (2) a "},{"text":"population","bold":true},{"text":", (3) a "},{"text":"government","bold":true},{"text":", (4) "},{"text":"sovereignty","bold":true},{"text":". A written constitution or state religion is "},{"text":"not","bold":true},{"text":" an element. (Montevideo's fourth criterion is capacity to enter into relations with other states.)"}]},{"text":[{"text":"Government:","bold":true},{"text":" the structure through which human agents act for the state, which is an artificial entity; the machinery for administering the state (legislature, executive, judiciary, ministries, courts, armed forces, police)."}]},{"text":[{"text":"Section 2(1), 1999 Constitution:","bold":true},{"text":" Nigeria is \"one indivisible and indissoluble sovereign State to be known by the name of the Federal Republic of Nigeria\"; section 2(2): a federation of states and a Federal Capital Territory."}]},{"text":[{"text":"The "},{"text":"state is created by society through law","bold":true},{"text":"; law defines each organ's powers ("},{"text":"A.G. Ogun State v A.G. Federation","italic":true},{"text":" (1982)); acts beyond power are null and void."}]},{"text":[{"text":"Monopoly of legitimate use of force:","bold":true},{"text":" the state alone ordinarily uses or authorises coercion (police, military), channelled through law."}]},{"text":[{"text":"Separation of powers:","bold":true},{"text":" legislature makes, executive enforces, judiciary interprets (sections 4, 5, 6); originated with John Locke, developed by "},{"text":"Montesquieu","bold":true},{"text":" ("},{"text":"The Spirit of the Laws","italic":true},{"text":"). "},{"text":"Checks and balances:","bold":true},{"text":" e.g. the Supreme Court voiding an Act inconsistent with the Constitution."}]},{"text":[{"text":"Westphalian model","bold":true},{"text":" (treaties of 1648): "},{"text":"sovereign equality","bold":true},{"text":" of states, territorial integrity, "},{"text":"non-interference","bold":true},{"text":"."}]},{"text":[{"text":"3 modes of extinction:","bold":true},{"text":" merger (states unite); dissolution (breaks into successors); "},{"text":"annexation","bold":true},{"text":" (absorbed by another state)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Recognition","bold":true},{"text":" is politically important but "},{"text":"not strictly conclusive","bold":true},{"text":" of statehood: a breakaway region with territory, population and government but no recognition is contested, not automatically excluded."}]},{"text":[{"text":"A state does "},{"text":"not","bold":true},{"text":" lose its personality because its government is oppressive, fascist or racist; international law, as a rule, ignores internal affairs unless other states are affected."}]},{"text":[{"text":"Internationally a state is "},{"text":"one legal person","bold":true},{"text":"; federal units have no separate international personality."}]},{"text":[{"text":"Reality check: the law proclaims lofty aims (\"do justice to all manners of men\"), yet a dominant class often manipulates state machinery."}]}]}]},{"number":"2.5","title":"Ruler and citizens: sovereignty, legitimacy and the rule of law","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Absolute rule:","bold":true},{"text":" Louis XIV interrupted a judge who said \"the king and the state\" with "},{"text":"\"I am the state\"","bold":true},{"text":" (Dulaure). Rulers, and African kings seen as demi-gods, wielded absolute power based on "},{"text":"divine right","bold":true},{"text":"."}]},{"text":[{"text":"Jean Bodin","bold":true},{"text":", a French writer, introduced the doctrine of "},{"text":"sovereignty","bold":true},{"text":" into Western political theory."}]},{"text":[{"text":"4 theories to curtail rulers' power:","bold":true},{"text":" (1) "},{"text":"social contract","bold":true},{"text":" (Hobbes, Locke, Rousseau); (2) the "},{"text":"rule of law","bold":true},{"text":" (A.V. Dicey, "},{"text":"Law of the Constitution","italic":true},{"text":"); (3) "},{"text":"separation of powers","bold":true},{"text":"; (4) the "},{"text":"principle of legality","bold":true},{"text":" ("},{"text":"nullum crimen sine lege","italic":true},{"text":"). Divine right of kings is "},{"text":"not","bold":true},{"text":" one."}]},{"text":[{"text":"Popular sovereignty, section 14(2)(a):","bold":true},{"text":" \"Sovereignty belongs to the people of Nigeria from whom government through this Constitution derives all its powers and authority.\" Its ultimate expression is the power to change leaders."}]},{"text":[{"text":"Legitimacy:","bold":true},{"text":" once charismatic or traditional, now a matter of law. "},{"text":"Section 1(2):","bold":true},{"text":" no person or group may take control of the government \"except in accordance with the provisions of this Constitution.\" A failed coup is "},{"text":"treason","bold":true},{"text":" (sections 37 and 38, Criminal Code), punishable by death; the provision cannot stop a successful coup."}]},{"text":[{"text":"Farrar and Dugdale:","bold":true},{"text":" modern legitimacy rests not on mere legality but on "},{"text":"\"impersonal rational authority\"","bold":true},{"text":": the rule of law accepted both by those who run the system and by the people."}]},{"text":[{"text":"4 sources of legitimacy:","bold":true},{"text":" constitutionalism; democratic consent; rule of law; "},{"text":"performance legitimacy","bold":true},{"text":" (security, roads, hospitals delivered)."}]},{"text":[{"text":"Kelsen:","bold":true},{"text":" a law made by constitutional procedure is legitimate because it follows from hi$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 9, $study_guide$gher norms, even if many think it unjust."}]}]},{"type":"paragraph","text":[{"text":"Dicey's rule of law, 3 pillars:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Supremacy of regular law:","bold":true},{"text":" no one is punishable except for a distinct breach of law established before the ordinary courts; no arbitrary power."}]},{"text":[{"text":"Equality before the law:","bold":true},{"text":" everyone, whatever his rank, is subject to the ordinary law and courts."}]},{"text":[{"text":"The constitution is the "},{"text":"result of the ordinary law","bold":true},{"text":": rights are secured by court decisions."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Social contract:","bold":true},{"text":" Hobbes ("},{"text":"Leviathan","italic":true},{"text":", 1651): without government life is \"solitary, poor, nasty, brutish and short\", so people surrender power to a sovereign. Locke (1632-1704): government exists to protect life, liberty and property and may be resisted if it fails. Rousseau (1712-1778): sovereignty lies in the "},{"text":"general will","bold":true},{"text":" of the people."}]},{"text":[{"text":"Legality:","bold":true},{"text":" section 36(8): no one is guilty of an act that was not an offence when done; section 36(12): offences must be defined in written law ("},{"text":"Aoko v Fagbemi","italic":true},{"text":" (1961)). Bayo charged for a then-lawful act is protected by legality."}]},{"text":[{"text":"Rule of law cases:","bold":true},{"text":" detaining a trader for three weeks without charge breaches the rule of law (section 35 requires being brought before a court within a reasonable time). "},{"text":"Military Governor of Lagos State v Ojukwu","italic":true},{"text":" (1986): government must obey court orders. "},{"text":"Lakanmi","italic":true},{"text":" (1971): even military decrees were tested against law."}]},{"text":[{"text":"Louis XIV essay:","bold":true},{"text":" contrast absolute rule with today's position: sovereignty in the people (section 14(2)(a)), power limited by the Constitution, separation of powers and the rule of law; citizens hold rights (Chapter IV) and duties; legitimacy depends on consent (Osipitan and the call for a national conference)."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Order is the foremost objective; anarchy comes from non-enforcement."}]},{"text":[{"text":"Rights are not absolute: limits on contract (crime, prices, trade names) and politics (age 18, parties, disqualifications)."}]},{"text":[{"text":"Law is the means, justice the end; justice is in the eye of the beholder (Thorne); first condition of humanity (Soyinka)."}]},{"text":[{"text":"Ulpian: constant and perpetual will; Rawls: fairness; Plato: what one is fitted for; Aristotle: law plus equality."}]},{"text":[{"text":"Aquinas: commutative and distributive; Aristotle: corrective (retrospective) and distributive (prospective)."}]},{"text":[{"text":"Formal (\"my hands are tied\") vs substantive ("},{"text":"Chinwendu v Mbamali","italic":true},{"text":"; judicial activism); procedural = section 36; "},{"text":"Josiah","italic":true},{"text":": three-way traffic."}]},{"text":[{"text":"State: territory, population, government, sovereignty; recognition not conclusive; section 2(1)."}]},{"text":[{"text":"Bodin (sovereignty), Montesquieu (separation of powers), Dicey (rule of law); section 14(2)(a) and section 1(2)."}]}]}],"theory":{"itemId":"056bbef2-4eac-53f6-86c2-5f26a4949416","question":[{"type":"paragraph","text":[{"text":"\"Justice, like beauty, is in the eye of the beholder\" (Emily Thorne). Discuss the various perceptions and types of justice."}]}]},"practice":[{"topic":"Objectives of Law, Law and Justice, and the State","named":false}]}},{"kind":"note","itemId":"be2857a1-fb5c-5cf3-a3a1-fd4530fb35e4","sourceKey":"guide-topic:3","position":3,"payload":{"title":"Aspects and Classifications of Law","body":"The four types of law by origin; the six classifications (public/private, civil/criminal, substantive/procedural, municipal/international, written/unwritten, common law/equity) with definitions, examples and Nigerian statutes; burden and standard of proof; the history of equity (Earl of Oxford's case, Judicature Acts 1875); why no classification is watertight and why classification still matters.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"The four types of law by origin; the six classifications (public/private, civil/criminal, substantive/procedural, municipal/international, written/unwritten, common law/equity) with definitions, examples and Nigerian statutes; burden and standard of proof; the history of equity ("},{"text":"Earl of Oxford's case","italic":true},{"text":", Judicature Acts 1875); why no classification is watertight and why classification still matters."}],"lessons":[{"number":"3.1","title":"Types of law by origin","mustKnow":[{"type":"paragraph","text":[{"text":"Montesquieu ("},{"text":"The Spirit of the Laws","italic":true},{"text":"): laws in the widest sense are \"any necessary relation arising from the nature of things\"; all beings have their laws. So \"law\" has many uses. Classified by origin, there are "},{"text":"4 types","bold":true},{"text":":"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Eternal law:","bold":true},{"text":" constant, everlasting, universal; it has always existed and never changes. "},{"text":"St Thomas Aquinas","bold":true},{"text":" (1224-1274): law is \"the exemplar of divine wisdom as directing the motions and acts of everything\". Eternal law is the foundation of all other laws: God-given rules governing all creation."}]},{"text":[{"text":"Divine law:","bold":true},{"text":" the law of God or from God. Perfect example: the "},{"text":"Ten Commandments","bold":true},{"text":" in the Holy Bible (Exodus 20:1-17). Based on the premise that man, being sinful, cannot make a valid and just law, $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 10, $study_guide$so he must turn to God."}]},{"text":[{"text":"Natural law:","bold":true},{"text":" a body of moral rules and principles of human conduct deduced from nature and "},{"text":"discoverable by reason","bold":true},{"text":". Lord Lloyd: \"a body of objective moral principles based on the nature of the universe and discoverable by reason\". Aquinas: natural law is \"a participation of the eternal law in a rational creature\"."}]},{"text":[{"text":"Human or positive law:","bold":true},{"text":" law posited (laid down) by an authority of society, which is its sole source of validity. Studied by "},{"text":"legal positivism","bold":true},{"text":", which does not concern itself with morality."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Natural law has a "},{"text":"descriptive","bold":true},{"text":" sense (laws of gravity, planetary motion, the law that makes us sleep or hunger) and a "},{"text":"prescriptive","bold":true},{"text":" sense (a universal precept regulating human conduct). Lawyers use the prescriptive sense. Two conceptions: an ideal guide to positive law, or a "},{"text":"higher law","bold":true},{"text":" to which positive law must conform to be valid."}]},{"text":[{"text":"Lon Fuller:","bold":true},{"text":" no separation of law and morals; law is \"the enterprise of subjecting human conduct to the governance of rules\"; it must have an internal morality, be clear and certain and not retroactive. "},{"text":"Cicero","bold":true},{"text":" (1st century BC): \"True law is right reason in agreement with Nature… one eternal and unchangeable law… valid for all nations for all times.\""}]},{"text":[{"text":"Positivists: "},{"text":"Jeremy Bentham","bold":true},{"text":" (father of legal positivism: law is a command of a sovereign to subordinates), "},{"text":"John Austin","bold":true},{"text":" (law is \"a rule laid down for the guidance of an intelligent being by an intelligent being having power over him\", backed by sanction). "},{"text":"H.L.A. Hart","bold":true},{"text":" insisted there is no necessary connection between law as it is ("},{"text":"lex lata","italic":true},{"text":") and law as it ought to be ("},{"text":"de lege ferenda","italic":true},{"text":"). In "},{"text":"A.-G. Federation v Guardian Newspapers Ltd","italic":true},{"text":", Uwaifo JSC rejected judging a law's validity by ethics, morality or religion. Critics say positivism can lead to dictatorship and tyranny."}]},{"text":[{"text":"Exam trap: \"Procedural law\" is "},{"text":"not","bold":true},{"text":" a type of law by origin. A student who says CAMA is valid simply because the National Assembly enacted it, whatever its morality, is taking the "},{"text":"positivist","bold":true},{"text":" (human law) view."}]},{"text":[{"text":"Eternal law works impartially for kings and servants; divine law depends on those (popes, kings) who claim authority to interpret it and may be twisted to oppress. Natural law's big contribution: it rejected the idea that man cannot make just law, made law a matter of reason not fatalism, and inspired equality, democracy and human rights."}]}]}]},{"number":"3.2","title":"Public and private law; civil and criminal law","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Public law:","bold":true},{"text":" concerned with the protection of the state and its organs; governs the relationship between the "},{"text":"state and citizens","bold":true},{"text":", where the state is "},{"text":"'higher'","bold":true},{"text":" in legal status. Examples: constitutional law, administrative law, criminal law, international law."}]},{"text":[{"text":"Private law:","bold":true},{"text":" concerned with relationships "},{"text":"between individuals","bold":true},{"text":" and the protection of individual rights. Examples: contract, torts, family law, succession, trusts, law of evidence."}]},{"text":[{"text":"Civil law","bold":true},{"text":" (in this context): defines the rights and duties of persons to one another and gives an injured person a way to be "},{"text":"compensated","bold":true},{"text":" for another's wrongful act. Examples: contract, torts, land law, family law. Aim: recovery of money or property, or enforcement of a right."}]},{"text":[{"text":"Criminal law:","bold":true},{"text":" protects the interest of the "},{"text":"public at large","bold":true},{"text":" by "},{"text":"punishing","bold":true},{"text":" conduct believed harmful to society. Punishment: imprisonment, fine or both. The "},{"text":"State","bold":true},{"text":" prosecutes on behalf of society."}]}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Criminal case"}],[{"text":"Civil case"}]],"rows":[[[{"text":"Who sues"}],[{"text":"The State (prosecution)"}],[{"text":"The injured person (plaintiff/claimant)"}]],[[{"text":"Aim"}],[{"text":"Punishment"}],[{"text":"Compensation or enforcing a right"}]],[[{"text":"Standard of proof"}],[{"text":"Beyond reasonable doubt: "},{"text":"s.135 Evidence Act 2011","bold":true}],[{"text":"Balance of probabilities: "},{"text":"s.134 Evidence Act 2011","bold":true}]],[[{"text":"Burden of proof"}],[{"text":"Stays on the prosecution; does not shift"}],[{"text":"May shift between the parties"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Civil\" has other meanings: law that is not criminal; the law of a state as opposed to international law; to the "},{"text":"armed forces","bold":true},{"text":", everything not peculiar to the military (a civil court as opposed to a court martial)."}]},{"text":[{"text":"Balance of probabilities:","bold":true},{"text":" judgment goes to the party who proves its case more convincingly. The higher criminal standard exists "},{"text":"to protect the accused from the awesome power of the state and the danger of wrongful conviction","bold":true},{"text":"; this is the presumption of innocence, \"the one golden thread\" of criminal law ("},{"text":"Woolmington v DP$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 11, $study_guide$P","italic":true},{"text":" (1935); s.36(5) 1999 Constitution)."}]},{"text":[{"text":"Serious crimes (murder, rape, burglary) are normally tried in the "},{"text":"High Court","bold":true},{"text":"; minor offences (minor traffic offences, minor assault) are tried "},{"text":"summarily in the Magistrate Court","bold":true},{"text":". Criminal law is codified in the "},{"text":"Criminal Code","bold":true},{"text":" (Southern States) and the "},{"text":"Penal Code","bold":true},{"text":" (Northern States)."}]},{"text":[{"text":"Overlap:","bold":true},{"text":" assault, false imprisonment and defamation are both crimes and torts. If A steals B's bicycle, A is guilty of "},{"text":"stealing","bold":true},{"text":" and liable to B in the tort of "},{"text":"conversion","bold":true},{"text":". Breach of contract is "},{"text":"not","bold":true},{"text":" a crime."}]},{"text":[{"text":"France vs Nigeria:","bold":true},{"text":" France has a separate body of rules and courts for matters involving the state. Nigeria has "},{"text":"no","bold":true},{"text":" separate system; state-citizen litigation follows the same rules as private litigation. The only distinction is "},{"text":"procedural","bold":true},{"text":": special procedures apply to enforce public duties, e.g. fundamental rights enforcement (Fundamental Rights (Enforcement Procedure) Rules) and "},{"text":"judicial review","bold":true},{"text":". If the special procedure is not followed, the case "},{"text":"may be struck out","bold":true},{"text":"."}]}]}]},{"number":"3.3","title":"Substantive and procedural law; municipal and international law","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Substantive law:","bold":true},{"text":" the rules of law themselves; it states "},{"text":"rights, duties and liabilities","bold":true},{"text":", defines a code of conduct and prescribes a penalty for breach. Examples: contract, torts, criminal law, constitutional law; "},{"text":"s.419 Criminal Code","bold":true},{"text":" (obtaining goods by false pretences, with imprisonment)."}]},{"text":[{"text":"Procedural (adjectival) law:","bold":true},{"text":" the methods of proceeding by which substantive rights and duties are "},{"text":"enforced in court","bold":true},{"text":". It covers: how an action is initiated; mode of proof; giving evidence; examination of witnesses; manner of giving judgment; "},{"text":"enforcement of judgment","bold":true},{"text":". Whether conduct amounts to an offence is "},{"text":"substantive","bold":true},{"text":", not procedural."}]},{"text":[{"text":"Sources of procedural law: Rules of Court (e.g. High Court of Lagos State (Civil Procedure) Rules), Criminal Procedure Act (South) and Criminal Procedure Code (North), now largely replaced by the "},{"text":"Administration of Criminal Justice Act 2015","bold":true},{"text":" (procedural law to the Criminal and Penal Codes), the Evidence Act, the Sheriffs and Civil Process Act."}]},{"text":[{"text":"Municipal (national, domestic) law:","bold":true},{"text":" the internal law of a particular country, regulating relations between individuals and between individuals and the State. Example: the 1999 Constitution."}]},{"text":[{"text":"International law:","bold":true},{"text":" governs relations between "},{"text":"States inter se","bold":true},{"text":" or between States and "},{"text":"international organisations","bold":true},{"text":". Sources (Art. 38(1) Statute of the International Court of Justice): "},{"text":"treaties; international custom; general principles of law recognised by civilised nations; judicial decisions and teachings of the most highly qualified publicists","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"International law divides into "},{"text":"private international law (conflict of laws)","bold":true},{"text":", which handles cases inside a domestic legal system where "},{"text":"foreign elements","bold":true},{"text":" arise (two Nigerians contract in England to sell goods in London; a Nigerian court applies English law to its validity), and "},{"text":"public international law","bold":true},{"text":", which is a "},{"text":"separate system","bold":true},{"text":" altogether."}]},{"text":[{"text":"Examples of international law: the "},{"text":"African Charter on Human and Peoples' Rights","bold":true},{"text":", the Universal Declaration of Human Rights, the UN Charter. A local government bye-law is "},{"text":"not","bold":true},{"text":" a source of international law."}]},{"text":[{"text":"s.12(1) 1999 Constitution:","bold":true},{"text":" a treaty has no force of law in Nigeria until "},{"text":"enacted by the National Assembly","bold":true},{"text":". Ratification alone is not enough."}]},{"text":[{"text":"Barrister consulting Civil Procedure Rules to start a claim and serve the defendant = procedural law."}]}]}]},{"number":"3.4","title":"Written and unwritten law","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Written law","bold":true},{"text":" (technical meaning): a rule "},{"text":"formally enacted","bold":true},{"text":" into a statute by the legislature, after debate and scrutiny and assent by the chief executive. Names: "},{"text":"Codes, Statutes, Acts, Decrees, Edicts, Laws, Rules, Ordinances","bold":true},{"text":". Judicial precedents are "},{"text":"not","bold":true},{"text":" written law."}]},{"text":[{"text":"Unwritten law","bold":true},{"text":" means two things: (1) rules not written down at all, such as "},{"text":"customary law and conventions","bold":true},{"text":"; (2) "},{"text":"unenacted","bold":true},{"text":" rules even if reduced into writing, such as "},{"text":"case law","bold":true},{"text":"."}]},{"text":[{"text":"Example of an unwritten constitution: the "},{"text":"British Constitution","bold":true},{"text":". The bulk of a country's unwritten law is its customary law."}]}]}],"explainMore":[{"type":"list","ordere$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 12, $study_guide$d":false,"items":[{"text":[{"text":"Written down is not the same as written. The neighbour principle in "},{"text":"Donoghue v Stevenson","italic":true},{"text":" (1932) is printed in the law reports but is "},{"text":"unwritten law","bold":true},{"text":" because no legislature enacted it."}]},{"text":[{"text":"s.36(12) 1999 Constitution:","bold":true},{"text":" a person shall not be convicted of a criminal offence unless the offence is defined and its penalty prescribed in a "},{"text":"written law","bold":true},{"text":" (an Act of the National Assembly, a Law of a State, or subsidiary legislation). So a conviction under unwritten custom is unlawful: "},{"text":"Aoko v Fagbemi","italic":true},{"text":" [1961] 1 All NLR 400 (adultery not an offence). This effectively abolished customary criminal law."}]}]}]},{"number":"3.5","title":"Common law and equity","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Common law","bold":true},{"text":" (as a division of law): the law developed by the old common law courts of England: "},{"text":"King's Bench, Court of Common Pleas, Court of Exchequer","bold":true},{"text":". The Court of Chancery was "},{"text":"not","bold":true},{"text":" one of them."}]},{"text":[{"text":"Origin: after the "},{"text":"Norman Conquest of 1066","bold":true},{"text":", royal judges went on circuit applying local customs; meeting at Westminster, they compared customs and kept the more sensible ones, producing uniform rules for the whole realm: judge-made law found in decided cases."}]},{"text":[{"text":"Defects:","bold":true},{"text":" strict, formal, full of legalism; every action began by "},{"text":"royal writ","bold":true},{"text":"; no writ, no remedy; main remedy "},{"text":"damages","bold":true},{"text":", often ineffective."}]},{"text":[{"text":"Rise of equity:","bold":true},{"text":" unsatisfied plaintiffs petitioned the King; the "},{"text":"Lord Chancellor","bold":true},{"text":" handled the petitions; by the end of the 15th century petitions went straight to him, and his court became the "},{"text":"Court of Chancery","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Key events","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Earl of Oxford's case","bold":true,"italic":true},{"text":" (1615):","bold":true},{"text":" an assignee of a lease built a house and planted trees; the owner ejected him; the common law court gave judgment for the owner. "},{"text":"Lord Ellesmere","bold":true},{"text":", the Chancellor, granted an "},{"text":"injunction","bold":true},{"text":" restraining the owner: \"by the law of God, he that builds a house must live in it\". "},{"text":"Coke CJ","bold":true},{"text":" protested."}]},{"text":[{"text":"Lord Bacon","bold":true},{"text":" (Attorney General, later Lord Chancellor, under James I) resolved the clash for Chancery: "},{"text":"where common law and equity conflict, equity prevails","bold":true},{"text":"."}]},{"text":[{"text":"Judicature Acts","bold":true},{"text":" (in force "},{"text":"1875","bold":true},{"text":"): "},{"text":"fused the administration","bold":true},{"text":" of both in the same courts but did "},{"text":"not","bold":true},{"text":" abolish the distinction between legal and equitable rights. Nigerian courts likewise administer both."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Before 1875 a litigant with a common law right who needed an injunction had to sue "},{"text":"first at common law","bold":true},{"text":" to establish the right, "},{"text":"then in Chancery","bold":true},{"text":" for the remedy: common law courts could not grant "},{"text":"injunctions, specific performance or rescission","bold":true},{"text":", and Chancery could not award "},{"text":"damages","bold":true},{"text":". Damages is a common law remedy, not equitable."}]},{"text":[{"text":"Example: Uche signs over his car to Lola for ₦500,000. At law the contract is enforceable, but if he was induced by "},{"text":"fraud, mistake or misrepresentation","bold":true},{"text":", "},{"text":"equity","bold":true},{"text":" can rescind it. Equity mitigates the harshness of common law."}]},{"text":[{"text":"Ashburton's famous image: the two streams of jurisdiction now run in the same channel but do not mingle their waters."}]}]}]},{"number":"3.6","title":"No watertight classification; why classify","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Classifications "},{"text":"overlap","bold":true},{"text":". Land law has become largely public law since the "},{"text":"Land Use Act","bold":true},{"text":"; tax law is as much private as public; assault is a crime and a tort."}]},{"text":[{"text":"A real problem may need several subjects: an employee dismissed after a workplace accident needs "},{"text":"contract, labour law and tort","bold":true},{"text":" combined."}]},{"text":[{"text":"Importance of classification:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Subject classification: coherent study of related rules; analysing a case's issues and the applicable rules."}]},{"text":[{"text":"Common law/equity: understanding how they evolved; separating legal from equitable rights and remedies to get an adequate remedy."}]},{"text":[{"text":"Public/private: in France, the applicable law and court; in Nigeria, the right "},{"text":"procedure","bold":true},{"text":" (fundamental rights, winding-up petitions, judicial review)."}]},{"text":[{"text":"Civil/criminal: separating private injuries from public order; choosing whether to "},{"text":"sue, set the criminal process in motion, or wait for the criminal case to end before suing","bold":true},{"text":"."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Classifications should be \"the lawyer's servants, not his masters\". Matching pairs to remember: substantive v procedural = the rules themselves$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 13, $study_guide$ v how they are enforced; municipal v international = law within a country v law between states; written v unwritten = enacted v not enacted."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"By origin: eternal (Aquinas), divine (Ten Commandments), natural (reason; Lloyd, Fuller, Cicero), positive (Bentham, Austin, Hart)."}]},{"text":[{"text":"Public law: state is 'higher'; private law: between individuals."}]},{"text":[{"text":"Civil: compensation, balance of probabilities (s.134 EA 2011); criminal: punishment, beyond reasonable doubt (s.135), burden stays on prosecution."}]},{"text":[{"text":"Substantive = rights and duties; procedural = enforcement in court (ACJA 2015, Rules of Court)."}]},{"text":[{"text":"International law sources: treaties, custom, general principles, judicial decisions and publicists; treaties need enactment (s.12(1) CFRN)."}]},{"text":[{"text":"Written = enacted; case law is unwritten; s.36(12) needs written law for a crime."}]},{"text":[{"text":"Common law courts: King's Bench, Common Pleas, Exchequer. "},{"text":"Earl of Oxford's case","italic":true},{"text":" (1615): equity prevails. Judicature Acts 1875 fused administration only."}]},{"text":[{"text":"No classification is watertight, but each has practical importance."}]}]}],"theory":{"itemId":"52b0d680-0180-5709-bc2b-142dea0724a8","question":[{"type":"paragraph","text":[{"text":"\"Distinguishing in practice between one classification of law and another may not be as clear-cut as it appears in theory.\" Discuss, with reference to any four classifications of law."}]}]},"practice":[{"topic":"Aspects and Classifications of Law","named":false}]}},{"kind":"note","itemId":"7283e5e9-6327-5f9c-a547-acf8c702186a","sourceKey":"guide-topic:4","position":4,"payload":{"title":"Methods of Social Control through Law","body":"The meaning of social control and who coined it; Pound, Ross, Quinney and Elias on law; formal and informal control; why law is (or is not) the paramount agent; the seven techniques (Summers' five plus Farrar and Dugdale's two), each with its definition, Nigerian examples, cases and alternatives; the limits of law as a tool of social control.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"The meaning of social control and who coined it; Pound, Ross, Quinney and Elias on law; formal and informal control; why law is (or is not) the paramount agent; the seven techniques (Summers' five plus Farrar and Dugdale's two), each with its definition, Nigerian examples, cases and alternatives; the limits of law as a tool of social control."}],"lessons":[{"number":"4.1","title":"The idea of social control","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Social control:","bold":true},{"text":" loosely, the control of "},{"text":"social behaviour","bold":true},{"text":", that is, behaviour that "},{"text":"affects others","bold":true},{"text":". Social order is a wider, related idea; order must exist before any system of control."}]},{"text":[{"text":"The term was coined by sociologists. "},{"text":"Edward A. Ross","bold":true},{"text":" first used it for regulative institutions that keep individual behaviour in line with group demands (beliefs, ceremonies, public opinion, morals, art, education, law). "},{"text":"William G. Sumner","bold":true},{"text":" used it to show how "},{"text":"folkways","bold":true},{"text":" (habits and custom) control conduct."}]},{"text":[{"text":"Otite and Ogionwo:","bold":true},{"text":" social control is the various means by which a society exercises authority over its members and enforces conformity to its norms."}]},{"text":[{"text":"Roscoe Pound:","bold":true},{"text":" law is \""},{"text":"social control through the systematic application of the force of politically organised society","bold":true},{"text":"\"; \"in the modern world law has become the "},{"text":"paramount agent","bold":true},{"text":" of social control\". His "},{"text":"social engineering","bold":true},{"text":" idea: law as a tool for "},{"text":"balancing and harmonising competing social interests","bold":true},{"text":"."}]},{"text":[{"text":"Ross:","bold":true},{"text":" law is \"the most specialised and highly finished engine of control employed by society\"."}]},{"text":[{"text":"Quinney:","bold":true},{"text":" the legal system is the most explicit form of social control. Law consists of "},{"text":"3 elements","bold":true},{"text":": (1) specific rules of conduct; (2) planned use of sanctions to support the rules; (3) designated officials to interpret and enforce the rules. Law grows more important as societies grow more complex."}]},{"text":[{"text":"Elias:","bold":true},{"text":" the law of a community is \"the body of rules regulating human conduct regarded as obligatory or binding by its members\" (it covers customary law too)."}]}]},{"type":"table","header":[[{"text":"Formal control"}],[{"text":"Informal control"}]],"rows":[[[{"text":"Law: rules, sanctions, courts, police, prisons"}],[{"text":"Ridicule, gossip, ostracism, censure (used spontaneously)"}]]]},{"type":"paragraph","text":[{"text":"Advantages of law","bold":true},{"text":" over other instruments (public opinion, religion, morality, custom): "},{"text":"wealth of detailed rules; explicit sanctions; regularised procedure; organised institutions and machinery for enforcement","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Functions of law as an instrument of social control:","bold":true},{"text":" maintains public order and suppresses deviant behaviour; facilitates co-operative action; constitutes and regulates the principal organs of power; communicates, regulates and reinforces social values."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Pound admitted law is not the only agency: household, church, school, trade and professional associations all help, \"but the brunt of the task falls on the legal order\"."}]},{"text":[{"text":"Village$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 14, $study_guide$rs refusing to trade with a family or let children mix with them = "},{"text":"informal control by ostracism","bold":true},{"text":", not a legal technique. Imprisonment after trial is formal."}]},{"text":[{"text":"Nwabueze:","bold":true},{"text":" social control is a means to an end, "},{"text":"social justice","bold":true},{"text":"; it prevents undue concentration of wealth and exploitation; \"an unregulated freedom of private enterprise is nothing but social anarchy\"."}]},{"text":[{"text":"Otite and Ogionwo's sociological sanctions: physical (punishment, expulsion, extermination), economic, psychological and anticipated sanctions."}]}]}]},{"number":"4.2","title":"The seven techniques; the penal technique and its alternatives","mustKnow":[{"type":"paragraph","text":[{"text":"Robert S. Summers","bold":true},{"text":" gave "},{"text":"5","bold":true},{"text":" basic techniques: penal, grievance-remedial, private arranging, administrative-regulatory, public-benefit conferral. "},{"text":"Farrar and Dugdale","bold":true},{"text":" added "},{"text":"2","bold":true},{"text":": "},{"text":"constitutive","bold":true},{"text":" and "},{"text":"fiscal","bold":true},{"text":", and renamed the last one "},{"text":"conferral of social benefits","bold":true},{"text":". The "},{"text":"7","bold":true},{"text":":"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Penal"}]},{"text":[{"text":"Grievance-remedial"}]},{"text":[{"text":"Private arranging"}]},{"text":[{"text":"Constitutive"}]},{"text":[{"text":"Administrative-regulatory"}]},{"text":[{"text":"Fiscal"}]},{"text":[{"text":"Conferral of social benefits (public benefit conferral)"}]}]},{"type":"paragraph","text":[{"text":"\"Judicial precedent technique\", \"warning\" and \"compounding\" are "},{"text":"not","bold":true},{"text":" among the seven. The techniques are found in "},{"text":"both legislation and judge-made law","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Penal technique:","bold":true},{"text":" spells out "},{"text":"prohibited conduct, the penalty for breach, the procedure for determining guilt and the appropriate punishment","bold":true},{"text":". The State plays the active role. The "},{"text":"criminal justice system","bold":true},{"text":" applies it: rules on criminal acts and omissions, the "},{"text":"Police","bold":true},{"text":" and other enforcement agencies, "},{"text":"prisons","bold":true},{"text":" and detention centres. (Insurance companies are not part of it.)"}]},{"text":[{"text":"Substantive law: Criminal Code (South), Penal Code (North), other statutes, Sharia codes in some Northern States. Procedure: Criminal Procedure Act and Criminal Procedure Code (now largely the ACJA 2015)."}]}]},{"type":"paragraph","text":[{"text":"Alternatives to the penal system (4):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Non-intervention:","bold":true},{"text":" society cannot and should not criminalise every immoral act; the legislature chooses. "},{"text":"Aoko v Fagbemi","italic":true},{"text":" [1961] 1 All NLR 400: adultery not a crime because it was "},{"text":"not defined, with its penalty prescribed, in any written law","bold":true},{"text":" (s.36(12) 1999 Constitution). Police also encourage family members in minor matters to settle privately."}]},{"text":[{"text":"Warning or caution:","bold":true},{"text":" for child or petty offenders; a judge warns a noisy spectator instead of committing him for contempt; binding-over orders."}]},{"text":[{"text":"Reciprocity and self-help:","bold":true},{"text":" \"an eye for an eye\"; Farrar and Dugdale call it \"a symptom of an underdeveloped system\". Mob \"jungle justice\" is dangerous: an "},{"text":"innocent person may be punished without fair hearing","bold":true},{"text":", and the perpetrators are liable civilly and criminally."}]},{"text":[{"text":"Compounding:","bold":true},{"text":" receiving property or other consideration in return for an agreement "},{"text":"not to prosecute","bold":true},{"text":". It needs a "},{"text":"compromise between offender and complainant","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"How the penal technique controls: the victim reports to the police "},{"text":"instead of taking vengeance","bold":true},{"text":"; police investigate; the police or the "},{"text":"Attorney-General","bold":true},{"text":" (ss.174 and 211 CFRN) decide whether to prosecute; the accused gets a fair hearing; guilt must be proved beyond reasonable doubt; punishment is fine, imprisonment or death."}]},{"text":[{"text":"It applies to all, high and low, and the "},{"text":"statute of limitation does not run against crime","bold":true},{"text":": fraud from 12 years ago can still be prosecuted. Civil actions, by contrast, become statute-barred after about 5, 6 or 10 years depending on the claim."}]},{"text":[{"text":"Compounding examples: relatives of an accident victim drop charges when the driver promises ₦150,000; Mr A drops a burglary case on finding his cousin was the burglar; an employer dismisses a fraudulent employee instead of prosecuting. "},{"text":"Oputa JSC","bold":true},{"text":" in "},{"text":"Federal Civil Service Commission v Laoye","italic":true},{"text":" [1989] 2 NWLR (Pt 106) 652: justice is reached through finding the truth, and the instrument for finding the truth of a criminal charge is "},{"text":"trial in open court","bold":true},{"text":"; prosecute first, dismiss after."}]},{"text":[{"text":"Problem trap: a cashier refunds stolen co-operative funds and begs, but the society's committee insists on prosecution. Compounding is "},{"text":"unavailable","bold":true},{"text":" because there is no compromise with the complainant."}]}]}]},{"number":"4.3","title":"The grievance-remedial technique and its alternatives","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Summers$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 15, $study_guide$:","bold":true},{"text":" it \""},{"text":"defines remediable grievances, specifies remedies… and provides for enforcement of remedial awards","bold":true},{"text":"\". It operates mainly in "},{"text":"civil law","bold":true},{"text":": contract, family law, commercial law, torts, property, equity and trusts, labour law (not criminal law). Procedure: civil procedure, civil remedies, legal advice and aid."}]},{"text":[{"text":"Remedies:","bold":true},{"text":" general damages, special damages, specific performance, injunction, "},{"text":"restitutio in integrum","italic":true},{"text":". Imprisonment is "},{"text":"not","bold":true},{"text":" one."}]},{"text":[{"text":"Logical basis:","bold":true},{"text":" an adequately remedied person is pacified, which discourages injustice and stops people taking the law into their own hands."}]}]},{"type":"paragraph","text":[{"text":"Alternatives (4):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Penal technique:","bold":true},{"text":" some wrongs are crimes and torts (assault, false imprisonment, defamation). "},{"text":"Rule in ","bold":true},{"text":"Smith v Selwyn","bold":true,"italic":true},{"text":" [1914] 3 KB 98:","bold":true},{"text":" where the wrong is a "},{"text":"felony","bold":true},{"text":", no tort action until the defendant has been "},{"text":"prosecuted or a reasonable excuse is shown","bold":true},{"text":" for not prosecuting. Applied in "},{"text":"Nwankwo v Ajaegbu","italic":true},{"text":" (1978); not followed in "},{"text":"Tika Tore Press Ltd v Umar","italic":true},{"text":" [1968] and "},{"text":"Panthinsan v Edet","italic":true},{"text":" [1968]; described as \"archaic\" and \"anachronistic\"."}]},{"text":[{"text":"Private settlement:","bold":true},{"text":" e.g. a "},{"text":"liquidated damages clause","bold":true},{"text":" stating exactly what a defaulter pays."}]},{"text":[{"text":"Insurance:","bold":true},{"text":" drivers with cover refer a collision to their insurers."}]},{"text":[{"text":"Arbitration:","bold":true},{"text":" where a contract has an arbitration clause, going to court first is "},{"text":"premature","bold":true},{"text":"; courts set aside awards only within narrow limits."}]}]},{"type":"paragraph","text":[{"text":"Worked example (liquidated damages):","bold":true},{"text":" clause = ₦50,000 per day late; delivery 3 days late. Payable = 3 × ₦50,000 = "},{"text":"₦150,000","bold":true},{"text":", paid without litigation."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Advantages of arbitration","bold":true},{"text":" (Lusk): (1) much quicker disposal; (2) an arbitrator familiar with the technical background can be chosen; (3) informal, so lawyers are not essential; (4) less executive time and lower costs. Also "},{"text":"secrecy and informality","bold":true},{"text":", and amicable resolution that keeps harmony. Trap: it is "},{"text":"not always cheaper","bold":true},{"text":"; setting an award aside in court adds cost."}]}]}]},{"number":"4.4","title":"The private arranging and constitutive techniques","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Private arranging:","bold":true},{"text":" the law provides a "},{"text":"framework of rules for the validity of private transactions","bold":true},{"text":", leaving individuals to arrange their affairs within it. Mainly civil law: contract, family, commercial, property, partnership, company law, trusts. Examples: "},{"text":"marriage, settling a trust, making a will","bold":true},{"text":"."}]},{"text":[{"text":"Will:","bold":true},{"text":" in writing (no special form), "},{"text":"signed by the testator in the presence of at least two witnesses present at the same time","bold":true},{"text":", who attest and subscribe. Otherwise invalid, and property passes under the rules of "},{"text":"intestacy","bold":true},{"text":"."}]},{"text":[{"text":"Marriage:","bold":true},{"text":" free choice of Marriage Act, customary or Islamic marriage, but a person in a "},{"text":"subsisting statutory marriage cannot validly contract another marriage under any system","bold":true},{"text":" (Marriage Act)."}]},{"text":[{"text":"Constitutive technique","bold":true},{"text":" (added by Farrar and Dugdale): its distinctive feature is the "},{"text":"creation of a new legal person","bold":true},{"text":" separate from its members, which brings "},{"text":"perpetual succession and limited liability","bold":true},{"text":". It is an "},{"text":"offshoot","bold":true},{"text":" of private arranging: no one must form a company, but those who do must meet the law's requirements, so it \"takes off where private arranging stops\"."}]},{"text":[{"text":"Salomon v Salomon & Co Ltd","bold":true,"italic":true},{"text":" [1897] AC 22 (House of Lords):","bold":true},{"text":" a duly incorporated company is a legal person "},{"text":"separate and distinct from its members","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Salomon facts:","bold":true},{"text":" Salomon sold his boot business (1892) to a company formed with his wife and five children (7 members then required) for £39,000: £10,000 in secured debentures, 20,000 £1 shares, £9,000 cash. He held 2,001 of 2,007 shares. On liquidation, assets £10,000, liabilities £17,000 (£10,000 owed to Salomon). The trial court and Court of Appeal called the company a sham; the House of Lords unanimously reversed: the company was a separate person and Salomon, a "},{"text":"secured debenture holder","bold":true},{"text":", was paid first. Lord Halsbury LC: \"Either the company was a legal entity or it was not.\" The principle is not a licence for fraud."}]},{"text":[{"text":"Shareholders of a failed company are generally not personally liable for its debts (Salomon)."}]},{"text":[{"text":"Used by government too: statutory corporations, universities, agencies; and for religious and cultural bodies$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 16, $study_guide$ as "},{"text":"incorporated trustees","bold":true},{"text":" (CAMA). Groups recognised "},{"text":"without","bold":true},{"text":" legal personality: partnerships, labour unions, "},{"text":"political parties","bold":true},{"text":", professional bodies."}]},{"text":[{"text":"Government intervention in private arranging:","bold":true},{"text":" Child Rights Act 2003; sale of goods; "},{"text":"Land Use Act","bold":true},{"text":" (Governor's consent to assign or mortgage a right of occupancy); "},{"text":"Hire Purchase Act 1965, s.9","bold":true},{"text":": once "},{"text":"three-fifths (3/5)","bold":true},{"text":" of the hire-purchase price is paid, the owner can recover the goods "},{"text":"only by court action","bold":true},{"text":". Before the Act, seizure was lawful in "},{"text":"Atere v Amao","italic":true},{"text":" (1957) (£10 of £1,332 unpaid) and "},{"text":"Sanyaolu v Bentworth Finance","italic":true},{"text":" (1972) (£100 of £5,486 unpaid)."}]}]},{"type":"paragraph","text":[{"text":"Worked example (the 3/5 rule):","bold":true},{"text":" price ₦4,000,000; paid ₦2,600,000. Fraction paid = 2,600,000 ÷ 4,000,000 = 0.65 (65%). Threshold = 3/5 × 4,000,000 = ₦2,400,000 (60%). 65% is more than 60% (but less than three-quarters), so the owner may recover only by "},{"text":"court action","bold":true},{"text":". Method: divide amount paid by total price and compare with 0.6. In "},{"text":"Atere","italic":true},{"text":", paid fraction = 1,322 ÷ 1,332 ≈ 99.2%; in "},{"text":"Sanyaolu","italic":true},{"text":", 5,386 ÷ 5,486 ≈ 98.2% (rounded to one decimal place): under s.9 both owners would now need a court order."}]}]},{"number":"4.5","title":"Administrative-regulatory, fiscal and social benefit techniques","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Administrative-regulatory:","bold":true},{"text":" government agencies "},{"text":"adopt regulatory standards, communicate them to private operators and ensure compliance","bold":true},{"text":". Steps: "},{"text":"licensing, inspection, warning letters, revocation of licence","bold":true},{"text":", then administrative proceedings, civil litigation or "},{"text":"criminal prosecution as the last resort","bold":true},{"text":". Examples: Ministry of Education permit for a private school; "},{"text":"NAFDAC","bold":true},{"text":" approval before producing consumables; Standards Organisation of Nigeria; DPR; Weights and Measures; "},{"text":"NCC","bold":true},{"text":" licences for mobile telephone operators."}]},{"text":[{"text":"Fiscal:","bold":true},{"text":" taxation's classical aim is revenue; it is also used to "},{"text":"redistribute income, stimulate economic growth and discourage anti-social behaviour","bold":true},{"text":". Examples: the 1998 budget raised the penalty for "},{"text":"gas flaring by 1,900 per cent","bold":true},{"text":"; income tax and capital transfer tax narrow the gap between haves and have-nots. Tax administration by the federal and State revenue authorities, and customs and excise laws, also serve the fiscal technique."}]},{"text":[{"text":"Conferral of social benefits:","bold":true},{"text":" government provides "},{"text":"social amenities and welfare","bold":true},{"text":" (roads, education, electricity, housing, health care, social security) "},{"text":"without directly regulating conduct","bold":true},{"text":", expecting improved welfare to bring order and prevent apathy and strife."}]}]},{"type":"table","header":[[{"text":"Comparison"}],[{"text":"Administrative-regulatory"}],[{"text":"Other technique"}]],"rows":[[[{"text":"v penal"}],[{"text":"Regulates "},{"text":"wholesome","bold":true},{"text":" activities"}],[{"text":"Prohibits and sanctions anti-social conduct"}]],[[{"text":"v grievance-remedial"}],[{"text":"Preventive","bold":true},{"text":": acts before a grievance arises"}],[{"text":"Remedies after the wrong (e.g. consumer sues a negligent manufacturer)"}]]]},{"type":"paragraph","text":[{"text":"Worked example (percentage increase):","bold":true},{"text":" an increase of 1,900% means new = old × (1 + 1,900/100) = old × 20. A penalty of 50 kobo per unit would become ₦10."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Food regulator inspecting factories = administrative-regulatory; a sick consumer suing = grievance-remedial."}]},{"text":[{"text":"Social benefit programmes: Nomadic Education, National Mass Literacy, Low Cost Housing, National Primary Health Care, People's Bank, NDE, FEAP, OMPADEC, "},{"text":"NDDC","bold":true},{"text":", NAPEP, NEEDS. "},{"text":"Weakness:","bold":true},{"text":" poor implementation and "},{"text":"hijacking by elites","bold":true},{"text":", so only crumbs reach the target group."}]},{"text":[{"text":"The "},{"text":"AGABA problem","bold":true},{"text":" (promoters sell an unapproved baby drug; children die; promoters hide behind the company) turns on the "},{"text":"administrative-regulatory","bold":true},{"text":" (no NAFDAC approval) and "},{"text":"constitutive","bold":true},{"text":" ("},{"text":"Salomon","italic":true},{"text":" is not a shield for fraud) techniques. A Niger Delta unrest problem turns on "},{"text":"conferral of social benefits","bold":true},{"text":" and "},{"text":"fiscal","bold":true},{"text":" techniques."}]}]}]},{"number":"4.6","title":"Overlap of techniques and limits of law","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The techniques "},{"text":"overlap and complement","bold":true},{"text":" each other; government may "},{"text":"combine","bold":true},{"text":" them, choosing the mix that best achieves its aim. They show the two main sources of modern law: legislation and judge-made law."}]},{"text":[{"text":"Limits of law","bold":true},{"text":" (why some sociologists deny it is paramount): some laws are seen "},{"text":"in breach more than in enforcement","bold":true},{"text":"; "},{"text":"dead-letter laws","bold":true},{"text":" in the st$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 17, $study_guide$atute books; enforcement does not always prevent the evil and may create new problems; "},{"text":"discretion of enforcement agencies","bold":true},{"text":". Law's explicit sanctions are a strength, not a limit."}]},{"text":[{"text":"Law cannot punish every immoral act (non-intervention); law is not the only agency (Pound); a law far out of step with popular conduct is \"doomed as an instrument of social control\" (Ehrlich)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Pound's limits of effective legal action:","bold":true},{"text":" difficulty of ascertaining facts; many moral duties (such as gratitude) are too intangible to enforce; some injuries are too subtle (feelings, privacy); many relations (family life) lie beyond legal action; and law needs an external agency or person to set it in motion."}]},{"text":[{"text":"In Nigeria, rising crime (419 fraud, kidnapping, corruption, trafficking) shows the penal technique's weakness in "},{"text":"enforcement","bold":true},{"text":", not in its rules. Welfare laws fail without funding and honest implementation."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Social control: control of behaviour affecting others; coined by Ross; Sumner's folkways."}]},{"text":[{"text":"Pound: \"social control through the systematic application of the force of politically organised society\"; paramount agent; social engineering balances interests."}]},{"text":[{"text":"Quinney's 3 elements; Ross's \"highly finished engine\"; Elias's definition."}]},{"text":[{"text":"Seven techniques: Summers' five plus Farrar and Dugdale's constitutive and fiscal."}]},{"text":[{"text":"Penal alternatives: non-intervention ("},{"text":"Aoko v Fagbemi","italic":true},{"text":"), warning, self-help, compounding ("},{"text":"FCSC v Laoye","italic":true},{"text":")."}]},{"text":[{"text":"Grievance-remedial alternatives: penal ("},{"text":"Smith v Selwyn","italic":true},{"text":"), private settlement, insurance, arbitration."}]},{"text":[{"text":"Private arranging (wills, marriage; HP Act 3/5); constitutive ("},{"text":"Salomon","italic":true},{"text":")."}]},{"text":[{"text":"Administrative-regulatory is preventive (NAFDAC, NCC); fiscal (gas flaring +1,900%); social benefits (NDDC; elite hijacking)."}]},{"text":[{"text":"Techniques overlap; law has limits."}]}]}],"theory":{"itemId":"5fb8404d-f31e-5259-bfd9-fd3c3cd9fd53","question":[{"type":"paragraph","text":[{"text":"Analysing the role of law as an instrument of social control, discuss any four methods of social control through law, with Nigerian examples."}]}]},"practice":[{"topic":"Methods of Social Control through Law","named":false}]}},{"kind":"note","itemId":"e6c9276a-f7c1-5827-be27-660ceefab03c","sourceKey":"guide-topic:5","position":5,"payload":{"title":"Fact Finding and Dispute Resolution","body":"Adjudicatory and non-adjudicatory methods; adversarial and inquisitorial fact finding with their merits and demerits; burden and standard of proof, res ipsa loquitur, shifting of fact and law; the four forms of ADR plus negotiation; old and customary methods.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"Adjudicatory and non-adjudicatory methods; adversarial and inquisitorial fact finding with their merits and demerits; burden and standard of proof, res ipsa loquitur, shifting of fact and law; the four forms of ADR plus negotiation; old and customary methods."}],"lessons":[{"number":"5.1","title":"Settling disputes; the adjudicatory method","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Bringing an end\" to a dispute differs from \"settling\" or \"resolving\" it. A parent who confiscates a toy two boys are fighting over ends the quarrel but resolves nothing."}]},{"text":[{"text":"Old methods:","bold":true},{"text":" in the Middle Ages disputes were \"resolved\" by "},{"text":"ordeal","bold":true},{"text":" (burning hands in fire, throwing a baby of doubtful legitimacy into a river); surviving unscathed proved innocence. This is "},{"text":"\"proof\"","bold":true},{"text":" as opposed to "},{"text":"trial","bold":true},{"text":". "},{"text":"Trial by ordeal is prohibited by the Criminal Code.","bold":true}]},{"text":[{"text":"Decisions are respected when based on "},{"text":"objective standards and standard procedures","bold":true},{"text":", not the adjudicator's whims."}]},{"text":[{"text":"2 modern methods:","bold":true},{"text":" (1) "},{"text":"adjudicatory","bold":true},{"text":" (litigation); (2) "},{"text":"non-adjudicatory","bold":true},{"text":" (Alternative Dispute Resolution, ADR)."}]},{"text":[{"text":"Adjudicatory method:","bold":true},{"text":" the dispute goes to a "},{"text":"court","bold":true},{"text":" or tribunal established by law; a judge, magistrate or adjudicator "},{"text":"assigned by the state","bold":true},{"text":" decides for one party. It is "},{"text":"formal","bold":true},{"text":": parties and witnesses appear before formal institutions. The decision is "},{"text":"binding and self-executing","bold":true},{"text":" (needs no other tribunal to give it force of law)."}]},{"text":[{"text":"The judge must "},{"text":"first ascertain the facts, then apply the law.","bold":true},{"text":" The "},{"text":"2 methods of fact finding:","bold":true},{"text":" "},{"text":"adversarial","bold":true},{"text":" and "},{"text":"inquisitorial","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Regular courts normally use the adversarial method; many Nigerian "},{"text":"tribunals and panels","bold":true},{"text":" (disciplinary, examination malpractice, benefits tribunals) are "},{"text":"semi-inquisitorial","bold":true},{"text":"."}]},{"text":[{"text":"Ajegunle co-tenants problem:","bold":true},{"text":" Mrs A wants to find who stole her jewellery by \"tying the Holy Book with a key\" and calling each name; Mrs C refuses, so the others call her the thief. Advic$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 18, $study_guide$e: the method is like the old ordeals and is "},{"text":"outlawed","bold":true},{"text":"; Mrs C was right to refuse and "},{"text":"her refusal is not proof of guilt","bold":true},{"text":". Report to the police (proof beyond reasonable doubt in court), or, as neighbours with a continuing relationship, use mediation by elders."}]}]}]},{"number":"5.2","title":"The adversarial method","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Adversarial (accusatorial) method:","bold":true},{"text":" "},{"text":"each party and his lawyer","bold":true},{"text":" control how facts are collected and presented; the parties appear as "},{"text":"adversaries","bold":true},{"text":"."}]},{"text":[{"text":"A witness's evidence:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Examination-in-chief:","bold":true},{"text":" a party calls his own witness to establish evidence material to his case."}]},{"text":[{"text":"Cross-examination:","bold":true},{"text":" by the other side, to "},{"text":"weaken, neutralise and demolish","bold":true},{"text":" the case of the party who called the witness. "},{"text":"A witness not cross-examined is taken as admitted.","bold":true}]},{"text":[{"text":"Re-examination:","bold":true},{"text":" lets the witness "},{"text":"explain any seeming inconsistency","bold":true},{"text":" arising from cross-examination."}]}]}]},{"text":[{"text":"Judge = umpire","bold":true},{"text":", enforcing "},{"text":"ground rules","bold":true},{"text":": (1) hearsay is inadmissible; (2) no leading questions to "},{"text":"your own","bold":true},{"text":" witness; (3) no taking the other side by surprise."}]},{"text":[{"text":"The judge "},{"text":"must not descend into the arena","bold":true},{"text":" to find evidence, even facts he knows. If a vital witness is not called, he can do nothing; he cannot call his own witnesses and may question a witness "},{"text":"only to clarify an ambiguity","bold":true},{"text":"."}]},{"text":[{"text":"Level playing ground:","bold":true},{"text":" same rules for both; civil cases decided on the "},{"text":"balance of probability","bold":true},{"text":": if the scale of justice tilts "},{"text":"51%","bold":true},{"text":" to one party, he wins. "},{"text":"2 modifications:","bold":true},{"text":" criminal procedure; res ipsa loquitur."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A judge in a ₦2,500,000 contract suit who privately knows of a decisive witness that neither counsel called must "},{"text":"decide on the evidence presented","bold":true},{"text":"."}]},{"text":[{"text":"Bassef Orji","bold":true},{"text":" (charged with murder, found with roasted human flesh, says it came from accident victims): the prosecution did not cross-examine him on this defence or call a vital witness. The judge "},{"text":"cannot call the witness","bold":true},{"text":"; the "},{"text":"unchallenged defence stands","bold":true},{"text":" and doubt favours Bassef."}]}]}]},{"number":"5.3","title":"Standard of proof; criminal cases; res ipsa loquitur","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Civil:","bold":true},{"text":" balance of probabilities. "},{"text":"Criminal:","bold":true},{"text":" "},{"text":"beyond reasonable doubt","bold":true},{"text":" (Evidence Act 2011: s.134 civil, s.135 criminal)."}]},{"text":[{"text":"In criminal cases the prosecution discloses its evidence before trial; the accused need not disclose his defence."}]},{"text":[{"text":"Section 35(2), 1999 Constitution:","bold":true},{"text":" \"Any person who is arrested or detained shall have the right to remain silent or avoid answering any question until after consultation with a legal practitioner or any other person of his own choice.\""}]},{"text":[{"text":"Section 36(5), 1999 Constitution:","bold":true},{"text":" \"Every person who is charged with a criminal offence shall be presumed to be innocent until he is proved guilty.\" (Formerly s.33(5), 1979 Constitution.)"}]},{"text":[{"text":"The burden stays on the prosecution and "},{"text":"never shifts","bold":true},{"text":"; it must prove every ingredient and negate available defences, except matters peculiarly within the accused's knowledge."}]},{"text":[{"text":"Woolmington v DPP","italic":true},{"text":" (1935): there is no burden on the prisoner to prove his innocence; \"it is sufficient for him to raise a doubt as to his guilt.\""}]},{"text":[{"text":"State v Keji Amusan","italic":true},{"text":" (1982): \"suspicion, no matter how grave, can never ground a conviction.\""}]},{"text":[{"text":"Res ipsa loquitur = \"the facts speak for themselves\"","bold":true},{"text":": a rule of evidence affecting the burden of proof, to help accident victims. Classic statement by "},{"text":"Erle CJ","bold":true},{"text":" in "},{"text":"Scott v London and St Katherine Docks Co","italic":true},{"text":" (1865)."}]},{"text":[{"text":"Effect:","bold":true},{"text":" the "},{"text":"defendant","bold":true},{"text":" must show "},{"text":"a specific cause or that he used reasonable care","bold":true},{"text":". The plaintiff proves only that an accident happened and he was the victim, not its exact cause or the person responsible."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Policy: better nine guilty go free than one innocent be punished; the presumption of innocence is a "},{"text":"declaration of social policy","bold":true},{"text":"."}]},{"text":[{"text":"Kunle, last seen near the till after a quarrel, charged with stealing ₦450,000: mere suspicion, so "},{"text":"acquit","bold":true},{"text":"; he need not prove he did not take it."}]},{"text":[{"text":"Refusing to answer police questions until a lawyer arrives = "},{"text":"s.35(2)","bold":true},{"text":", not s.36(5)."}]},{"text":[{"text":"Res ipsa examples: an aircraft crash, collapsing scaffolding, a "},{"text":"swab left inside a patient after an$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 19, $study_guide$ abdominal operation","bold":true},{"text":" ("},{"text":"Mahon v Osborne","italic":true},{"text":", 1939). In such a case the "},{"text":"hospital","bold":true},{"text":" must explain."}]}]}]},{"number":"5.4","title":"Facts; shifting of fact and law","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Fact","bold":true},{"text":" (Evidence Act; s.258(1) Evidence Act 2011, formerly s.2(1)) includes: (a) anything, state of things or relation of things capable of being perceived by the senses; (b) "},{"text":"any mental condition of which any person is conscious.","bold":true}]},{"text":[{"text":"Whoever wants judgment on facts he asserts must prove they exist (s.131(1) Evidence Act 2011; "},{"text":"Elemo v Omolade","italic":true},{"text":", 1968)."}]},{"text":[{"text":"Nwadialo's 2 senses of \"burden of proof\":","bold":true},{"text":" (1) "},{"text":"legal burden","bold":true},{"text":": to establish the whole case to the required standard; (2) "},{"text":"evidential burden","bold":true},{"text":": to adduce evidence on a particular fact or issue. "},{"text":"Shifting of fact = shifting of the evidential burden","bold":true},{"text":"; in civil cases it moves with the "},{"text":"pleadings","bold":true},{"text":"."}]},{"text":[{"text":"Facts in issue (civil):","bold":true},{"text":" the facts a plaintiff must prove to establish his claim, "},{"text":"unless admitted","bold":true},{"text":" expressly or by implication (Aguda)."}]},{"text":[{"text":"Affirmanti non neganti incumbit probatio","bold":true,"italic":true},{"text":":","bold":true},{"text":" the burden lies on the one who "},{"text":"affirms","bold":true},{"text":", not the one who denies."}]},{"text":[{"text":"Confessing and avoiding:","bold":true},{"text":" the defendant admits the allegation but pleads "},{"text":"new facts","bold":true},{"text":" changing its complexion; "},{"text":"he","bold":true},{"text":" must prove them."}]},{"text":[{"text":"4 exceptions shifting a burden to the accused:","bold":true},{"text":" (1) defence of "},{"text":"exemption or qualification","bold":true},{"text":" from the law creating the offence; (2) a "},{"text":"statute","bold":true},{"text":" places the onus on him; (3) "},{"text":"special facts within his knowledge","bold":true},{"text":"; (4) "},{"text":"intoxication or insanity","bold":true},{"text":"."}]},{"text":[{"text":"Shifting of law:","bold":true},{"text":" "},{"text":"ignorantia facti excusat, ignorantia juris non excusat","bold":true,"italic":true},{"text":" = ignorance of fact excuses; ignorance of law does not. If a party relies on a law unaware it was amended or repealed, the burden of informing the court falls on "},{"text":"the person who knows","bold":true},{"text":"."}]},{"text":[{"text":"Jura novit curia","bold":true,"italic":true},{"text":" = \"it is for the court to know the law\": if counsel fail to cite a relevant law, the burden "},{"text":"shifts to the judge","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Emeka sues Bayo for the ₦60,000 balance of a ₦150,000 laptop. Bayo "},{"text":"admits","bold":true},{"text":" the promise: Emeka is "},{"text":"discharged","bold":true},{"text":" from proving it. Bayo "},{"text":"denies","bold":true},{"text":" it: Emeka must prove it. Emeka produces a "},{"text":"memorandum signed by Bayo","bold":true},{"text":": the evidential burden shifts to "},{"text":"Bayo","bold":true},{"text":" to show it is not genuine."}]},{"text":[{"text":"A tenant sued for ₦300,000 rent who admits it was due but says he paid the agent is "},{"text":"confessing and avoiding","bold":true},{"text":"; the "},{"text":"tenant","bold":true},{"text":" proves payment."}]},{"text":[{"text":"Adenle v Oyegbade","italic":true},{"text":" (1967): where both sides accept land was originally family land, the onus is on whoever claims "},{"text":"exclusive","bold":true},{"text":" entitlement."}]},{"text":[{"text":"Okagbue v COP","italic":true},{"text":" (1965): the accused need not prove innocence. Simply pleading not guilty shifts nothing."}]},{"text":[{"text":"Shift of fact occurs at the hearing; shift of law at the "},{"text":"address stage","bold":true},{"text":", between counsel. "},{"text":"Ignorantia judicis est calamitas innocentis","bold":true,"italic":true},{"text":": the ignorance of the judge is the calamity of the innocent."}]}]}]},{"number":"5.5","title":"Adversarial versus inquisitorial","mustKnow":[{"type":"paragraph","text":[{"text":"Adversarial advantages (5):","bold":true},{"text":" (1) reduces adjudicator "},{"text":"bias","bold":true},{"text":", and a perverse judgment can be reversed on appeal; (2) each party presents his case and discredits the other's; (3) more "},{"text":"acceptable","bold":true},{"text":": equal chance to win; (4) "},{"text":"develops the law","bold":true},{"text":" through ingenious arguments; (5) binding and self-executing."}]},{"type":"paragraph","text":[{"text":"Adversarial disadvantages (5):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"\"Sporting theory\" of justice:","bold":true},{"text":" those with the best lawyers (often the rich) win."}]},{"text":[{"text":"Acrimonious.","bold":true}]},{"text":[{"text":"Temptation to "},{"text":"manufacture evidence","bold":true},{"text":" ("},{"text":"Whitehouse v Jordan","italic":true},{"text":", 1980: experts' evidence \"doctored\")."}]},{"text":[{"text":"Delay tactics","bold":true},{"text":": "},{"text":"Ajani v Giwa","italic":true},{"text":" (1986), Oputa JSC deplored 16 years to settle land ownership."}]},{"text":[{"text":"Long delay impairs fact finding:","bold":true},{"text":" witnesses die, relocate or forget; evidence is lost."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Inquisitorial method:","bold":true},{"text":" trials as "},{"text":"inquiries","bold":true},{"text":"; main feature: the "},{"text":"adjudicator has considerable control over how$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 20, $study_guide$ evidence is collected and presented","bold":true},{"text":". He investigates, questions parties and witnesses, may appoint assessors or rely on "},{"text":"experts who never appear before it","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Inquisitorial advantages (4):","bold":true},{"text":" (1) "},{"text":"speedy","bold":true},{"text":", usually with a prescribed time limit; (2) "},{"text":"simpler, less formal, cheaper","bold":true},{"text":" (a prescribed form, not a writ); (3) "},{"text":"equal access to justice","bold":true},{"text":", since success depends on the body, not on representation; (4) binding and self-executing."}]},{"type":"paragraph","text":[{"text":"Inquisitorial disadvantages (3):","bold":true},{"text":" (1) "},{"text":"hasty trial","bold":true},{"text":": \"justice delayed is justice denied\" but "},{"text":"\"justice rushed is justice crushed\"","bold":true},{"text":"; (2) quality depends on the body's "},{"text":"ability and effort","bold":true},{"text":"; (3) often "},{"text":"in camera","bold":true},{"text":", escaping public scrutiny (officers convicted under the Abacha regime for "},{"text":"phantom coups","bold":true},{"text":")."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"R v Deputy Industrial Injuries Commissioner, ex parte Moore","italic":true},{"text":" (1965): reliance on two absent doctors' opinions was "},{"text":"not a breach of natural justice","bold":true},{"text":"; Diplock LJ stressed the tribunal's inquisitorial nature."}]},{"text":[{"text":"Baba v Nigerian Civil Aviation Training Centre","italic":true},{"text":" (Supreme Court): no breach of fair hearing where the person had a reasonable opportunity to defend himself, though cross-examination was refused."}]},{"text":[{"text":"Titi","bold":true},{"text":" countersigned the invigilator's irregularity report; the Examination Malpractices Panel, being inquisitorial, may rely on it though he is abroad. Her appeal will likely "},{"text":"fail","bold":true},{"text":"."}]},{"text":[{"text":"Judges now lean investigative in "},{"text":"divorce and child guardianship","bold":true},{"text":" cases. Trap: speedy disposal is an "},{"text":"inquisitorial","bold":true},{"text":" advantage."}]}]}]},{"number":"5.6","title":"ADR and customary methods","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Non-adjudicatory method (ADR):","bold":true},{"text":" disputes resolved "},{"text":"without the adjudicator finding facts","bold":true},{"text":"; no formal institutions, witnesses or apportionment of blame, yet recognised and regulated by law."}]},{"text":[{"text":"4 main forms:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Reconciliation:","bold":true},{"text":" the parties confer and agree to restore cordiality and harmony; "},{"text":"only the disputants","bold":true},{"text":" take part. Impossible if one refuses."}]},{"text":[{"text":"Conciliation:","bold":true},{"text":" a "},{"text":"third party as intermediary","bold":true},{"text":"; it differs from reconciliation in "},{"text":"the number of parties","bold":true},{"text":". The conciliator meets the parties "},{"text":"together","bold":true},{"text":", discusses the issues, proposes compromise terms and maps agreement and disagreement. His decision is "},{"text":"merely a guide","bold":true},{"text":"."}]},{"text":[{"text":"Mediation:","bold":true},{"text":" the mediator "},{"text":"rarely inquires into facts, does not apportion blame","bold":true},{"text":", merely "},{"text":"offers suggestions","bold":true},{"text":" the parties may accept or reject; meets them "},{"text":"separately","bold":true},{"text":". "},{"text":"Not binding even in a trade dispute.","bold":true}]},{"text":[{"text":"Arbitration:","bold":true},{"text":" the parties agree to have an "},{"text":"independent third party","bold":true},{"text":" settle the dispute "},{"text":"and to be bound by his decision","bold":true},{"text":"; the "},{"text":"only","bold":true},{"text":" form where the third party "},{"text":"decides on the merits","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Negotiation:","bold":true},{"text":" the parties settle it themselves; "},{"text":"once a third party comes in, it is no longer negotiation.","bold":true}]},{"text":[{"text":"3 essentials of arbitration:","bold":true},{"text":" (1) an existing or envisaged dispute; (2) "},{"text":"voluntary agreement","bold":true},{"text":" to refer it; (3) a "},{"text":"binding award","bold":true},{"text":". The arbitrator need not be a judge."}]},{"text":[{"text":"Binding conciliation:","bold":true},{"text":" in a "},{"text":"trade dispute","bold":true},{"text":" under the "},{"text":"Trade Disputes Act","bold":true},{"text":", a conciliator appointed by the Minister has "},{"text":"seven days","bold":true},{"text":"; a settlement is reported to the "},{"text":"Minister","bold":true},{"text":" with a "},{"text":"memorandum signed by the parties' representatives","bold":true},{"text":", which then "},{"text":"binds","bold":true},{"text":" the parties (breach is an offence)."}]}]},{"type":"table","header":[[{"text":"Adjudicatory"}],[{"text":"Non-adjudicatory"}]],"rows":[[[{"text":"Formal institutions"}],[{"text":"Generally informal"}]],[[{"text":"Fact finding"}],[{"text":"No fact finding"}]],[[{"text":"Apportions blame"}],[{"text":"No blame"}]],[[{"text":"Looks back and applies the law"}],[{"text":"Suggests solutions for future harmony"}]]]},{"type":"paragraph","text":[{"text":"ADR advantages (6):","bold":true},{"text":" avoids the "},{"text":"\"win-lose\"","bold":true},{"text":" character of litigation; saves time; parties "},{"text":"control their own fate","bold":true},{"text":"; free from "},{"text":"rules of evidence","bold":true},{"text":"; specialist arbitrator with "},{"text":"technical knowledge","bold":true},{"text":"; "},{"text":"not state-financed","bold":true},{"text":", so parties pay a$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 21, $study_guide$nd feel a sense of belonging."}]},{"type":"paragraph","text":[{"text":"ADR disadvantages (5):","bold":true},{"text":" costs of rooms and arbitrators' fees; awards subject to the court's "},{"text":"overriding powers","bold":true},{"text":" (to remit or set aside for error of law on its face); "},{"text":"no consolidation","bold":true},{"text":" of multi-party disputes, since it is voluntary; reconciliation and mediation "},{"text":"do not punish wrongdoers","bold":true},{"text":"; decisions "},{"text":"may not be binding","bold":true},{"text":"."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"In "},{"text":"M.V. Lupex v Nigerian Overseas Chartering and Shipping Ltd","italic":true},{"text":" (2003) the Supreme Court held a party "},{"text":"cannot approbate and reprobate","bold":true},{"text":": suing in court despite an arbitration clause reprobates it, and courts must act on the agreement. Once accepted, arbitration cannot be abandoned ("},{"text":"Larbi v Kwasi","italic":true},{"text":", 1950)."}]},{"text":[{"text":"Divorce proceedings may be adjourned for "},{"text":"reconciliation","bold":true},{"text":"; short \"reconciliation periods\" of resumed cohabitation do not defeat a later divorce."}]},{"text":[{"text":"Customary methods:","bold":true},{"text":" family heads, elders and chiefs mediate or arbitrate to restore harmony (the traditional attitude that \"you do not return from court and resume friendship\"). Customary arbitration binds where the parties voluntarily submit and agree to be bound by a decision under their custom ("},{"text":"Agu v Ikewibe","italic":true},{"text":", 1991)."}]},{"text":[{"text":"Trend:","bold":true},{"text":" English courts penalise in costs litigants who shun ADR; Justice Eso's group settled the "},{"text":"Mint Company","bold":true},{"text":" dispute with about "},{"text":"2,000","bold":true},{"text":" ex-workers by mediation within a year after over twelve years of fighting. Multi-door courthouses bring ADR into the courts."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Adjudicatory (binding, self-executing) versus non-adjudicatory (ADR); trial by ordeal is a crime."}]},{"text":[{"text":"Adversarial: parties control, judge as umpire; inquisitorial: adjudicator controls evidence."}]},{"text":[{"text":"Examination-in-chief, cross-examination (demolish), re-examination (explain)."}]},{"text":[{"text":"Civil 51% balance; criminal beyond reasonable doubt; ss.35(2) and 36(5) 1999 Constitution."}]},{"text":[{"text":"Res ipsa loquitur: defendant shows specific cause or reasonable care."}]},{"text":[{"text":"Shifting of fact = evidential burden; affirmanti non neganti; confessing and avoiding; four exceptions; jura novit curia."}]},{"text":[{"text":"Adversarial 5/5 (sporting theory); inquisitorial 4/3 (justice rushed is justice crushed)."}]},{"text":[{"text":"Reconciliation (parties only), conciliation (together), mediation (separately, never binding), arbitration (binding award); negotiation has no third party."}]}]}],"theory":{"itemId":"e7570f39-06f5-5958-b9eb-856041a2859e","question":[{"type":"paragraph","text":[{"text":"Critically examine the adversarial and inquisitorial methods of fact finding. Which do you prefer?"}]}]},"practice":[{"topic":"Fact Finding and Dispute Resolution","named":false}]}},{"kind":"note","itemId":"4c36c7c4-f8be-57b4-93c6-6a809f6eba82","sourceKey":"guide-topic:6","position":6,"payload":{"title":"Legal Reasoning","body":"The meaning of legal reasoning and features of legal language; principles, rules and standards; rhetoric; deductive, inductive and analogical logic and the limits of syllogism; practical reasoning and how judges justify decisions; judicial precedent (stare decisis, ratio decidendi, obiter dicta, per incuriam, distinguishing, overruling, the hierarchy of courts); how to approach problem questions.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"The meaning of legal reasoning and features of legal language; principles, rules and standards; rhetoric; deductive, inductive and analogical logic and the limits of syllogism; practical reasoning and how judges justify decisions; judicial precedent (stare decisis, ratio decidendi, obiter dicta, per incuriam, distinguishing, overruling, the hierarchy of courts); how to approach problem questions."}],"lessons":[{"number":"6.1","title":"Legal reasoning and the language of the law","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Reasoning:","bold":true},{"text":" thinking persuasively, in a coordinated, orderly, sensible and logical manner. "},{"text":"Legal:","bold":true},{"text":" connected with law."}]},{"text":[{"text":"Legal reasoning:","bold":true},{"text":" a "},{"text":"systematic, logical, coordinated, convincing or persuasive thinking, argument or presentation of points or issues relating to law.","bold":true}]},{"text":[{"text":"Legal reasoning in the judicial process:","bold":true},{"text":" the process of careful thinking by a judicial officer in the course of resolving legal issues presented by parties before his court."}]},{"text":[{"text":"Features of legal language:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Law is usually expressed in general terms","bold":true},{"text":", because it must apply to many people in varied circumstances. Example: "},{"text":"s.316 Criminal Code","bold":true},{"text":" (murder) names no weapon, so it covers shooting, stabbing, poisoning or strangling."}]},{"text":[{"text":"Law can be expressed in highly specific language","bold":true},{"text":" when no doubt is intended. Example: "},{"text":"s.6(5) 1999 Constitution","bold":true},{"text":" lists the superior courts of record one by one."}]},{"text":[{"text":"Use of abstract concepts","bold":true},{"text":" (\"contract\", \"company\", \"rule of law\", \"legal personality\", \"ownership\", \"possession\", \"fee simple\"). Main advantage: "},{"te$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 22, $study_guide$xt":"economy of words","bold":true},{"text":" (no need to list every detail)."}]},{"text":[{"text":"Common words with uncommon meanings","bold":true},{"text":" (\"matter\" for case; \"it is submitted that\")."}]},{"text":[{"text":"Latin and French phrases","bold":true},{"text":" ("},{"text":"consensus ad idem","italic":true},{"text":", "},{"text":"ultra vires","italic":true},{"text":", "},{"text":"audi alteram partem","italic":true},{"text":", "},{"text":"nemo dat quod non habet","italic":true},{"text":")."}]},{"text":[{"text":"Archaic English","bold":true},{"text":" (\"hereinbefore\", \"aforementioned\", \"hereinafter\")."}]},{"text":[{"text":"Argot or jargon","bold":true},{"text":" for insiders: \"my brief has not been perfected\" = I have not been paid my fee; \"I am speaking from the bar\" = I speak honestly as an officer of the court."}]},{"text":[{"text":"Resonant formal expressions:","bold":true},{"text":" \"the truth, the whole truth and nothing but the truth\"."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Case law is generalised too.","bold":true},{"text":" "},{"text":"Donoghue v Stevenson","italic":true},{"text":" (1932) concerned a snail in ginger beer, but its principle is stated at a "},{"text":"higher level of generality","bold":true},{"text":": a manufacturer of consumer goods owes a duty of care to the final consumer. Stating it only as snails in ginger beer would "},{"text":"hinder the growth of case law","bold":true},{"text":"; yet it is limited (consumable goods, proven health harm) so it is not too fluid."}]},{"text":[{"text":"The rule of law as a concept saves words: it carries (a) supremacy of the law, (b) equality before the law, (c) fundamental human rights."}]}]}]},{"number":"6.2","title":"Principles, rules and standards","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Principle of law:","bold":true},{"text":" an "},{"text":"established legal truth or proposition so clear that it cannot be contradicted except by a clearer proposition.","bold":true},{"text":" It is a timeless guide for making, executing and interpreting law, and a yardstick for judging legislation, decisions and arguments as valid or not, "},{"text":"notwithstanding any good result","bold":true},{"text":" they produce."}]},{"text":[{"text":"Examples in constitutional law: "},{"text":"rule of law, separation of powers, supremacy of the Constitution","bold":true},{"text":"."}]},{"text":[{"text":"An argument contrary to an established principle immediately becomes suspect and open to legal attack.","bold":true}]},{"text":[{"text":"Principles furnish the basis for rules; rules are specific applications of principles.","bold":true}]},{"text":[{"text":"Natural justice","bold":true},{"text":" (a principle) gives "},{"text":"2 rules","bold":true},{"text":":"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Audi alteram partem","bold":true,"italic":true},{"text":": hear the other side; a party must not be condemned unheard."}]},{"text":[{"text":"Nemo judex in causa sua","bold":true,"italic":true},{"text":": no one should be a judge in his own cause."}]}]}]},{"text":[{"text":"Standard:","bold":true},{"text":" a general measure of conduct applied "},{"text":"according to the circumstances of each case","bold":true},{"text":", leaving discretion to the judge. Examples: "},{"text":"reasonable care","bold":true},{"text":", the "},{"text":"reasonable man","bold":true},{"text":" in negligence, due care, good faith."}]},{"text":[{"text":"Rule:","bold":true},{"text":" a fixed, detailed precept giving the same answer for the same facts."}]}]},{"type":"table","header":[[],[{"text":"Principle"}],[{"text":"Rule"}],[{"text":"Standard"}]],"rows":[[[{"text":"Nature"}],[{"text":"Broad legal truth"}],[{"text":"Specific application"}],[{"text":"Flexible measure of conduct"}]],[[{"text":"Example"}],[{"text":"Natural justice"}],[{"text":"30 km/h school-zone limit"}],[{"text":"\"Drive with reasonable care\""}]],[[{"text":"Discretion"}],[{"text":"Guides reasoning"}],[{"text":"Little"}],[{"text":"Much"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Roscoe Pound","bold":true},{"text":" observed that in negligence the law must leave a wide margin of discretion, as in the standard of the reasonable man, and that attempts to replace it with hard and fast rules prove futile; such general standards are applied liberally according to the circumstances of each case."}]},{"text":[{"text":"A magistrate who hears a ₦1,200,000 claim against a company he largely owns breaches "},{"text":"nemo judex in causa sua","bold":true,"italic":true},{"text":". Dismissing a worker without hearing him breaches "},{"text":"audi alteram partem","bold":true,"italic":true},{"text":"."}]},{"text":[{"text":"Lord Hewart CJ in "},{"text":"R v Sussex Justices, ex parte McCarthy","italic":true},{"text":" (1924): justice \"should not only be done, but should manifestly and undoubtedly be seen to be done.\""}]}]}]},{"number":"6.3","title":"Rhetoric and logic","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Rhetoric:","bold":true},{"text":" the art of seeking to convince or persuade another, in writing or speech, to accept one's position or view. "},{"text":"Plato:","bold":true},{"text":" \"the art of winning men's minds with words.\""}]},{"text":[{"text":"Aristotle","bold":true},{"text":" distinguished "},{"text":"forensic","bold":true},{"text":" from "},{"text":"deliberative","bold":true},{"text":" rhetoric and thought deliberative the nobler. Broadly, "},{"text":"lawyers use forensic rhetoric","bold":true},{"text":" (persuading the court for a client); "},{"text":"judges use deliberative rhetoric","bold":true},{"text":" (a rational decision justifiable for the parties and society)."}]},{"text":[{"text":"The principal rhetorical device in law is the appeal to authority:","bold":true},{"text":" citing judicial and statutory $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 23, $study_guide$authorities (primary sources). Writers' opinions and foreign decisions (secondary or foreign sources) are only "},{"text":"persuasive","bold":true},{"text":"."}]},{"text":[{"text":"Rhetoric is an "},{"text":"acquired skill","bold":true},{"text":", not a gift: \"There is nothing like a born lawyer.\" Lawyers are made by diligence, patience and application of legal techniques."}]},{"text":[{"text":"Value of logic:","bold":true},{"text":" it helps the lawyer "},{"text":"reason clearly, express himself precisely, put his thoughts firmly, and detect bad arguments","bold":true},{"text":"."}]},{"text":[{"text":"Syllogism (deductive logic):","bold":true},{"text":" a deductive argument from a "},{"text":"major premise","bold":true},{"text":" and a "},{"text":"minor premise","bold":true},{"text":" to a "},{"text":"conclusion","bold":true},{"text":" that necessarily follows. Deduction runs from the "},{"text":"general to the particular","bold":true},{"text":"."}]},{"text":[{"text":"Inductive logic:","bold":true},{"text":" from "},{"text":"particular cases to a general principle","bold":true},{"text":" (from the minor to the major premise)."}]},{"text":[{"text":"Analogical reasoning:","bold":true},{"text":" comparing the issue with "},{"text":"closely similar earlier decisions","bold":true},{"text":"; a "},{"text":"loose, not strictly logical","bold":true},{"text":" form of reasoning."}]},{"text":[{"text":"Non sequitur","bold":true,"italic":true},{"text":": the fallacy where the conclusion does not follow from the premises."}]}]},{"type":"paragraph","text":[{"text":"Syllogism layout (statute = major premise):","bold":true}]},{"type":"table","header":[[{"text":"Part"}],[{"text":"Example"}]],"rows":[[[{"text":"Major premise (the law)"}],[{"text":"Any trader who sells in Oyingbo market without a permit shall pay a fine of ₦20,000."}]],[[{"text":"Minor premise (the facts)"}],[{"text":"Mama Bisi sold in Oyingbo market without a permit."}]],[[{"text":"Conclusion"}],[{"text":"Mama Bisi shall pay a fine of ₦20,000."}]]]},{"type":"paragraph","text":[{"text":"3 limitations of syllogism:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Logic is concerned with "},{"text":"validity, not truth","bold":true},{"text":". Validity = the conclusion follows from the premises; truth = the facts actually exist."}]},{"text":[{"text":"A wrong premise accepted as true leads inevitably to a wrong conclusion","bold":true},{"text":", though the form is valid."}]},{"text":[{"text":"A statement may be logical in one context and illogical in another:","bold":true},{"text":" \"things equal to the same thing are equal to one another\" works for 2 + 2 = 4 = 3 + 1, but \"a man is a human being; a woman is a human being; therefore a man is a woman\" is absurd."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Lawyer advising on a statute uses deduction:","bold":true},{"text":" the section is the major premise, the client's facts the minor, the advice the conclusion. Classic illustration under the old CAMA 1990: \"any person under 18 cannot join in forming a company; Seyi is under 18; so Seyi cannot join\". Here \"Seyi is under 18\" is the "},{"text":"minor premise","bold":true},{"text":"."}]},{"text":[{"text":"Truth versus validity in court:","bold":true},{"text":" a witness may be "},{"text":"logical yet lying","bold":true},{"text":"; counsel must expose it, and a judge who misses the distinction gives undeserved weight to the evidence."}]},{"text":[{"text":"Counsel who relies on a ₦50,000 penalty section that had been "},{"text":"repealed","bold":true},{"text":" has a valid form but a "},{"text":"false major premise","bold":true},{"text":", so a wrong conclusion."}]},{"text":[{"text":"Why induction for case law:","bold":true},{"text":" one decision may not yield a clear major premise, so the lawyer examines several cases, shows they share features with his client's case, and argues they establish a general rule (e.g. three earlier negligence cases where defendants paid damages). Then he reasons deductively from that rule."}]},{"text":[{"text":"Lord Diplock in ","bold":true},{"text":"Home Office v Dorset Yacht Co","bold":true,"italic":true},{"text":" (1970)","bold":true},{"text":" on whether a duty of care exists: "},{"text":"first stage analytical and inductive","bold":true},{"text":" (identify the characteristics A, B, C, D common to past cases where a duty was found); "},{"text":"second stage deductive and analytical","bold":true},{"text":" (convert that into \"wherever A, B, C, D exist a duty arises\" and test the present facts). The analyst must already know what he is looking for: the analogical element."}]}]}]},{"number":"6.4","title":"Practical reasoning and justification","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Practical reasoning","bold":true},{"text":" differs from formal logic: (1) it is "},{"text":"not tied to deduction or induction","bold":true},{"text":"; (2) it makes "},{"text":"frequent use of analogy","bold":true},{"text":"; (3) it "},{"text":"weighs various considerations","bold":true},{"text":" before a justifiable conclusion; (4) the link between premise and conclusion need not be formally valid; (5) whether the conclusion is good or bad is judged by "},{"text":"society's prevailing values","bold":true},{"text":", a verdict that may be reversed with time."}]},{"text":[{"text":"Oliver Wendell Holmes:","bold":true},{"text":" \"The life of the law has not been logic but experience.\" Meaning: logic is "},{"text":"only part","bold":true},{"text":" of legal reasoning; rules are "},{"text":"modified or discarded","bold":true},{"text":" as experience and values change (\"an endless succession of reason\")."}]},{"text":[{"text":"Factors judges use to justify decisions, apart from appeal to authority (4):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Coherence","bold":true},{"text":" $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 24, $study_guide$with existing principles and authorities (the more inconsistent, the less likely)."}]},{"text":[{"text":"Whether the consequences are acceptable in terms of "},{"text":"justice","bold":true},{"text":"."}]},{"text":[{"text":"Common sense","bold":true},{"text":" and the supposed view of a "},{"text":"reasonable man","bold":true},{"text":"."}]},{"text":[{"text":"Public policy","bold":true},{"text":" (the larger public good)."}]}]}]},{"text":[{"text":"A judge's "},{"text":"personal likes and dislikes","bold":true},{"text":" are "},{"text":"not","bold":true},{"text":" a proper justification."}]},{"text":[{"text":"Because these factors are weighed, outcomes can be hard to predict: litigation is sometimes called "},{"text":"\"a gamble\"","bold":true},{"text":" (a party may lose at the High Court and Court of Appeal yet win at the Supreme Court)."}]},{"text":[{"text":"Rhetoric and logic are the technical components of adjudication","bold":true},{"text":", but courts now depart from them where justice demands. "},{"text":"Chinwendu v Mbamali","italic":true},{"text":" (1980), per Eso JSC: \"Care should be taken by the court always not to sacrifice justice on the altar of technicalities.\""}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Judges weigh the evidence, counsel's rhetoric and logic, and fit with standards and principles, then give a "},{"text":"reasoned judgment","bold":true},{"text":". Logic is \"only part of the story\"."}]},{"text":[{"text":"An appellant seeking to overturn a ₦3,000,000 judgment only because counsel misnumbered paragraphs, after full argument on the merits, should fail: the court "},{"text":"decides on the merits","bold":true},{"text":"."}]},{"text":[{"text":"General Showboy problem","bold":true},{"text":" (death penalty for coup plotting; one earlier pardon; international calls for mercy): a judge may justify a lighter sentence by "},{"text":"justice","bold":true},{"text":" (death forecloses review), "},{"text":"public policy","bold":true},{"text":" (ill will abroad), "},{"text":"common sense and the reasonable man","bold":true},{"text":", and the earlier pardon."}]}]}]},{"number":"6.5","title":"Judicial precedent","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Stare decisis (judicial precedent):","bold":true},{"text":" a decision of a judge on a "},{"text":"question of law","bold":true},{"text":" binds "},{"text":"the judge himself and judges of lower courts","bold":true},{"text":" to decide the same question the same way."}]},{"text":[{"text":"Formula:","bold":true},{"text":" if the facts are A, B, C, D and the judge treats A, B, C as material, discards D and decides Y, then any later case whose material facts are A, B, C must also be decided Y (an extra immaterial fact E changes nothing)."}]},{"text":[{"text":"Farrar:","bold":true},{"text":" English case law is the product of "},{"text":"practical reasoning","bold":true},{"text":" emerging from decision making, combining "},{"text":"reasoning by analogy","bold":true},{"text":" with "},{"text":"reasoning by rules","bold":true},{"text":"."}]},{"text":[{"text":"Binding precedent:","bold":true},{"text":" from a court of higher rank. "},{"text":"Persuasive precedent:","bold":true},{"text":" from a court of "},{"text":"coordinate jurisdiction","bold":true},{"text":" (one State High Court for another) or a "},{"text":"foreign court","bold":true},{"text":" (English, Ghanaian); learned writers likewise only persuade."}]},{"text":[{"text":"Ratio decidendi:","bold":true},{"text":" \"the reason for the decision\"; the legal rule on which the decision rests, or the principle without which the court would not have reached its decision. Only the ratio binds."}]},{"text":[{"text":"Goodhart's 5 rules:","bold":true},{"text":" the principle of a case (1) is not found in the reasons given; (2) is not found in the rule of law stated; (3) is not necessarily found from all the ascertainable facts and the decision; (4) "},{"text":"is found from the facts treated by the judge as material and his decision on them","bold":true},{"text":"; (5) requires knowing what facts were held "},{"text":"immaterial","bold":true},{"text":"."}]},{"text":[{"text":"Julius Stone","bold":true},{"text":" disagreed: finding the ratio is basically "},{"text":"choosing an appropriate level of generality","bold":true},{"text":"; a case contains many potential rationes (e.g. "},{"text":"Donoghue v Stevenson","italic":true},{"text":" read at levels such as agent of harm, vehicle of harm, plaintiff's injury)."}]},{"text":[{"text":"Obiter dictum:","bold":true},{"text":" a remark made by the judge "},{"text":"\"by the way\"","bold":true},{"text":", not necessary for the decision; "},{"text":"not binding","bold":true},{"text":". Its weight depends on "},{"text":"the level of the court and the learning of the judge","bold":true},{"text":". A Supreme Court statement made after inviting counsel to address it on the law is a superior species of obiter, likely to be followed."}]},{"text":[{"text":"Per incuriam:","bold":true},{"text":" literally \"through carelessness\"; a decision given "},{"text":"in ignorance of a relevant statute or binding precedent","bold":true},{"text":". A court need not follow "},{"text":"its own","bold":true},{"text":" per incuriam decision, but "},{"text":"a lower court must still follow a higher court's decision even if per incuriam","bold":true},{"text":"."}]},{"text":[{"text":"Distinguishing:","bold":true},{"text":" pointing out an "},{"text":"essential (mostly factual) difference","bold":true},{"text":" between the present case and the earlier one, so the earlier case is not followed "},{"text":"but remains good law","bold":true},{"text":". Differs from "},{"text":"overruling","bold":true},{"text":" or refusing to follow, which only a court not bound by the earlier decision may do."}]},{"text":[{"text":"Glanville Williams:","bold":true},{"text":" "},{"text":"non-restrictive","bold":true},{"t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 25, $study_guide$ext":" distinguishing keeps the earlier ratio intact but finds the facts materially different; "},{"text":"restrictive","bold":true},{"text":" distinguishing cuts down the earlier ratio by treating extra facts as material."}]},{"text":[{"text":"Do judges make law?","bold":true},{"text":" Settled: "},{"text":"yes, though retrospectively","bold":true},{"text":", where no statute or precedent clearly applies (Cross). Mellish LJ: the whole of equity and nine-tenths of the common law were made by judges."}]}]},{"type":"paragraph","text":[{"text":"5 factors affecting the weight of a precedent:","bold":true},{"text":" (1) "},{"text":"age","bold":true},{"text":" (older precedents are harder to disturb); (2) "},{"text":"status and composition","bold":true},{"text":" of the court; (3) "},{"text":"adequacy of the law report","bold":true},{"text":"; (4) "},{"text":"history","bold":true},{"text":" (later approval, whether fully argued, unjust or absurd consequences, changed social conditions); (5) "},{"text":"unanimity","bold":true},{"text":" versus dissent. Length of the judgment is not a factor."}]},{"type":"paragraph","text":[{"text":"Hierarchy and precedent:","bold":true}]},{"type":"table","header":[[{"text":"Court"}],[{"text":"Position"}]],"rows":[[[{"text":"Supreme Court"}],[{"text":"Binds all courts to which the doctrine applies. Respects its own decisions but "},{"text":"may overrule one reached on a wrong principle","bold":true},{"text":" ("},{"text":"Bronik Motors v Wema Bank","italic":true},{"text":", 1983; "},{"text":"Abdulkarim v Incar","italic":true},{"text":", 1992)"}]],[[{"text":"Court of Appeal"}],[{"text":"Bound by its own decisions except ("},{"text":"Young v Bristol Aeroplane Co","italic":true},{"text":", 1944): (1) it chooses between two conflicting decisions of its own; (2) it must refuse one that cannot stand with a higher court's decision; (3) it need not follow one given per incuriam. In criminal matters, not strictly bound but reluctant to depart"}]],[[{"text":"Federal High Court (formerly Federal Revenue Court)"}],[{"text":"Binds Magistrate and District Courts; bound by Court of Appeal and Supreme Court"}]],[[{"text":"State High Courts"}],[{"text":"Coordinate: one High Court's decision only "},{"text":"persuades","bold":true},{"text":" another ("},{"text":"Barclays Bank v Hassan","italic":true},{"text":", 1961)"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Superior courts of record, s.6(5)(a) to (i) 1999 Constitution (made the only superior courts of record by s.6(3)):","bold":true},{"text":" Supreme Court, Court of Appeal, Federal High Court, High Court of a State, Sharia Court of Appeal of a State, Customary Court of Appeal of a State (with the FCT equivalents and the National Industrial Court). Magistrate, Customary, Area and District Courts are inferior courts set up by laws authorised under s.6(5)(j) and (k)."}]},{"text":[{"text":"Ratio in appellate courts (Obilade):","bold":true},{"text":" if the majority judgments rest on consistent but different principles, all those principles form the ratio; if on the same principle, that principle is the ratio; a proposition rejected by the majority is not the ratio. Where the court is "},{"text":"equally divided","bold":true},{"text":", the appeal is dismissed: "},{"text":"semper praesumitur pro negante","bold":true,"italic":true},{"text":" (\"the presumption is always in favour of the negative\")."}]},{"text":[{"text":"A Chief Magistrate who thinks a binding High Court decision was per incuriam must "},{"text":"follow it","bold":true},{"text":", though she may express doubt as obiter ("},{"text":"Board of Customs and Excise v Bolarinwa","italic":true},{"text":"). Per incuriam also covers overlooked binding precedent ("},{"text":"Nicholas v Penny","italic":true},{"text":", 1950)."}]},{"text":[{"text":"\"Had the goods been perishable I would have applied a different rule\", said in a cement case, is "},{"text":"obiter","bold":true},{"text":"."}]},{"text":[{"text":"A State High Court decision on a "},{"text":"state","bold":true},{"text":" matter does not bind magistrates in other states; on a "},{"text":"federal","bold":true},{"text":" matter it binds magistrates within and outside the state."}]},{"text":[{"text":"Overruling","bold":true},{"text":" sets aside an earlier "},{"text":"rule","bold":true},{"text":" in a later case; "},{"text":"reversing","bold":true},{"text":" sets aside the decision in the "},{"text":"same case","bold":true},{"text":" on appeal."}]},{"text":[{"text":"Problem pattern:","bold":true},{"text":" an Osun State High Court judge who rejects a Supreme Court decision as wrong and treats a contrary House of Lords decision as binding "},{"text":"errs twice","bold":true},{"text":": the Supreme Court binds him; English decisions are at most persuasive in Nigeria."}]}]}]},{"number":"6.6","title":"Approach to problems; reasoning in legislation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Problem questions: IRAC.","bold":true},{"text":" "},{"text":"I","bold":true},{"text":"ssue, "},{"text":"R","bold":true},{"text":"ule, "},{"text":"A","bold":true},{"text":"pplication, "},{"text":"C","bold":true},{"text":"onclusion (also IPAC, with Principle for Rule). Identify each issue, state the governing law with authorities, apply it to the facts, conclude and advise."}]},{"text":[{"text":"Essay questions: IDBC.","bold":true},{"text":" "},{"text":"I","bold":true},{"text":"ntroduction, "},{"text":"D","bold":true},{"text":"efinition, "},{"text":"B","bold":true},{"text":"ody, "},{"text":"C","bold":true},{"text":"onclusion. Give an authoritative definition; one point per paragraph with cases; always conclude."}]},{"text":[{"text":"Reasons for new legislation (5):","bold":true},{"text":" (1) dynamic nature of society; (2) "},{"text":"change in political and economic ideologies","bold":true},{"text":" of government (e.g. a military-to-civilian transition: the Petroleum Trust F$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 26, $study_guide$und was abolished); (3) "},{"text":"global shifts in value systems","bold":true},{"text":" (women's and children's rights, environment); (4) "},{"text":"scientific and technological breakthroughs","bold":true},{"text":" (computers, the internet); (5) "},{"text":"arrest of anti-social behaviour","bold":true},{"text":" (the "},{"text":"Advance Fee Fraud","bold":true},{"text":" law against \"419\"; failed banks laws; NDLEA)."}]},{"text":[{"text":"Ambiguity:","bold":true},{"text":" a provision bears "},{"text":"two or more meanings","bold":true},{"text":", each deducible from the text (lexical, syntactic, contextual). "},{"text":"Vagueness:","bold":true},{"text":" the meaning is "},{"text":"cloudy, indeterminate and confusing","bold":true},{"text":"; it is "},{"text":"worse","bold":true},{"text":" than ambiguity because context can hardly cure it."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Mr Ade sued Mr Ola in the Ibadan High Court citing only a House of Lords decision. Advise Mr Ola.\" Use "},{"text":"IRAC","bold":true},{"text":": issue (is an English decision binding?), rule (precedent binds only within a hierarchy; foreign decisions persuade), application, conclusion (persuasive only)."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Legal reasoning: systematic, logical, persuasive thinking on law; language usually general (s.316 Criminal Code), sometimes specific (s.6(5) Constitution); concepts save words."}]},{"text":[{"text":"Principles ground rules (natural justice: audi alteram partem, nemo judex in causa sua); standards (reasonable man) flex with each case."}]},{"text":[{"text":"Rhetoric: Plato's definition; lawyers forensic, judges deliberative; principal device is appeal to authority."}]},{"text":[{"text":"Deduction: general to particular (syllogism); induction: particular to general (case law); analogy is loose."}]},{"text":[{"text":"Syllogism limits: validity not truth; false premise, false conclusion; context."}]},{"text":[{"text":"Practical reasoning; Holmes's \"experience\"; four justifying factors; "},{"text":"Chinwendu v Mbamali","italic":true},{"text":"."}]},{"text":[{"text":"Precedent: ratio (Goodhart, Stone), obiter, per incuriam, distinguishing; "},{"text":"Young v Bristol Aeroplane","italic":true},{"text":" exceptions. Problems: IRAC; essays: IDBC."}]}]}],"theory":{"itemId":"60048f78-076c-54fd-82f1-f119a83545ec","question":[{"type":"paragraph","text":[{"text":"Write short notes on (a) principles and standards, (b) legal rhetoric and legal logic, (c) legal reasoning and practical reasoning."}]}]},"practice":[{"topic":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","named":false}]}},{"kind":"note","itemId":"a4887f7b-46f6-5d89-a17a-0ef5e0298664","sourceKey":"guide-topic:7","position":7,"payload":{"title":"Legislation","body":"Meaning of legislation and reasons for new laws; legislative proposals and drafting; how a bill becomes an Act (civilian and military); types and forms of legislation, subsidiary legislation, codification; the rules of statutory interpretation with cases; aids, presumptions and maxims.","noteType":"guide_topic","number":7,"mustKnow":[{"text":"Meaning of legislation and reasons for new laws; legislative proposals and drafting; how a bill becomes an Act (civilian and military); types and forms of legislation, subsidiary legislation, codification; the rules of statutory interpretation with cases; aids, presumptions and maxims."}],"lessons":[{"number":"7.1","title":"Legislation, reasons for it and legislative proposals","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Legislation (strict sense):","bold":true},{"text":" law made by the "},{"text":"legislature","bold":true},{"text":", the body whose primary duty is to make law (not ministries, councils or courts)."}]},{"text":[{"text":"Definition:","bold":true},{"text":" the "},{"text":"formal and express promulgation or declaration of legal rules, proscriptions or directions into statutes","bold":true},{"text":" on the subjects to which they relate."}]},{"text":[{"text":"Section 4(1), 1999 Constitution:","bold":true},{"text":" federal legislative power is vested in the National Assembly. "},{"text":"Section 4(2):","bold":true},{"text":" it legislates for the "},{"text":"peace, order and good government of the Federation","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"5 reasons for new legislation:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Dynamic nature of society:","bold":true},{"text":" new attitudes and values; e.g. laws against dumping refuse in public places and indiscriminate slaughtering of animals."}]},{"text":[{"text":"Change in political and economic ideologies of government:","bold":true},{"text":" \"A change of government must bring new changes in the law\" (Atiyah); e.g. a civilian regime repealing Decrees and abolishing the Petroleum Trust Fund."}]},{"text":[{"text":"Global shifts in value systems:","bold":true},{"text":" laws on women's and children's rights, environment, endangered species, from membership of international organisations and NGOs."}]},{"text":[{"text":"Scientific and technological breakthroughs:","bold":true},{"text":" computers and the Internet spread private information \"to all and sundry\"; tape recorders forced copyright changes for broadcast music; hence IT laws."}]},{"text":[{"text":"Arrest of anti-social behaviour:","bold":true},{"text":" Failed Banks Decree 1994, Advance Fee Fraud (\"419\") Decree, Money Laundering Act, NDLEA Act 1989."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Who may initiate:","bold":true},{"text":" citizens, interest groups, communities, NGOs (e.g. WOTCLEF), ministries, corporate bodies, legislators, the executive."}]},{"text":[{"text":"Form:","bold":true},{"text":" "},{"text":"no stereotyped form","bold":true},{"text":", but "},{"text":"logically and structurally $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 27, $study_guide$presented","bold":true},{"text":", titled by subject (e.g. \"Secret Cultism: The Menace of Cultism in Institutions of Learning in Nigeria\")."}]},{"text":[{"text":"Order of contents:","bold":true},{"text":" (1) "},{"text":"present position","bold":true},{"text":", (2) "},{"text":"anomalies","bold":true},{"text":", (3) "},{"text":"suggested changes","bold":true},{"text":", (4) "},{"text":"concrete proposals","bold":true},{"text":" for the law."}]},{"text":[{"text":"Channels:","bold":true},{"text":" memoranda to government departments, to the legislature or its "},{"text":"committee","bold":true},{"text":", or to the "},{"text":"Law Reform Commission","bold":true},{"text":"; opinions in "},{"text":"print and electronic media","bold":true},{"text":"; "},{"text":"pressure groups","bold":true},{"text":" (e.g. the NUT on professionalising teaching). A court judgment is not a channel."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Scenario matching: Internet privacy = technology; new regime repealing Decrees = ideology; women's rights after joining international bodies = global values; public-health refuse law = dynamic society; anti-fraud law = anti-social behaviour. \"Preserving every custom whatever the change in values\" is never a reason."}]}]}]},{"number":"7.2","title":"Drafting, language defects and the structure of a statute","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Draftsman's instructions","bold":true},{"text":" must state: "},{"text":"object","bold":true},{"text":" of the law, "},{"text":"background","bold":true},{"text":", the "},{"text":"mischief or need","bold":true},{"text":" to cure, "},{"text":"implementation bodies","bold":true},{"text":", "},{"text":"procedures and instruments","bold":true},{"text":", "},{"text":"possible exemptions","bold":true},{"text":"."}]},{"text":[{"text":"Qualities:","bold":true},{"text":" flair; high intellect; "},{"text":"analytical, diagnostic","bold":true},{"text":" mind; good memory and foresight; patience, "},{"text":"attention to detail","bold":true},{"text":"; mastery of language; "},{"text":"amenable to corrections and criticisms","bold":true},{"text":"; familiar with the country's "},{"text":"socio-cultural and political peculiarities","bold":true},{"text":". "},{"text":"Knowledge of law is indispensable","bold":true},{"text":", so appoint a "},{"text":"lawyer","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Principle"}],[{"text":"Meaning"}],[{"text":"Breach"}]],"rows":[[[{"text":"Mastery and familiarity of language"}],[{"text":"Common English; no tribal or Latin expressions"}],[{"text":"\"rank pari passu\", \"inter alia\""}]],[[{"text":"Direct and explicit expression"}],[{"text":"Not winding"}],[{"text":"Long self-defence clause; better \"Every person has a right to defend himself when attacked.\""}]],[[{"text":"Economy of language"}],[{"text":"No needless synonyms"}],[{"text":"\"fails, refuses, neglects, omits or avoids\""}]],[[{"text":"Orderliness"}],[{"text":"Logical sections and paragraphs"}],[{"text":"Patchwork draft"}]],[[{"text":"Avoid archaism"}],[{"text":"Drop words that add nothing"}],[{"text":"\"above\", \"hereinafter\", \"aforesaid\""}]],[[{"text":"Consistency of terms"}],[{"text":"Same word for the same idea"}],[{"text":"\"lessor\" in s.2, \"landlord\" in s.5"}]],[[{"text":"Connective words"}],[{"text":"will/shall, and/or, from/to"}],[{"text":"\"from\" and \"to\" may include or exclude stated periods"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Section 55:","bold":true},{"text":" National Assembly business is in "},{"text":"English, and in Hausa, Ibo and Yoruba when adequate arrangements have been made","bold":true},{"text":"; in practice English."}]},{"text":[{"text":"Gibson:","bold":true},{"text":" be wary of metaphors; use the same word always for the same idea (elegant variation confuses); avoid repetitions."}]},{"text":[{"text":"Ambiguity:","bold":true},{"text":" "},{"text":"two or more mutually exclusive meanings","bold":true},{"text":", each deducible from the text. Types: "},{"text":"lexical, syntactic, contextual","bold":true},{"text":"."}]},{"text":[{"text":"Vagueness:","bold":true},{"text":" cloudy, indeterminate meaning creating "},{"text":"borderline cases","bold":true},{"text":"; "},{"text":"worse than ambiguity","bold":true},{"text":" because it can "},{"text":"hardly be resolved by the context","bold":true},{"text":"."}]},{"text":[{"text":"Open texture:","bold":true},{"text":" built-in "},{"text":"generality or flexibility","bold":true},{"text":", since no statute foresees every case. "},{"text":"Farrar and Dugdale:","bold":true},{"text":" the drafter must make a rule "},{"text":"general enough","bold":true},{"text":" yet "},{"text":"detailed and clear","bold":true},{"text":"; \"breadth of scope and precision are not always compatible objectives\"."}]}]},{"type":"paragraph","text":[{"text":"Structure (Commonwealth order):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Preliminary:","bold":true},{"text":" long title, preamble (not always), short title, enacting clause, commencement clause."}]},{"text":[{"text":"Principal:","bold":true},{"text":" substantive and administrative (enforcing agencies) provisions."}]},{"text":[{"text":"Miscellaneous:","bold":true},{"text":" offences and supplementary provisions."}]},{"text":[{"text":"Final:","bold":true},{"text":" savings, transitional provisions, repeals, schedules, perhaps an interpretation section."}]},{"text":[{"text":"Executive endorsement:","bold":true},{"text":" signature of the President or Governor."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Punctuation","bold":true},{"text":" is part of a statute; changing it alone can change meaning. "},{"text":"Schedules","bold":true},{"text":" hold elaborate technical information; "},{"text":"marginal notes","bold":true},{"text":" act as bookmarks."}]}]}],"explainMore":[$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 28, $study_guide${"type":"list","ordered":false,"items":[{"text":[{"text":"Spot the defect: \"large gatherings\" with no number = "},{"text":"vagueness","bold":true},{"text":"; \"bank\" (lender or riverbank) = "},{"text":"ambiguity","bold":true},{"text":"."}]},{"text":[{"text":"Semantics:","bold":true},{"text":" words like \"consent\", \"husband\", \"reasonable\" decide liberty and liability. Drafters use "},{"text":"definition sections","bold":true},{"text":" and "},{"text":"interpretation clauses","bold":true},{"text":" to extend or narrow ordinary meaning: if a Law says \"money means paper currency (notes) only\", coins are not money under it. "},{"text":"Section 318","bold":true},{"text":" defines words in the Constitution; the "},{"text":"Interpretation Act","bold":true},{"text":" fills gaps."}]}]}]},{"number":"7.3","title":"The legislative process","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The National Assembly is "},{"text":"bicameral: Senate and House of Representatives","bold":true},{"text":" (section 47). A bill (except a money bill) may start in either House. A bill is "},{"text":"gazetted","bold":true},{"text":" to give the public notice so people can weigh in; this does not make it law."}]}]},{"type":"paragraph","text":[{"text":"Stages in the House of origin:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"First reading:","bold":true},{"text":" the "},{"text":"Clerk","bold":true},{"text":" reads it to inform members; "},{"text":"no questions","bold":true},{"text":"."}]},{"text":[{"text":"Second reading:","bold":true},{"text":" "},{"text":"general principles debated, questions asked","bold":true},{"text":"."}]},{"text":[{"text":"Committee stage:","bold":true},{"text":" text examined "},{"text":"clause by clause, even word by word","bold":true},{"text":", to make it acceptable."}]},{"text":[{"text":"Report stage:","bold":true},{"text":" bill returns "},{"text":"in amended form","bold":true},{"text":"; "},{"text":"success or failure becomes evident","bold":true},{"text":"."}]},{"text":[{"text":"Third reading:","bold":true},{"text":" final vote by "},{"text":"simple or two-thirds majority depending on subject matter","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Then the "},{"text":"other House","bold":true},{"text":" repeats the process, then "},{"text":"assent","bold":true},{"text":" by the President (Governor for a State). Assent turns the bill into an "},{"text":"Act","bold":true},{"text":" (federal) or "},{"text":"Law","bold":true},{"text":" (State)."}]},{"text":[{"text":"Standing committees","bold":true},{"text":" are permanent, by subject; "},{"text":"ad hoc committees","bold":true},{"text":" handle one issue and dissolve after reporting."}]},{"text":[{"text":"Section 58(5):","bold":true},{"text":" if the President withholds assent, the bill becomes law "},{"text":"without assent","bold":true},{"text":" if "},{"text":"passed again by two-thirds in each House","bold":true},{"text":" (State equivalent: section 100(5))."}]},{"text":[{"text":"Military regime:","bold":true},{"text":" legislative and executive powers "},{"text":"fused","bold":true},{"text":"; no readings or debates. "},{"text":"Decree","bold":true},{"text":" = signed by the Head of the Federal Military Government; "},{"text":"Edict","bold":true},{"text":" = signed by a State Military Governor. Weakness: "},{"text":"lack of rigorous scrutiny","bold":true},{"text":", hence "},{"text":"endless amendments","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: Senate two-thirds plus House simple majority does "},{"text":"not","bold":true},{"text":" override a veto. Debate starts at second reading, not first."}]},{"text":[{"text":"Surviving Decrees and Edicts are deemed Acts or Laws under "},{"text":"section 315","bold":true},{"text":". A hurried bill meets implementation problems; legislative power also checks the executive."}]}]}]},{"number":"7.4","title":"Types and forms of legislation, subsidiary legislation and codification","mustKnow":[{"type":"table","header":[[{"text":"Type"}],[{"text":"Meaning"}],[{"text":"Example"}]],"rows":[[[{"text":"Public General Act"}],[{"text":"Applies to everyone, everywhere"}],[{"text":"Criminal Code, Matrimonial Causes Act"}]],[[{"text":"Local Act"}],[{"text":"One locality or community"}],[{"text":"Curfew in one area; NDDC Act; Act setting up one university"}]],[[{"text":"Private Act"}],[{"text":"A particular person or body"}],[{"text":"Pardon for a named convict; proscribing a union"}]],[[{"text":"Consolidating Act"}],[{"text":"Re-enacts earlier related "},{"text":"statutes","bold":true},{"text":", with modifications, as one coherent whole"}],[{"text":"Four aviation Acts in one"}]],[[{"text":"Code"}],[{"text":"Existing statutes "},{"text":"plus common law and equity","bold":true},{"text":" on a subject"}],[{"text":"Criminal Code, Penal Code, CAMA 1990"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Also: "},{"text":"amending","bold":true},{"text":" and "},{"text":"repealing","bold":true},{"text":" Acts; "},{"text":"money bills","bold":true},{"text":"; "},{"text":"executive","bold":true},{"text":", "},{"text":"member's","bold":true},{"text":" and "},{"text":"private","bold":true},{"text":" bills; "},{"text":"primary","bold":true},{"text":" (by the legislature; the Constitution is the foundation) vs "},{"text":"subsidiary","bold":true},{"text":". In a further classification (municipal, primary, judicial, executive, subordinate), a "},{"text":"practice direction","bold":true},{"text":" by a Chief Judge is "},{"text":"judicial legislation","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Form"}],[{"text":"Made by"}]],"rows":[[[{"text":"Ordinance"}],[{"text":"Central legislature before 1 October 1954"}]],[[{"text":"Act / Law"}],[{"text":"National Assembly / State House of Assembly"}]],[[{"text":"Decree / Edict"}$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 29, $study_guide$],[{"text":"Federal Military Government / State Military Governor"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Subsidiary (delegated) legislation:","bold":true},{"text":" made by bodies "},{"text":"other than the legislature","bold":true},{"text":" under a statute: "},{"text":"bye-laws","bold":true},{"text":", "},{"text":"regulations","bold":true},{"text":" of public corporations, ministers' "},{"text":"statutory instruments","bold":true},{"text":". The parent law is the "},{"text":"enabling statute","bold":true},{"text":"."}]},{"text":[{"text":"Why:","bold":true},{"text":" the legislature "},{"text":"cannot provide every detail","bold":true},{"text":" and lacks "},{"text":"technical expertise","bold":true},{"text":"."}]},{"text":[{"text":"Limit:","bold":true},{"text":" exceeding the power makes it "},{"text":"ultra vires, null and void","bold":true},{"text":"; it ranks below statutes."}]}]},{"type":"paragraph","text":[{"text":"Codification:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"For:","bold":true},{"text":" one source instead of scattered, overlapping law; more accessible; encourages reform; simplifies judges' work. Proposed for land law (Land Use Act, conveyancing laws, customary tenure)."}]},{"text":[{"text":"Against:","bold":true},{"text":" "},{"text":"Von Savigny","bold":true},{"text":" favoured unconscious, evolutionary growth of law, not drastic change; a code cannot foresee all cases; it breaks continuity, risks "},{"text":"fossilisation","bold":true},{"text":", is expensive."}]},{"text":[{"text":"Customary law:","bold":true},{"text":" impracticable because of "},{"text":"ethnic diversity","bold":true},{"text":", "},{"text":"near irreconcilable differences","bold":true},{"text":", and loss of "},{"text":"flexibility and adaptability","bold":true},{"text":"."}]},{"text":[{"text":"Safeguard:","bold":true},{"text":" review the code "},{"text":"every 10 or 20 years","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"One named person = private; one region or institution = local; everyone = public general. A minister's regulation that adds an unauthorised tax is void to that extent."}]},{"text":[{"text":"Atiyah: law is \"an immensely complex social machine\", always needing repair; \"we must not look for perfection or for finality\"."}]}]}]},{"number":"7.5","title":"Rules of statutory interpretation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Obilade:","bold":true},{"text":" the primary duty of the courts in interpreting statutes is "},{"text":"to find the intention of the legislature","bold":true},{"text":", as expressed in the statute, though judges were not present when it was made."}]}]},{"type":"table","header":[[{"text":"Rule"}],[{"text":"What the court does"}],[{"text":"Case"}]],"rows":[[[{"text":"Literal"}],[{"text":"Natural, ordinary meaning, whatever the result"}],[{"text":"Sussex Peerage case","italic":true},{"text":" (1844), Tindal C.J."}]],[[{"text":"Golden"}],[{"text":"Departs from ordinary meaning to avoid absurdity, inconsistency or repugnance, "},{"text":"no further","bold":true}],[{"text":"Becke v Smith","italic":true},{"text":" (1836); "},{"text":"University of Ibadan v Adamolekun","italic":true},{"text":" (1967)"}]],[[{"text":"Mischief"}],[{"text":"Finds the defect in the earlier law and reads the Act to cure it"}],[{"text":"Heydon's case","italic":true},{"text":" (1584)"}]],[[{"text":"Purposive"}],[{"text":"Reads the words to achieve the statute's purpose"}],[{"text":"Nafiu Rabiu v State","italic":true},{"text":" (1981)"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Tindal C.J.:","bold":true},{"text":" \"If the words of the statute are in themselves precise and unambiguous, then no more can be necessary than to expound those words in their natural and ordinary sense.\""}]},{"text":[{"text":"Heydon's case asks:","bold":true},{"text":" (1) the law before the Act; (2) the "},{"text":"mischief","bold":true},{"text":" it did not cover; (3) the "},{"text":"remedy","bold":true},{"text":" Parliament chose; (4) the "},{"text":"true reason","bold":true},{"text":" for it."}]},{"text":[{"text":"Literal rule criticisms:","bold":true},{"text":" words have no meaning outside context; absurd results; "},{"text":"Dias:","bold":true},{"text":" ill-suited to modern social legislation in a developing society. (Too much judicial freedom is "},{"text":"not","bold":true},{"text":" one.)"}]},{"text":[{"text":"Mischief rule limits:","bold":true},{"text":" many modern laws meet new needs rather than cure defects; no test for the actual words; no access to parliamentary debates (Hansard)."}]},{"text":[{"text":"Status:","bold":true},{"text":" "},{"text":"rules of practice, not law","bold":true},{"text":". "},{"text":"Fatayi-Williams CJN","bold":true},{"text":" ("},{"text":"Awolowo v Shagari","italic":true},{"text":"): they are \"of little practical assistance in settling doubts\". "},{"text":"Bennion:","bold":true},{"text":" \"there is no golden rule nor is there a mischief rule or a literal rule ... there are a thousand and one interpretative criteria.\""}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Awolowo v Shagari","bold":true,"italic":true},{"text":" (1979):","bold":true},{"text":" on the 1979 presidential election, justices applying the "},{"text":"literal rule","bold":true},{"text":" to the same words reached "},{"text":"opposing conclusions","bold":true},{"text":"."}]},{"text":[{"text":"Adegbenro v Akintola","bold":true,"italic":true},{"text":" (1963):","bold":true},{"text":" the Governor could remove the Premier \"if it appears to him\" he lacked majority support; the Privy Council held he could decide "},{"text":"without any limit on the material","bold":true},{"text":" used (in effect, it could even come to him in a dream)."}]},{"text":[{"text":"Adamolekun","bold":true,"italic":true},{"text":":","bol$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 30, $study_guide$d":true},{"text":" an Edict inconsistent with a Federal Decree was void, but a literal reading of an ouster clause would have left it standing; the Supreme Court called that absurd and struck it down: "},{"text":"golden rule","bold":true},{"text":". A hawker inside the Secretariat caught by \"in the vicinity of\" is the same reasoning ("},{"text":"Adler v George","italic":true},{"text":" (1964))."}]},{"text":[{"text":"In "},{"text":"Magor and St Mellons RDC v Newport Corporation","italic":true},{"text":", Lord Denning urged judges to fill gaps; "},{"text":"Lord Simonds","bold":true},{"text":" called it \"a naked usurpation of the legislative function under the thin disguise of interpretation\"."}]},{"text":[{"text":"Best approach:","bold":true},{"text":" a "},{"text":"combination","bold":true},{"text":" of canons and aids, read against the legislative purpose."}]}]}]},{"number":"7.6","title":"Aids, presumptions and maxims","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Context:","bold":true},{"text":" an Act is "},{"text":"read as a whole","bold":true},{"text":"; words take meaning from context."}]},{"text":[{"text":"Intrinsic aids","bold":true},{"text":" (inside the Act): "},{"text":"preamble, long title","bold":true},{"text":", definition and interpretation sections, schedules."}]},{"text":[{"text":"Extrinsic aids","bold":true},{"text":" (outside): "},{"text":"Interpretation Act","bold":true},{"text":", "},{"text":"dictionaries","bold":true},{"text":" (e.g. Black's Law Dictionary), "},{"text":"textbooks","bold":true},{"text":", precedent."}]},{"text":[{"text":"Section 318(4):","bold":true},{"text":" the Interpretation Act applies to interpreting the Constitution. Its purpose: "},{"text":"avoid needless and burdensome repetition","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Presumptions:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"A new Act does "},{"text":"not alter existing law","bold":true},{"text":" unless it says so."}]},{"text":[{"text":"Against "},{"text":"interfering with vested rights","bold":true},{"text":" and against "},{"text":"retrospective","bold":true},{"text":" operation."}]},{"text":[{"text":"In criminal law, against "},{"text":"liability without fault","bold":true},{"text":" unless strict liability is clear."}]},{"text":[{"text":"Against "},{"text":"ousting courts' jurisdiction","bold":true},{"text":": construed "},{"text":"strictly","bold":true},{"text":", choosing the meaning that "},{"text":"preserves","bold":true},{"text":" jurisdiction ("},{"text":"Barclays Bank v CBN","italic":true},{"text":" (1976))."}]}]},{"type":"table","header":[[{"text":"Maxim"}],[{"text":"Meaning"}]],"rows":[[[{"text":"Ejusdem generis"}],[{"text":"General words after specific ones cover only the "},{"text":"same class","bold":true}]],[[{"text":"Expressio unius est exclusio alterius"}],[{"text":"Express mention of one "},{"text":"excludes","bold":true},{"text":" others"}]],[[{"text":"Noscitur a sociis"}],[{"text":"A word takes meaning from "},{"text":"associated words","bold":true}]],[[{"text":"Lex non cogit ad impossibilia"}],[{"text":"Law does not compel the "},{"text":"impossible","bold":true}]],[[{"text":"Ut res magis valeat quam pereat"}],[{"text":"Prefer the reading that makes it "},{"text":"valid and effective","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Precedent:","bold":true},{"text":" "},{"text":"Lord Diplock, ","bold":true},{"text":"Carter v Bradbeer","bold":true,"italic":true},{"text":" (1975):","bold":true},{"text":" a ratio on words in one statute is only "},{"text":"persuasive","bold":true},{"text":" for the same words in another statute."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Bread, meat pie, cake, doughnut, sausage and other snacks\": \"other snacks\" covers pastries such as chin-chin, not jollof rice, fish or zobo."}]},{"text":[{"text":"A penalty on \"the Principal and/or Vice-Principal\" absent without excuse does not reach teachers (expressio unius)."}]},{"text":[{"text":"Scenarios: levy charged on earlier bookings = against "},{"text":"retrospectivity","bold":true},{"text":"; offence silent on knowledge = against "},{"text":"liability without fault","bold":true},{"text":"; \"no court shall entertain any action\" = "},{"text":"preserve jurisdiction","bold":true},{"text":"."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Legislation = formal, express promulgation of legal rules by the legislature (s.4(2))."}]},{"text":[{"text":"5 reasons: dynamic society, ideology, global values, technology, anti-social behaviour."}]},{"text":[{"text":"Draftsman must be a lawyer; ambiguity is less serious than vagueness; open texture is deliberate."}]},{"text":[{"text":"Statute order: preliminary, principal, miscellaneous, final, executive endorsement."}]},{"text":[{"text":"Bill: first, second, committee, report, third reading, other House, assent; override needs two-thirds in each House."}]},{"text":[{"text":"Consolidation = statutes only; code adds common law and equity; ultra vires subsidiary legislation is void."}]},{"text":[{"text":"Literal ("},{"text":"Sussex Peerage","italic":true},{"text":"), golden ("},{"text":"Adamolekun","italic":true},{"text":"), mischief ("},{"text":"Heydon's case","italic":true},{"text":"), purposive: rules of practice only."}]},{"text":[{"text":"Four presumptions and five maxims guide intention."}]}]}],"theory":{"itemId":"b1d50cd4-755c-597c-8b21-8f82a6086dd2","question":[{"type":"paragraph","text":[{"text":"\"The primary duty of the courts in interpreting statutes is to find the intention of the legislature\" (Obilade). Discuss the rules of statutory interpretation with cases."}]}]},"practice":[{"topic":"Legislation: Process, Types and Statutory Interpretation","named":false}]}},{"kind":"note","itemId":"4b3a1819-9992-50b6-aa2e-0c3eba2cd629","sourceKey":"guide-topic:8","posi$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 31, $study_guide$tion":8,"payload":{"title":"Sources of Nigerian Law","body":"What \"sources of Nigerian law\" means; primary vs secondary sources; received English law and the 1 January 1900 date; the test for a statute of general application and its cases; Nigerian legislation (Constitution, Ordinances, Acts, Laws, Decrees, Edicts, subsidiary legislation); customary law, Islamic law and the three validity tests with cases; judicial precedent; international law; secondary sources.","noteType":"guide_topic","number":8,"mustKnow":[{"text":"What \"sources of Nigerian law\" means; primary vs secondary sources; received English law and the 1 January 1900 date; the test for a statute of general application and its cases; Nigerian legislation (Constitution, Ordinances, Acts, Laws, Decrees, Edicts, subsidiary legislation); customary law, Islamic law and the three validity tests with cases; judicial precedent; international law; secondary sources."}],"lessons":[{"number":"8.1","title":"Meaning and classification of sources","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sources of Nigerian law:","bold":true},{"text":" the materials through which a legal practitioner, a court or a judge finds reliable authorities for a particular legal question. It tells you how and where to locate the law on any problem. (It is not about printers of statutes, judges' private beliefs or the 1914 amalgamation.)"}]},{"text":[{"text":"Sources are of two kinds:"}]}]},{"type":"table","header":[[{"text":"Primary sources (can bind a court)"}],[{"text":"Secondary sources (only persuasive)"}]],"rows":[[[{"text":"1. English law (received English law and extended English law)"}],[{"text":"Law reports"}]],[[{"text":"2. Nigerian legislation and subsidiary enactments"}],[{"text":"Textbooks and treatises"}]],[[{"text":"3. Nigerian case law (judicial precedent)"}],[{"text":"Legal periodicals and journals"}]],[[{"text":"4. Customary law, including Islamic law where applicable"}],[{"text":"Law digests"}]],[[{"text":"5. International law, once enacted into Nigerian law"}],[{"text":"Legal dictionaries, newspapers, etc."}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Key difference:","bold":true},{"text":" only "},{"text":"primary","bold":true},{"text":" sources can bind a Nigerian court; "},{"text":"secondary","bold":true},{"text":" sources merely "},{"text":"persuade","bold":true},{"text":", and are usually relied on where no primary source is available or applicable."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A common way of counting is \"six sources\": received English law, Nigerian legislation, case law, customary law, delegated legislation and international law. Whatever the count, the primary/secondary split is the one examiners test."}]},{"text":[{"text":"Trap: law reports appear on the secondary list because they are the books in which cases are found; the "},{"text":"decision","bold":true},{"text":" inside the report (judicial precedent) is the primary source."}]},{"text":[{"text":"Gboga problem","bold":true},{"text":" (a novel point, no statute or reported case, only a textbook by a leading professor): Gboga "},{"text":"may cite the textbook as persuasive authority","bold":true},{"text":". The court is not bound by it. Its weight depends on "},{"text":"the standing (personality) of the author and the significance of the subject covered","bold":true},{"text":". Build the answer: list primary and secondary sources; say primary sources bind; say textbooks are used where decisions are scarce or absent, if written by eminent scholars and of acceptable standard; give examples (Obilade, Kodilinye, Okonkwo, Aguda, Nwogwugwu; Sagay on international law); conclude on the facts."}]}]}]},{"number":"8.2","title":"Received English law","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Received English law","bold":true},{"text":" = 3 components:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"the "},{"text":"common law","bold":true},{"text":" of England;"}]},{"text":[{"text":"the "},{"text":"doctrines of equity","bold":true},{"text":";"}]},{"text":[{"text":"the "},{"text":"statutes of general application","bold":true},{"text":" (SOGA) that were "},{"text":"in force in England on 1 January 1900","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Reception enactments","bold":true},{"text":" (local laws that brought English law in): "},{"text":"section 45(1) of the Interpretation Act","bold":true},{"text":" (now section 32(1), Interpretation Act, Cap I23 LFN 2004) and "},{"text":"section 14 of the Supreme Court Ordinance 1914","bold":true},{"text":", among others; also the High Court Laws of the States."}]},{"text":[{"text":"Timing rule:","bold":true},{"text":" common law and equity apply "},{"text":"as they stand in England on the day they are applied","bold":true},{"text":" in Nigeria (not limited by time). Only SOGA are tied to the "},{"text":"1 January 1900","bold":true},{"text":" cut-off."}]},{"text":[{"text":"A SOGA "},{"text":"remains in force in Nigeria even if later repealed in England","bold":true},{"text":", until a Nigerian legislature repeals it."}]},{"text":[{"text":"\"Statute of general application\" is not defined","bold":true},{"text":" by the Supreme Court Ordinance, the Interpretation Act or any other reception enactment; its meaning comes from "},{"text":"case law","bold":true},{"text":"."}]},{"text":[{"text":"Osborne CJ's \"rough but not infallible test\"","bold":true},{"text":" ("},{"text":"Attorney General v John Holt & Co Ltd","italic":true},{"text":" (1910)): ask (1) "},{"text":"by what courts","bold":true},{"text":" is the statute applied in England? (2) "},{"text":"to what classes of the community","bold":true},{"text":" in England does it apply?"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Applied by "},{"text":"all","bold":true},{"text":" civil and criminal courts to "},{"text":$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 32, $study_guide$"all","bold":true},{"text":" classes on 1 January 1900: "},{"text":"strong likelihood","bold":true},{"text":" it is in force here."}]},{"text":[{"text":"Applied only by "},{"text":"certain courts","bold":true},{"text":" (e.g. a statute regulating procedure) or only to "},{"text":"certain classes","bold":true},{"text":" (e.g. an Act regulating a particular trade): probably "},{"text":"not","bold":true},{"text":" locally applicable."}]}]}]},{"text":[{"text":"Foreign (including English) decisions","bold":true},{"text":" do not bind Nigerian courts; Nigeria is independent and sovereign, so they are only "},{"text":"persuasive","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cases holding statutes to be of general application:","bold":true}]}]},{"type":"table","header":[[{"text":"Case"}],[{"text":"Statute"}],[{"text":"Point"}]],"rows":[[[{"text":"Lawal v Younan","italic":true},{"text":" (1961), Federal Supreme Court"}],[{"text":"Fatal Accidents Acts 1846 and 1864"}],[{"text":"applied to all classes in England"}]],[[{"text":"Braithwaite v Folarin","italic":true},{"text":" (1938), WACA"}],[{"text":"Fraudulent Conveyances Act 1571"}],[{"text":"applies generally to ordinary affairs and dealings of men, without qualification"}]],[[{"text":"Young v Abina","italic":true},{"text":" (1940), WACA"}],[{"text":"Land Transfer Act 1897"}],[{"text":"applied generally to the estates of all persons dying in England after 1 January 1898"}]],[[{"text":"Labinjoh v Abake","italic":true},{"text":" (1924)"}],[{"text":"Infants Relief Act 1874"}],[{"text":"held a SOGA"}]],[[{"text":"Taylor v Taylor","italic":true},{"text":" (1934)"}],[{"text":"Trustee Act 1888"}],[{"text":"held a SOGA"}]],[[{"text":"Thomas v De Souza","italic":true},{"text":" (1929)"}],[{"text":"Real Property Limitation Act 1874"}],[{"text":"held a SOGA"}]],[[{"text":"Malomo v Olusola","italic":true},{"text":" (1954)"}],[{"text":"Statute of Frauds 1677"}],[{"text":"held a SOGA"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"_Dede v African Association Ltd_ (1910):","bold":true},{"text":" Weber J held that SOGA must mean statutes "},{"text":"applicable throughout the United Kingdom","bold":true},{"text":", not those in force in England only. This sits uneasily with the wording of the Ordinance, which expressly says \"in force in "},{"text":"England","bold":true},{"text":"\"."}]},{"text":[{"text":"Worked application: an English Act of 1890 regulating procedure in certain English courts, in force on 1 January 1900, would probably "},{"text":"not","bold":true},{"text":" be a SOGA (applied only by certain courts). An Act applied by all civil courts to all classes would "},{"text":"likely","bold":true},{"text":" be one, but the test is \"not infallible\", so never say \"certain\"."}]},{"text":[{"text":"Where SOGA do not apply:","bold":true},{"text":" the States carved from the old Western Region (Ogun, Ondo, Osun, Ekiti, Oyo, Edo, Delta) replaced SOGA, for matters within State competence, with their own Law of England (Application) Law 1959. They still apply in "},{"text":"Lagos","bold":true},{"text":" (the old colony of Lagos, named in the former section 45 of the Interpretation Act) and elsewhere, and everywhere on Federal matters."}]},{"text":[{"text":"Extended English law","bold":true},{"text":": English statutes extended to Nigeria by name, and Nigerian laws that adopt the English law of a subject. It forms part of \"English law\" as a primary source."}]},{"text":[{"text":"English Court of Appeal decision of 1995 cited in Abuja: "},{"text":"persuasive only","bold":true},{"text":"."}]},{"text":[{"text":"Essay hint (\"Whether an English statute is of general application is uncertain and controversial\"): reception provisions; no statutory definition; "},{"text":"Dede","italic":true},{"text":"; Osborne CJ's test; other cases; conclude with the two conditions: "},{"text":"in force in England on 1 January 1900","bold":true},{"text":" and "},{"text":"of general application","bold":true},{"text":"."}]}]}]},{"number":"8.3","title":"Nigerian legislation, the Constitution and delegated legislation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Nigerian legislation","bold":true},{"text":" = "},{"text":"statutes","bold":true},{"text":" + "},{"text":"subsidiary legislation","bold":true},{"text":"."}]},{"text":[{"text":"Statutes","bold":true},{"text":" = laws enacted by the legislative arm. Their name depends on when, by whom and under what government they were made:"}]}]},{"type":"table","header":[[{"text":"Name"}],[{"text":"Made by"}]],"rows":[[[{"text":"Ordinance","bold":true}],[{"text":"the Nigerian "},{"text":"central legislature before 1 October 1954","bold":true}]],[[{"text":"Act","bold":true}],[{"text":"the "},{"text":"National Assembly","bold":true},{"text":" (Senate + House of Representatives), civilian rule"}]],[[{"text":"Law","bold":true}],[{"text":"a "},{"text":"State House of Assembly","bold":true},{"text":", civilian rule"}]],[[{"text":"Decree","bold":true}],[{"text":"the "},{"text":"Federal Military Government","bold":true},{"text":", military rule"}]],[[{"text":"Edict","bold":true}],[{"text":"a "},{"text":"Military Governor/Administrator of a State","bold":true},{"text":", military rule"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"1 October 1954","bold":true},{"text":" is the dividing line because "},{"text":"federalism","bold":true},{"text":" was introduced by the "},{"text":"Lyttelton Constitution","bold":true},{"text":", which came into force that day."}]},{"text":[{"text":"Legislation","bold":true},{"text":" is the "},{"text":"most important source","bold":true},{"text":" of law in a modern nation and the "},{"text":"\"measuring scale\"","bold":true},{"text":" for the efficacy of other legal sources; it can alter their content."}]},{"text":[{"text":"Constitution of the Federal Republic of Nigeria 1999:","bold":true},{"text":" came $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 33, $study_guide$into force on "},{"text":"29 May 1999","bold":true},{"text":"; the highest law, from which all other laws derive validity. "},{"text":"Section 1","bold":true},{"text":" proclaims its "},{"text":"supremacy","bold":true},{"text":" over all other laws, authorities and persons; any law inconsistent with it is "},{"text":"void to the extent of the inconsistency","bold":true},{"text":" (s 1(3))."}]},{"text":[{"text":"Division of legislative powers (s 4):","bold":true},{"text":" "},{"text":"Exclusive List","bold":true},{"text":" (Part I, Second Schedule): National Assembly only. "},{"text":"Concurrent List","bold":true},{"text":" (Part II): both National Assembly and State Houses of Assembly. "},{"text":"Residual matters","bold":true},{"text":" (on neither list): States only."}]},{"text":[{"text":"Subsidiary (delegated) legislation:","bold":true},{"text":" law made by persons or bodies other than the legislature under express powers conferred by a statute, called the "},{"text":"enabling statute","bold":true},{"text":". Examples: "},{"text":"bye-laws","bold":true},{"text":" of local governments, "},{"text":"regulations","bold":true},{"text":" of public corporations, "},{"text":"statutory instruments","bold":true},{"text":" of ministers (also rules, orders). An Act of the National Assembly is "},{"text":"not","bold":true},{"text":" subsidiary legislation."}]},{"text":[{"text":"Ultra vires:","bold":true},{"text":" delegated legislation that exceeds the power granted is "},{"text":"beyond power, null and void","bold":true},{"text":"."}]},{"text":[{"text":"Laws of the Federation of Nigeria (LFN):","bold":true},{"text":" all federal statutes up to "},{"text":"31 January 1990","bold":true},{"text":" consolidated as "},{"text":"LFN 1990","bold":true},{"text":"; revised up to 2002 and published as "},{"text":"LFN 2004","bold":true},{"text":" in "},{"text":"loose-leaf","bold":true},{"text":" format, so future amendments can be "},{"text":"easily incorporated","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Reasons for delegated legislation:","bold":true},{"text":" (1) it is practically impossible for the legislature to make laws for every aspect of life; (2) unforeseeable variations in events and conduct; (3) many areas need "},{"text":"technical expertise","bold":true},{"text":" the legislature lacks; (4) the legislature sets the general framework and leaves "},{"text":"specialists, technocrats and those involved in specific activities","bold":true},{"text":" to handle particular cases (e.g. professional bodies under the Legal Practitioners Act regulating their members). Allowing administrators to "},{"text":"override","bold":true},{"text":" the enabling statute is never a reason."}]},{"text":[{"text":"Arguments against:","bold":true},{"text":" less democratic (made by unelected bodies), weaker scrutiny, risk of abuse, sheer volume makes it hard for citizens to know the law. "},{"text":"Controls:","bold":true},{"text":" the courts (ultra vires), the legislature (amending or revoking the enabling power)."}]},{"text":[{"text":"Worked example: a State Law allows a local government to fix fines of up to ₦5,000 for illegal dumping; its bye-law fixes ₦50,000. The fine exceeds the delegated power by ₦45,000 (10 times the limit), so it is "},{"text":"ultra vires and liable to be declared null and void","bold":true},{"text":"."}]},{"text":[{"text":"Dating examples: 1950 central enactment = "},{"text":"Ordinance","bold":true},{"text":"; 1976 State Military Governor = "},{"text":"Edict","bold":true},{"text":"; 2015 Lagos State House of Assembly = "},{"text":"Law","bold":true},{"text":". Trap: an Edict was "},{"text":"never","bold":true},{"text":" made by the Federal Military Government."}]},{"text":[{"text":"A State Law conflicting with the Constitution is "},{"text":"void to the extent of the inconsistency","bold":true},{"text":"; recency and State autonomy do not save it."}]},{"text":[{"text":"Legislation also "},{"text":"validates and modifies","bold":true},{"text":" other sources: the Interpretation Act receives English law; the High Court Laws validate customary law; the Criminal Code abolished trial by ordeal and witchcraft practices."}]},{"text":[{"text":"Nigeria became independent on "},{"text":"1 October 1960","bold":true},{"text":" and a republic on "},{"text":"1 October 1963","bold":true},{"text":" (do not confuse with 1954)."}]}]}]},{"number":"8.4","title":"Customary law and Islamic law","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Customary law:","bold":true},{"text":" the customs accepted by members of a community as binding among them."}]},{"text":[{"text":"Classification:","bold":true},{"text":" (1) "},{"text":"ethnic (non-Moslem) customary law","bold":true},{"text":": indigenous, "},{"text":"unwritten","bold":true},{"text":", varies from one ethnic group to another; (2) "},{"text":"Moslem (Islamic) law","bold":true},{"text":": "},{"text":"largely written","bold":true},{"text":"."}]},{"text":[{"text":"Sources of Islamic law (the Sharia):","bold":true},{"text":" 1. the "},{"text":"Holy Quran","bold":true},{"text":"; 2. the "},{"text":"Sunna","bold":true},{"text":" (practice of the Prophet); 3. "},{"text":"consensus","bold":true},{"text":" of Islamic scholars (ijma); 4. "},{"text":"analogical deductions","bold":true},{"text":" from the holy writ (qiyas). The predominant school in Nigeria is the "},{"text":"Maliki","bold":true},{"text":" school."}]},{"text":[{"text":"Features:","bold":true},{"text":" acceptance as obligatory by the community; "},{"text":"flexibility and adaptability","bold":true},{"text":". "},{"text":"Lewis v Bankole","italic":true},{"text":" (1908), Osborne CJ: \"One of the most striking features of West African native custom … is its "},{"text":"flexibility","bold":true},{"text":"; it appears to have been always subject to motives of expediency, and it shows unquestionable "},{"text":"adaptability to $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 34, $study_guide$altered circumstances without entirely losing its character","bold":true},{"text":".\""}]},{"text":[{"text":"3 validity tests","bold":true},{"text":" (prescribed by "},{"text":"statute","bold":true},{"text":": the High Court Laws of the 36 States and the FCT, e.g. s 44 High Court Law, Oyo State 1978). A court enforces a customary rule only if it is "},{"text":"not","bold":true},{"text":":"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"repugnant to natural justice, equity and good conscience","bold":true},{"text":";"}]},{"text":[{"text":"contrary to public policy","bold":true},{"text":";"}]},{"text":[{"text":"incompatible, directly or by implication, with any law for the time being in force","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Inconsistency with English law is NOT a ground of invalidity.","bold":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Repugnancy cases:","bold":true}]}]},{"type":"table","header":[[{"text":"Case"}],[{"text":"Holding"}]],"rows":[[[{"text":"Eshugbayi Eleko v Officer Administering the Government of Nigeria","italic":true},{"text":" [1931] AC 662"}],[{"text":"Lord Atkin: a "},{"text":"barbarous","bold":true},{"text":" custom must be rejected as repugnant"}]],[[{"text":"Dawodu v Danmole","italic":true},{"text":" (1958, Privy Council 1962)"}],[{"text":"idi-igi","bold":true},{"text":" (distribution "},{"text":"per stirpes","bold":true},{"text":", by each wife's branch of children) is "},{"text":"not","bold":true},{"text":" repugnant; Privy Council rejected Jibowu's view that it breached equality (per capita, "},{"text":"ori-ojori","bold":true},{"text":"). Natural justice in a polygamous society is not equated with that of a monogamous one"}]],[[{"text":"Re Effiong Okon Atta","italic":true},{"text":" (1930)"}],[{"text":"custom letting a former slave owner administer the slave's personal estate after death: "},{"text":"repugnant","bold":true}]],[[{"text":"Guri v Hadejia Native Authority","italic":true},{"text":" (1959)"}],[{"text":"rule denying a person accused of highway robbery (hiraba) the right to "},{"text":"defend himself","bold":true},{"text":": "},{"text":"repugnant","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Public policy:","bold":true},{"text":" "},{"text":"Cole v Akinyele","italic":true},{"text":" (1960), Brett FJ (Federal Supreme Court): a custom that a child born out of wedlock, once paternity is accepted, becomes legitimate and shares equally with children of a marriage under the Marriage Ordinance was "},{"text":"invalid on grounds of public policy","bold":true},{"text":"."}]},{"text":[{"text":"Incompatibility:","bold":true},{"text":" if a State Law expressly prohibits what a custom permits, the custom fails the incompatibility test. Example: section 3 of the Legitimacy Act modified the Yoruba custom of acknowledgement."}]},{"text":[{"text":"The repugnancy clause "},{"text":"has not received a detailed and settled explanation","bold":true},{"text":"; its meaning is gathered from decided cases."}]},{"text":[{"text":"No customary crimes:","bold":true},{"text":" customary criminal law has been displaced. Section 36(12) of the 1999 Constitution says no one shall be convicted of an offence unless it is "},{"text":"defined and its penalty prescribed in a written law","bold":true},{"text":" (Criminal Code, Penal Code, etc.). In "},{"text":"Aoko v Fagbemi","italic":true},{"text":" (1961) a conviction for adultery, not an offence in written law, was quashed. Customary law now operates in civil matters."}]},{"text":[{"text":"Afar problem","bold":true},{"text":" (Agbor custom: robbery suspect not heard): invalid as "},{"text":"repugnant","bold":true},{"text":", following "},{"text":"Guri","italic":true},{"text":". Not because it differs from English procedure. Outline: importance of custom; statutory basis; three tests; uncertainty of repugnancy; "},{"text":"Guri","italic":true},{"text":"; conclude."}]},{"text":[{"text":"Justice Dede problem","bold":true},{"text":" (striking down every custom inconsistent with English law): wrong. Judge customs only by the three statutory tests; cite "},{"text":"Dawodu v Danmole","italic":true},{"text":"."}]},{"text":[{"text":"Diversity of ethnic customary law is a major obstacle to uniformity within each State."}]}]}]},{"number":"8.5","title":"Judicial precedent, international law and secondary sources","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Judicial precedent:","bold":true},{"text":" the practice whereby the earlier decision of a court is followed in later similar cases; a "},{"text":"lower","bold":true},{"text":" court "},{"text":"must follow","bold":true},{"text":" the earlier decision of a "},{"text":"higher","bold":true},{"text":" court. What judges make is "},{"text":"case law","bold":true},{"text":"."}]},{"text":[{"text":"Stare decisis","bold":true},{"text":" = \"let the decision stand\"."}]},{"text":[{"text":"Ratio decidendi","bold":true},{"text":" = the reason for the decision: the legal principle necessary for the decision, which "},{"text":"binds","bold":true},{"text":" later lower courts. "},{"text":"Obiter dictum","bold":true},{"text":" = a remark made \"by the way\", not necessary to the decision: "},{"text":"not binding","bold":true},{"text":", only persuasive."}]},{"text":[{"text":"Advantages:","bold":true},{"text":" ready solutions to legal problems; uniformity, consistency and certainty; lets lawyers, litigants and the public "},{"text":"predict","bold":true},{"text":" outcomes; settled expectations are not disrupted through default, mischief or ignorance."}]},{"text":[{"text":"Forms of precedent:","bold":true},{"text":" 1. "},{"text":"Original","bold":true},{"text":": a new rule where no similar earlier case exists (e.g. "},{"text":"Carlill v Carbolic Smoke Ball Co","italic":true},{"text":" [1893] on offer). 2. "},{"text":"Derivative","bold":true},{"text":": extends an exist$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 35, $study_guide$ing rule "},{"text":"by analogy","bold":true},{"text":" to a new situation. 3. "},{"text":"Declaratory","bold":true},{"text":": restates an existing rule, giving it "},{"text":"added weight and authority","bold":true},{"text":"."}]},{"text":[{"text":"Stare decisis is impracticable without (1) a "},{"text":"hierarchy of courts","bold":true},{"text":" and (2) an "},{"text":"efficient system of law reporting","bold":true},{"text":"."}]},{"text":[{"text":"International law","bold":true},{"text":" (historically "},{"text":"jus gentium","bold":true},{"text":", the law of nations): no nation can exist in isolation. Treaties, conventions, covenants and declarations. In Nigeria a "},{"text":"treaty does not operate as law until the National Assembly enacts it into law","bold":true},{"text":" (s 12, 1999 Constitution)."}]},{"text":[{"text":"Sani Abacha v Gani Fawehinmi","italic":true},{"text":" (2000): the "},{"text":"African Charter on Human and Peoples' Rights","bold":true},{"text":" (1981), incorporated by statute, is "},{"text":"enforceable in Nigerian courts","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A Kaduna State High Court facing facts materially similar to a Supreme Court decision "},{"text":"must follow its ratio","bold":true},{"text":"; fairness or the report it appears in does not matter."}]},{"text":[{"text":"Allowing a judge to depart freely from higher decisions he dislikes is "},{"text":"not","bold":true},{"text":" an advantage; it destroys certainty."}]},{"text":[{"text":"Ratified but unenacted convention (ratified 2020, not enacted): "},{"text":"not enforceable","bold":true},{"text":" as law in Nigeria, however strong the trader's claim. Executive signature or ratification is not enough. (Jus cogens rules are an exception binding regardless of incorporation.)"}]},{"text":[{"text":"Secondary sources:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Law reports:","bold":true},{"text":" essential where precedent operates, because only by reference to reported cases can courts and lawyers ascertain the law. Oldest: the "},{"text":"Year Books","bold":true},{"text":" (about 1283 to 1535). First Nigerian series: the "},{"text":"Nigerian Law Reports","bold":true},{"text":" (covering decisions from 1881), now extinct. Current: "},{"text":"NWLR","bold":true},{"text":" (since 1985), "},{"text":"SCNJ","bold":true},{"text":", "},{"text":"LRCN","bold":true},{"text":", "},{"text":"All NLR","bold":true},{"text":", Federation Weekly Law Reports. Sustainability is a weakness of Nigerian law reporting."}]},{"text":[{"text":"Textbooks and treatises:","bold":true},{"text":" English classics (Bracton, Coke, Blackstone; later Dicey, Cheshire, Hood Phillips, Wade); Nigerian (Obilade, Nwogwugwu, Okonkwo, Kodilinye, Aguda; Sagay on international law). Persuasive; weight depends on the author and the subject."}]},{"text":[{"text":"Periodicals and journals:","bold":true},{"text":" professional, academic or both (faculty journals)."}]},{"text":[{"text":"Law digests","bold":true},{"text":" (e.g. the Digest of Supreme Court Cases): "},{"text":"abridgements","bold":true},{"text":" of cases summarising facts, issues, arguments and decisions."}]},{"text":[{"text":"Dictionaries:","bold":true},{"text":" Jowitt's Dictionary of English Law, Stroud's Judicial Dictionary."}]}]}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sources = materials through which a lawyer or court finds reliable authorities."}]},{"text":[{"text":"Primary bind (English law, legislation, case law, customary/Islamic law); secondary persuade."}]},{"text":[{"text":"Received English law = common law + equity + SOGA in force in England on 1 January 1900 (s 45/32 Interpretation Act; s 14 Supreme Court Ordinance 1914)."}]},{"text":[{"text":"SOGA undefined by statute; Osborne CJ's test asks which courts and which classes; SOGA survive English repeal."}]},{"text":[{"text":"Ordinance (pre-1 October 1954), Act, Law, Decree, Edict; Constitution supreme (s 1), in force 29 May 1999."}]},{"text":[{"text":"Delegated legislation beyond its enabling power is ultra vires and void."}]},{"text":[{"text":"Custom valid unless repugnant, contrary to public policy or incompatible with written law; "},{"text":"Eleko","italic":true},{"text":", "},{"text":"Dawodu","italic":true},{"text":", "},{"text":"Atta","italic":true},{"text":", "},{"text":"Guri","italic":true},{"text":", "},{"text":"Cole v Akinyele","italic":true},{"text":"."}]},{"text":[{"text":"Islamic law: Quran, Sunna, consensus, analogy; Maliki school."}]},{"text":[{"text":"Stare decisis = let the decision stand; ratio binds, obiter persuades; needs hierarchy and law reporting."}]},{"text":[{"text":"Treaties bind only once enacted by the National Assembly ("},{"text":"Abacha v Fawehinmi","italic":true},{"text":")."}]}]}],"theory":{"itemId":"26d0c68c-8b07-5936-9b53-0696aaa660fa","question":[{"type":"paragraph","text":[{"text":"\"Customary law is a veritable source of Nigerian law only in so far as it passes the tests of validity.\" Discuss with decided cases."}]}]},"practice":[{"topic":"Sources of Nigerian Law","named":false}]}},{"kind":"note","itemId":"b5b0719c-44d1-5027-a44c-61ff91dfbd3d","sourceKey":"guide-topic:9","position":9,"payload":{"title":"Legal Research and Legal Writing","body":"Meaning of and reasons for legal research; the library, the librarian, classification, call numbers and the catalogue; statutes, law reports and how to cite and trace cases; periodicals, reference books and databases; types of essay and the steps in essay writing; hints on good writing; answering essay questions (IDBC) and problem questions (IRAC).","noteType":"guide_topic","number":9,"mustKnow":[{"text":"Meaning of and reasons for legal research; the library, the librarian, classification, call numbers and the catalogue; statutes, law reports and how to cite and trace cases; periodicals, reference books$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 36, $study_guide$ and databases; types of essay and the steps in essay writing; hints on good writing; answering essay questions (IDBC) and problem questions (IRAC)."}],"lessons":[{"number":"9.1","title":"Meaning of legal research and why it matters","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Research","bold":true},{"text":" (in legal method): the use of library materials to seek recorded information on a particular legal problem in order to "},{"text":"authoritatively determine the rights, duties and liabilities of the parties","bold":true},{"text":"."}]},{"text":[{"text":"Saying attributed to King George: "},{"text":"lawyers do not know much more law than other people, but they know better where to find it","bold":true},{"text":". It stresses legal research and effective use of the library."}]},{"text":[{"text":"Why research:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Law is "},{"text":"not static","bold":true},{"text":"; it is "},{"text":"dynamic and developing","bold":true},{"text":", so the lawyer must find the "},{"text":"current","bold":true},{"text":" rules."}]},{"text":[{"text":"Findings help the lawyer "},{"text":"persuade the court","bold":true},{"text":" to adopt his reasoning or interpretation."}]},{"text":[{"text":"Diligent research and advocacy can persuade a court to adopt a "},{"text":"new position","bold":true},{"text":" or even "},{"text":"reverse its earlier decision","bold":true},{"text":"."}]},{"text":[{"text":"Research leads to the "},{"text":"primary sources","bold":true},{"text":" of law. The library is to a lawyer what the laboratory is to a scientist."}]}]}]},{"text":[{"text":"Glanville Williams' warning:","bold":true},{"text":" the great disadvantage of confining yourself to textbooks and lecture notes is that you take "},{"text":"all your law at second hand","bold":true},{"text":". The law is in "},{"text":"statutes and judicial decisions","bold":true},{"text":"; what the text writer thinks is not, in itself, law, and he may have misinterpreted the authorities. Going to them is going to \"the fountain head\"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The law librarian","bold":true},{"text":" is a specialist on which sources are relevant to a subject (better still if legally trained). Once the subject area is identified, a competent librarian can "},{"text":"assemble the primary and secondary materials","bold":true},{"text":" for you. Such librarians are rare, so you must still know how to use the library yourself. The librarian does not write your opinion or decide cases."}]},{"text":[{"text":"A library is a "},{"text":"storehouse of information","bold":true},{"text":" in many forms; law is multidisciplinary, so research is not limited to legal materials."}]},{"text":[{"text":"Essay hint (\"A good lawyer knows the law; a better lawyer knows where to find it; the best knows both\"): explain research and its reasons; the librarian's role and its limits; even a lawyer who seems sure must "},{"text":"verify","bold":true},{"text":" his conclusion from source materials."}]},{"text":[{"text":"Trap: \"the law is static, so research once\" is the classic wrong option."}]}]}]},{"number":"9.2","title":"Finding books: classification, call numbers and the catalogue","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"6 elements identifying a book:","bold":true},{"text":" 1. the cover; 2. the author's name; 3. the publisher; 4. the title; 5. the place of publication; 6. the date of publication. All except the cover appear on the "},{"text":"title page","bold":true},{"text":". (The name of the owning library is "},{"text":"not","bold":true},{"text":" one.)"}]},{"text":[{"text":"Books are arranged by "},{"text":"subject","bold":true},{"text":" under a "},{"text":"classification system","bold":true},{"text":", not by colour or size. The two commonest:"}]}]},{"type":"table","header":[[{"text":"System"}],[{"text":"Call mark begins with"}],[{"text":"Example"}]],"rows":[[[{"text":"Library of Congress","bold":true},{"text":" (used by most Nigerian libraries)"}],[{"text":"a "},{"text":"letter","bold":true}],[{"text":"K108.7"}]],[[{"text":"Dewey Decimal","bold":true}],[{"text":"a "},{"text":"number","bold":true}],[{"text":"642.13"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Library of Congress:","bold":true},{"text":" 21 letters mark broad subject classes, e.g. A General works, B Philosophy, H Social Science, J Political Science, "},{"text":"K Law","bold":true},{"text":", Z Bibliography."}]},{"text":[{"text":"Call number:","bold":true},{"text":" identifies a book as a fingerprint identifies a person; no two books share one. In "},{"text":"B358.C54","bold":true},{"text":": "},{"text":"B","bold":true},{"text":" = broad subject (philosophy); "},{"text":"358","bold":true},{"text":" = sub-topic; "},{"text":"C","bold":true},{"text":" = first letter of the author's last name; "},{"text":"54","bold":true},{"text":" = number further identifying the author."}]},{"text":[{"text":"Shelving rule:","bold":true},{"text":" first alphabetically by the subject letter, then numerically by the subject number, then alphabetically by the author letter, then by the author number (read as a decimal)."}]},{"text":[{"text":"Catalogue:","bold":true},{"text":" lists "},{"text":"all","bold":true},{"text":" the library's books. Materials can be found by "},{"text":"author, title or subject","bold":true},{"text":" (author entry, title entry, subject entry). The "},{"text":"author entry is the main entry","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example (shelving):","bold":true},{"text":" order B358.C54, B200.C57, K146.O2, B200.A18."}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Letter: the three B books come before K146.O2."}]},{"text":[{"text":"Number: B200 comes before B358."}]}$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 37, $study_guide$,{"text":[{"text":"Author letter within B200: A18 before C57."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Order: "},{"text":"B200.A18, B200.C57, B358.C54, K146.O2","bold":true},{"text":". So B200.A18 is shelved first."}]}]}]},{"text":[{"text":"Why the catalogue beats browsing","bold":true},{"text":", even with open stacks: a browser may miss books that are "},{"text":"borrowed, waiting to be reserved or on the reserve shelf","bold":true},{"text":"; the catalogue lists them all and saves time. In a "},{"text":"closed-stack","bold":true},{"text":" library it is indispensable."}]},{"text":[{"text":"Forms of catalogue: printout book catalogues, microfilm or microfiche, and most commonly the "},{"text":"card catalogue","bold":true},{"text":"."}]},{"text":[{"text":"Author entry","bold":true},{"text":" shows everything on the title page (full name, full title, publisher, place and year) plus pages, series and the other entries. If you know the author but not the exact title, "},{"text":"check the author entry","bold":true},{"text":", note the call number, go to the shelf. Literary works are often not entered by subject."}]}]}]},{"number":"9.3","title":"Statutes, law reports and citing cases","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Nigeria has the FCT and "},{"text":"36 States","bold":true},{"text":"; "},{"text":"each State has its own system of law and courts","bold":true},{"text":", and the Federation and FCT have theirs (Laws of Kano State, Laws of Lagos State, Laws of the FCT, Laws of the Federation). A bail application in the Ogun State High Court is brought under "},{"text":"the law of Ogun State","bold":true},{"text":"."}]},{"text":[{"text":"Modern law report contains:","bold":true},{"text":" name of the case, date, court and judges; "},{"text":"headnote","bold":true},{"text":"; outline of the facts; names of counsel; sometimes a summary of their arguments; and "},{"text":"always a verbatim copy of the judgment","bold":true},{"text":". It does "},{"text":"not","bold":true},{"text":" give the reporter's own verdict."}]},{"text":[{"text":"Citation of a reported case:","bold":true},{"text":" names of the parties, the year (or month), the volume, the name of the law report and the page."}]},{"text":[{"text":"Square brackets [ ]:","bold":true},{"text":" the year is "},{"text":"essential","bold":true},{"text":" to locate the case, e.g. "},{"text":"FBIR v Nasr","italic":true},{"text":" [1964] 1 All NLR 408. "},{"text":"Round brackets ( ):","bold":true},{"text":" the year is "},{"text":"not essential","bold":true},{"text":", e.g. "},{"text":"Ademolekun v Council of UI","italic":true},{"text":" (1967) All NLR 40."}]},{"text":[{"text":"NWLR style:","bold":true},{"text":" "},{"text":"Marina Nominees Ltd v FBIR","italic":true},{"text":" [1986] 2 NWLR (Pt 20) 40: 2 = volume, "},{"text":"Pt 20 = part 20","bold":true},{"text":", 40 = page. Part and page matter most; "},{"text":"a part number is never duplicated","bold":true},{"text":"."}]},{"text":[{"text":"NWLR","bold":true},{"text":" (from 1 October 1985) comes out "},{"text":"weekly","bold":true},{"text":" and reports "},{"text":"Court of Appeal and Supreme Court","bold":true},{"text":" cases; "},{"text":"SCNJ","bold":true},{"text":" reports "},{"text":"only Supreme Court","bold":true},{"text":" cases, usually every month or two."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Tracing a case:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"With the citation: go to the shelf for that report and trace by year, or by volume plus part (NWLR)."}]},{"text":[{"text":"Title known but not the citation, or citation incomplete (e.g. "},{"text":"Adeolu v Mabamiye","italic":true},{"text":" (1985) 2 NWLR p.5, part missing): check the "},{"text":"list of cases","bold":true},{"text":" in a standard textbook on the subject, or an "},{"text":"index","bold":true},{"text":", for the full citation; otherwise search all that year's volumes. English cases: the Current Law Case Citators (from 1947) or the English Digest."}]},{"text":[{"text":"All cases on a subject: use a "},{"text":"case index","bold":true},{"text":", arranged alphabetically (locus standi under "},{"text":"L","bold":true},{"text":"). Judicially defined words (\"reasonable cause\", \"and\", \"beyond reasonable doubt\") are under "},{"text":"\"Words and phrases\"","bold":true},{"text":". If the index is in arrears, check the list of cases in each recent issue."}]}]}]},{"text":[{"text":"History:","bold":true},{"text":" Year Books (Anglo-French, about 1283 to 1535); private reports (Dyer from 1537; Coke's \"The Reports\", 1572-1616; Burrow, 1756-1772); then the modern period. Nigeria: Renner's reports (Gold Coast decisions, 1874-1886, when Lagos was part of that colony); regular reporting from "},{"text":"1916","bold":true},{"text":" with the "},{"text":"Nigerian Law Reports (NLR)","bold":true},{"text":", covering decisions from 1881 to 1955. Later: NMLR (1964), NWLR (1985), SCNJ, Federation Weekly Law Reports (2000). Most official series have died out."}]},{"text":[{"text":"Nigerian vs foreign reports:","bold":true},{"text":" NWLR, SCNJ, All NLR, LRCN are Nigerian. "},{"text":"WLR","bold":true},{"text":" (Weekly Law Reports), "},{"text":"AC","bold":true},{"text":" (Appeal Cases), "},{"text":"All ER","bold":true},{"text":" (All England Law Reports, from 1936), QB, Ch are English."}]},{"text":[{"text":"Statute books:","bold":true},{"text":" governments publish their Acts or Laws and periodically consolidate them (e.g. Laws of the Federation 1990). Check other States' laws, which may differ."}]}]}]},{"number":"9.4","title":"Periodicals, reference books and information technology","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Periodicals (journals)","bold":true},{"text":" differ from books: (1) they appear "},{"text":"at intervals","bold":true},{"text":" (weekly, mo$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 38, $study_guide$nthly, quarterly, etc.); a book treats its subject in one complete edition; (2) articles are "},{"text":"briefer","bold":true},{"text":", so you reach the essentials faster; (3) they contain articles by "},{"text":"different writers","bold":true},{"text":". Use them where a topic is too recent for any book."}]},{"text":[{"text":"2 types of journal:","bold":true},{"text":" "},{"text":"general","bold":true},{"text":" (many fields) and "},{"text":"specialised","bold":true},{"text":" (one field: banking, taxation, property)."}]},{"text":[{"text":"Periodical index:","bold":true},{"text":" the best tool when you have no citation or do not know which articles exist; it does for articles what the "},{"text":"catalogue","bold":true},{"text":" does for books."}]},{"text":[{"text":"Reference books:","bold":true},{"text":" for brief facts (meaning of a word, date of an event, a quotation, a place) without reading cover to cover. They "},{"text":"do not circulate","bold":true},{"text":", are used in the reference section, and carry "},{"text":"\"R\" or \"REF\"","bold":true},{"text":" above the call number."}]},{"text":[{"text":"2 types of reference book:","bold":true},{"text":" "},{"text":"general","bold":true},{"text":" (dictionaries, encyclopaedias, year books, atlases, directories) and "},{"text":"subject","bold":true},{"text":" (e.g. Black's Law Dictionary, Stroud's Judicial Dictionary, Jowitt's Dictionary of English Law, Osborn's Concise Law Dictionary, Mozley and Whiteley's Law Dictionary, Fawehinmi's Bar and Bench in Nigeria)."}]},{"text":[{"text":"Halsbury's Laws of England:","bold":true},{"text":" the most comprehensive legal "},{"text":"encyclopaedia","bold":true},{"text":", covering all areas of English law; the "},{"text":"take-off point","bold":true},{"text":" for legal research. Encyclopaedias are more current than textbooks."}]},{"text":[{"text":"Lexis and Westlaw:","bold":true},{"text":" "},{"text":"legal databases","bold":true},{"text":" making recent judicial decisions and legislation available electronically."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Nigerian journals: Nigerian Current Law Review, Nigerian Law Journal, Journal of Islamic and Comparative Law; most law faculties publish one. Foreign: Cambridge Law Journal, Harvard Law Review."}]},{"text":[{"text":"Amaka, researching recent banking-law developments with no article or citation in mind: use the "},{"text":"periodical index","bold":true},{"text":", not one-by-one browsing."}]},{"text":[{"text":"Student needing only the meaning of \"locus standi\" and a historical date: a "},{"text":"reference book","bold":true},{"text":" (law dictionary) in the reference section."}]}]}]},{"number":"9.5","title":"Legal writing: essay types and the writing process","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Essay:","bold":true},{"text":" a short piece of writing on a given subject; a literary composition, usually in prose, reflecting the writer's thoughts, ideas and viewpoints on an issue."}]},{"text":[{"text":"4 types of essay:","bold":true}]}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"Feature"}],[{"text":"Example"}]],"rows":[[[{"text":"Descriptive","bold":true}],[{"text":"reconstructs how a situation looks or feels, with the writer's feeling"}],[{"text":"a detainee describing his privations (Awolowo, "},{"text":"My March Through Prison","italic":true},{"text":")"}]],[[{"text":"Narrative","bold":true}],[{"text":"events in the order they occurred"}],[{"text":"Constitutional development in Nigeria from 1914 to date"}]],[[{"text":"Expository","bold":true}],[{"text":"explains, clarifies, informs, using illustrations and analogies"}],[{"text":"scope of separation of powers, rule of law, natural justice"}]],[[{"text":"Argumentative","bold":true}],[{"text":"takes a stand, persuades, "},{"text":"demolishes opposing arguments","bold":true}],[{"text":"\"The Abolition of the Death Penalty: To Be or Not to Be?\""}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Types may "},{"text":"overlap","bold":true},{"text":" and be combined, but aim for a clear focus."}]},{"text":[{"text":"Steps in essay writing:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Choose a topic:","bold":true},{"text":" do I want insight into it? will I find the materials? is the scope manageable? A good topic is "},{"text":"correct, complete and concise","bold":true},{"text":"."}]},{"text":[{"text":"Preliminary reading.","bold":true}]},{"text":[{"text":"Review (rethink) the topic:","bold":true},{"text":" hit it with every question; if stuck, use "},{"text":"what? who? where? when? how? why?","bold":true}]},{"text":[{"text":"Identify the basic question","bold":true},{"text":" (the most important, instructive, interesting and appropriate)."}]},{"text":[{"text":"Formulate the thesis:","bold":true},{"text":" turn the basic question into a basic answer. A definite thesis makes a "},{"text":"restricted and organised assertion about the topic and clearly reveals your attitude","bold":true},{"text":" towards it."}]},{"text":[{"text":"Test the idea","bold":true},{"text":" (4 tests): "},{"text":"writing","bold":true},{"text":", "},{"text":"credibility","bold":true},{"text":", "},{"text":"friendly colleague","bold":true},{"text":", "},{"text":"possibility","bold":true},{"text":"."}]},{"text":[{"text":"Prepare the outline.","bold":true}]},{"text":[{"text":"Choose materials.","bold":true}]},{"text":[{"text":"Examine sources:","bold":true},{"text":" organise your reading time; read "},{"text":"selectively","bold":true},{"text":", "},{"text":"responsibly","bold":true},{"text":", "},{"text":"critically","bold":true},{"text":"."}]},{"text":[{"text":"Write the drafts","bold":true},{"text":" (at least 4 recommended)."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The 4 tests:","bold":true},{"text":" "},{"text":"writing","bold":tr$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 39, $study_guide$ue},{"text":": put the idea on paper to think, revise and rearrange; "},{"text":"credibility","bold":true},{"text":": is it current, plausible and accurate, will it date?; "},{"text":"friendly colleague","bold":true},{"text":": give it to someone, ideally one who has researched the topic, for the most ruthless critique; "},{"text":"possibility","bold":true},{"text":": can you finish in the time and handle the issues? \"Repugnancy\" is not one of them."}]},{"text":[{"text":"Choosing materials:","bold":true},{"text":" books specifically on the topic; related materials (indexes, tables, charts, the author's references); "},{"text":"current","bold":true},{"text":" books and journals (latest editions); "},{"text":"classics","bold":true},{"text":" still relevant as guideposts, e.g. Elias on land law (some forty-one years old) or "},{"text":"Obilade's _The Nigerian Legal System_","bold":true},{"text":". Better a few valuable points than a shallow bite of everything."}]},{"text":[{"text":"Reading critically","bold":true},{"text":" = asking: will it command respect when cited? are the conclusions justified by the evidence? is the reasoning faulty? has the writer covered the subject?"}]},{"text":[{"text":"Drafts:","bold":true},{"text":" "},{"text":"first","bold":true},{"text":": write the whole paper without stopping to correct: \""},{"text":"Don't get it right, get it written","bold":true},{"text":"\"; "},{"text":"second","bold":true},{"text":": add omitted words and missing details; "},{"text":"third","bold":true},{"text":": cut the \""},{"text":"dead wood","bold":true},{"text":"\" of repetition and verbosity; address content, organisation, logic, coherence; move from a "},{"text":"writer-oriented draft to a reader-oriented work","bold":true},{"text":"; then keep reviewing to a finished product."}]},{"text":[{"text":"Divisions:","bold":true},{"text":" chapters (1, 2), sections (2.1), subsections (2.5.1); letters or Roman numerals also work."}]}]}]},{"number":"9.6","title":"Good writing and answering law questions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Hints on good writing:","bold":true},{"text":" introduction, originality, clarity, brevity, grammatical expression, accuracy, organisation, use of paragraphs, mechanical accuracy, conclusion."}]},{"text":[{"text":"Effective introduction:","bold":true},{"text":" "},{"text":"identifies the subject, arouses interest, is brief","bold":true},{"text":". It may be written last, once the body is organised."}]},{"text":[{"text":"Plagiarism:","bold":true},{"text":" the use of thoughts and ideas belonging to others "},{"text":"without acknowledgement","bold":true},{"text":"."}]},{"text":[{"text":"Brevity:","bold":true},{"text":" saying much in few words, never at the expense of substance."}]},{"text":[{"text":"3 kinds of conclusion:","bold":true},{"text":" "},{"text":"reflective","bold":true},{"text":" (highlights related issues and questions for future inquiry); "},{"text":"looking-ahead","bold":true},{"text":" (predicts or warns about the future); "},{"text":"straightforward","bold":true},{"text":" (states the end and makes suggestions and recommendations)."}]},{"text":[{"text":"Socio-legal analysis:","bold":true},{"text":" use a "},{"text":"multidimensional approach","bold":true},{"text":", not a strictly legal solution (e.g. cultism needs psychological, social, economic and political factors considered)."}]},{"text":[{"text":"Essay questions: IDBC","bold":true},{"text":" = "},{"text":"Introduction, Definition, Body, Conclusion","bold":true},{"text":"."}]},{"text":[{"text":"Problem questions: IRAC (or IPAC)","bold":true},{"text":" = "},{"text":"Issue(s), Rule (or Principle), Application (or Analysis), Conclusion","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"IDBC in practice:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Introduction:","bold":true},{"text":" background to the question (an apt quotation from a scholar or court helps), then a "},{"text":"thesis statement","bold":true},{"text":" saying what you will discuss. "},{"text":"Common mistake:","bold":true},{"text":" starting the body in the introduction, which loses the introduction marks."}]},{"text":[{"text":"Definition:","bold":true},{"text":" an authoritative definition first, then explain simply."}]},{"text":[{"text":"Body:","bold":true},{"text":" one point per paragraph, a sharp topic sentence, linking words (moreover, however), and "},{"text":"many cases","bold":true},{"text":"."}]},{"text":[{"text":"Conclusion:","bold":true},{"text":" summarise and recommend; never leave it out."}]}]}]},{"text":[{"text":"IRAC in practice:","bold":true},{"text":" a question setting out facts and ending \""},{"text":"Advise him","bold":true},{"text":"\" (e.g. an Onitsha trader whose customary claim is challenged) is a problem question: identify each "},{"text":"issue","bold":true},{"text":", state the "},{"text":"rule","bold":true},{"text":" with authority, "},{"text":"apply","bold":true},{"text":" it to the facts, "},{"text":"conclude","bold":true},{"text":" with clear advice. Writing it as an essay or retelling the facts is wrong. "},{"text":"Hybrid","bold":true},{"text":" questions combine both methods."}]},{"text":[{"text":"Worked conclusion:","bold":true},{"text":" Bisi predicts cybercrime in Nigeria in ten years and warns of what could happen: "},{"text":"looking-ahead","bold":true},{"text":"."}]},{"text":[{"text":"Accuracy: avoid exaggeration, bias and guesswork. Mechanical accuracy: tenses, capitals, spelling."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Research = using library materials to determine authoritatively parties' rights, duties and liabilities."}]},{"text":[{"text":"Law is dynamic; textbooks give law \"at second hand\"."}]},{"text":[{"text":"Library of Congress (letter: K108.7) vs Dewey (number: 642.13); shelve by letter, number, auth$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 40, $study_guide$or letter, author number."}]},{"text":[{"text":"Catalogue by author, title, subject; author entry is the main entry."}]},{"text":[{"text":"Citation: parties, year, volume, report, page; [ ] year essential, ( ) not; NWLR parts never repeat."}]},{"text":[{"text":"NWLR = Court of Appeal + Supreme Court weekly; SCNJ = Supreme Court only."}]},{"text":[{"text":"Periodical index for articles; reference books marked R/REF; Halsbury's the take-off point."}]},{"text":[{"text":"Essays: descriptive, narrative, expository, argumentative; topic correct, complete, concise."}]},{"text":[{"text":"Four tests: writing, credibility, friendly colleague, possibility; first draft \"don't get it right, get it written\"."}]},{"text":[{"text":"IDBC for essays, IRAC for problems."}]}]}],"theory":{"itemId":"e508e863-80cf-546f-8bcd-1a2f8231d36a","question":[{"type":"paragraph","text":[{"text":"Daphine, a final-year student, asks how to prepare and write her long essay. Advise her on the methods and approaches involved in essay writing."}]}]},"practice":[{"topic":"Legal Research and Legal Writing","named":false}]}}],"theory":[{"kind":"theory_question","itemId":"73f00702-90bb-546d-a270-d21a617d25c1","sourceKey":"guide-theory:1","position":1,"payload":{"prompt":"\"Law is like the proverbial elephant; you can only describe it from the perspective you choose.\" Discuss the schools of thought on the meaning of law and their relevance today."},"answer":{"kind":"model_answer","itemId":"38b0de96-307e-54ba-9931-80d8e447d02f","sourceKey":"guide-answer:1","payload":{"body":"• Introduction: technical meaning of law; the five blind men; Okunniga; theories overlap and are often implicit.\n• Positivism: Austin's definition and three elements; criticisms (wills, dictatorship, Lakanmi v A.G. (Western State) (1971), obedience without fear); Hart's primary and secondary rules. Relevance: supremacy of enacted law.\n• Pure theory: Kelsen's grundnorm and the Criminal Code chain; criticisms (formalism, locating the grundnorm, coups). Relevance: hierarchy of laws.\n• Natural law: Aquinas, Cicero, Grotius; criticisms (ought not is, multiple conscience). Relevance: Chapter IV rights, Niger Delta agitation.\n• Historical: Savigny's volksgeist; criticisms. Relevance: customary law and its three validity tests.\n• Others, one point and one criticism each: Ehrlich (checkpoint extortion), Pound (balancing), Bentham (airport searches), Holmes and Frank (extralegal factors).\n• Conclusion: each school sees one part of the elephant; Nigerian law draws on all; offer your own definition joining source, sanction and justice."}}},{"kind":"theory_question","itemId":"056bbef2-4eac-53f6-86c2-5f26a4949416","sourceKey":"guide-theory:2","position":2,"payload":{"prompt":"\"Justice, like beauty, is in the eye of the beholder\" (Emily Thorne). Discuss the various perceptions and types of justice."},"answer":{"kind":"model_answer","itemId":"016acb76-d119-57ca-aeac-5bf32fdbc4f2","sourceKey":"guide-answer:2","payload":{"body":"• Introduction: law is the means, justice the end; Ross (correct application, not arbitrariness); Soyinka; explain the quote with winner and loser in court; list factors shaping one's view.\n• Perceptions: Aristotle (law and equality), equality and its limits (the mother's three children, legal aid), Ulpian and Aquinas (render each his due), Plato (fitted for: caste, Osu), Rawls (fairness), Bix and Lasswell.\n• Types: commutative and distributive (Aquinas); corrective and distributive (Aristotle) with Federal Character and palliatives; procedural (section 36); formal (Awolowo's treasonable felony trial, Sheddon v Goodrich) against substantive (Chinwendu v Mbamali, judicial activism, Dennis Lloyd, reasonable man test); Josiah v The State.\n• Conclusion: justice is relative, yet law must balance competing interests; a just law commands obedience; apartheid shows law and justice can part."}}},{"kind":"theory_question","itemId":"52b0d680-0180-5709-bc2b-142dea0724a8","sourceKey":"guide-theory:3","position":3,"payload":{"prompt":"\"Distinguishing in practice between one classification of law and another may not be as clear-cut as it appears in theory.\" Discuss, with reference to any four classifications of law."},"answer":{"kind":"model_answer","itemId":"85b50280-9f15-5461-966c-4765154d9635","sourceKey":"guide-answer:3","payload":{"body":"• Introduction: law can be classified in many ways; list the six classifications; thesis: useful tools that overlap in practice.\n• Public v private: define with examples; the state as 'higher' party; Nigeria has no separate courts (contrast France), only special procedures (fundamental rights, judicial review); Land Use Act shows land law moving into public law; tax is both.\n• Civil v criminal: define; standards of proof (ss.134-135 Evidence Act 2011); overlap: assault, false imprisonment, defamation; stealing a bicycle = stealing plus conversion.\n• Written v unwritten: technical meaning; case law is written down yet unwritten (Donoghue v Stevenson); s.36(12) and Aoko v Fagbemi.\n• Common law v equity: history, Earl of Oxford's case (1615), Lord Bacon, Judicature Acts 1875 fused administration, not rights.\n• Practical importance: choice of procedure and remedy; the dismissed injured employee (contract, labour, tort).\n• Conclusion: the classifications overlap and are the lawyer's servants, not his masters, but they remain essential for choosing the right court, procedure and remedy."}}},{"kind":"theory_question","itemId":"5fb8404d-f31e-5259-bfd9-fd3c3cd9fd53","sourceKey":"guide-theory:4","position":4,"payload":{"prompt":"Analysing the role of law as an instrument of social control, discuss any four methods of social control through law, with Nigerian examples."},"answer":{"kind":"model_answer","itemId":"ac001134-4f1c-5a92-9cd7-645663fca301","sourceKey":"guide-answer:4","payload":{"body":"• Introduction: define social control (Ross, Otite and Ogionwo); Pound's definition and \"paramount agent\"; Quinney's three$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 41, $study_guide$ elements; law's advantages and functions; list the seven techniques (Summers; Farrar and Dugdale).\n• Penal: prohibited conduct, penalty, procedure, punishment; police, Attorney-General, courts, prisons; Criminal and Penal Codes; alternatives with Aoko v Fagbemi and FCSC v Laoye.\n• Grievance-remedial: Summers' definition; remedies; logical basis; Smith v Selwyn; arbitration.\n• Constitutive: new legal person; Salomon v Salomon [1897]; incorporated trustees, universities.\n• Administrative-regulatory: standards, licensing, inspection; NAFDAC, NCC, school permits; preventive, unlike grievance-remedial.\n• Conclusion: techniques overlap and combine; note limits (dead-letter laws, weak enforcement, elite hijacking of welfare); law remains the most organised instrument of social control."}}},{"kind":"theory_question","itemId":"e7570f39-06f5-5958-b9eb-856041a2859e","sourceKey":"guide-theory:5","position":5,"payload":{"prompt":"Critically examine the adversarial and inquisitorial methods of fact finding. Which do you prefer?"},"answer":{"kind":"model_answer","itemId":"7e3bbb43-cc98-5eb9-81e0-86f7648b564a","sourceKey":"guide-answer:5","payload":{"body":"• Introduction: adjudication requires the judge to find facts before applying law, by the adversarial or inquisitorial method.\n• Adversarial: parties control evidence; witness sequence; judge as umpire; balance of probability, modified by criminal rules (ss.35(2), 36(5); Woolmington v DPP; State v Keji Amusan) and res ipsa loquitur (Scott v London and St Katherine Docks). Five merits; five demerits (Whitehouse v Jordan; Ajani v Giwa).\n• Inquisitorial: adjudicator controls evidence (Ex parte Moore; Baba v NCATC). Four merits; three demerits (phantom coup trials).\n• Conclusion: state a reasoned preference, or argue for a blend as in divorce and custody cases."}}},{"kind":"theory_question","itemId":"60048f78-076c-54fd-82f1-f119a83545ec","sourceKey":"guide-theory:6","position":6,"payload":{"prompt":"Write short notes on (a) principles and standards, (b) legal rhetoric and legal logic, (c) legal reasoning and practical reasoning."},"answer":{"kind":"model_answer","itemId":"031d4bcd-a8ac-5cdb-9c52-93457e4c7b91","sourceKey":"guide-answer:6","payload":{"body":"• Introduction: define legal reasoning; each pair is a tool of it.\n• (a) Principle (legal truth contradicted only by a clearer one; grounds rules, e.g. natural justice); standard (flexible measure such as the reasonable man; Pound), contrasted with a fixed rule.\n• (b) Rhetoric (Plato; Aristotle's forensic and deliberative; appeal to authority; acquired skill). Logic (its value; syllogism with example; three limitations; induction; Dorset Yacht; analogy).\n• (c) Practical reasoning (no strict deduction, uses analogy, weighs considerations, judged by society's values); Holmes; four justifying factors; Chinwendu v Mbamali.\n• Conclusion: logic and rhetoric are the technical side; justice, policy and common sense complete legal reasoning."}}},{"kind":"theory_question","itemId":"b1d50cd4-755c-597c-8b21-8f82a6086dd2","sourceKey":"guide-theory:7","position":7,"payload":{"prompt":"\"The primary duty of the courts in interpreting statutes is to find the intention of the legislature\" (Obilade). Discuss the rules of statutory interpretation with cases."},"answer":{"kind":"model_answer","itemId":"e9fe0018-be88-52a5-b6ff-951805f6c0e3","sourceKey":"guide-answer:7","payload":{"body":"• Introduction: s.6(6)(b) judicial power; statutes suffer ambiguity, vagueness, open texture; courts seek intention from the words.\n• Literal: Sussex Peerage; weaknesses shown by Awolowo v Shagari and Adegbenro v Akintola; Dias.\n• Golden: absurdity, no further; Adamolekun.\n• Mischief: Heydon's case four questions; limits.\n• Purposive: Nafiu Rabiu v State; Lord Simonds' warning in Magor.\n• Assessment: rules of practice; Fatayi-Williams CJN; Bennion; supplement with aids, presumptions (Barclays Bank v CBN) and maxims.\n• Conclusion: a combination of canons and aids, against the legislative purpose, best finds legislative intention."}}},{"kind":"theory_question","itemId":"26d0c68c-8b07-5936-9b53-0696aaa660fa","sourceKey":"guide-theory:8","position":8,"payload":{"prompt":"\"Customary law is a veritable source of Nigerian law only in so far as it passes the tests of validity.\" Discuss with decided cases."},"answer":{"kind":"model_answer","itemId":"b06199e6-789e-5856-b667-394bd4f7548d","sourceKey":"guide-answer:8","payload":{"body":"• Introduction: define sources of Nigerian law and customary law (customs accepted by a community as binding); classify into ethnic customary law and Islamic law; note its flexibility (Lewis v Bankole). Thesis: courts enforce custom only if it passes three statutory tests.\n• Statutory basis: High Court Laws of the States and FCT (e.g. s 44 High Court Law, Oyo State 1978).\n• Repugnancy: no settled definition; Eshugbayi Eleko (barbarous custom); Re Effiong Okon Atta; Guri v Hadejia NA; limits: Dawodu v Danmole (inconsistency with English ideas is not repugnancy).\n• Public policy: Cole v Akinyele.\n• Incompatibility with written law: e.g. Legitimacy Act; s 36(12) 1999 Constitution and Aoko v Fagbemi (no unwritten customary crimes).\n• Conclusion: custom remains a primary, binding source within these limits; the tests protect justice without imposing English standards."}}},{"kind":"theory_question","itemId":"e508e863-80cf-546f-8bcd-1a2f8231d36a","sourceKey":"guide-theory:9","position":9,"payload":{"prompt":"Daphine, a final-year student, asks how to prepare and write her long essay. Advise her on the methods and approaches involved in essay writing."},"answer":{"kind":"model_answer","itemId":"259ec35a-431f-5db2-a668-83603fe9759f","sourceKey":"guide-answer:9","payload":{"body":"• Introduction: define an essay; note the four types; thesis: good writing follows settled steps.\n• Pre-writing: choose a manageable topic with available materials (correct, complete, concise); preliminary reading; rethink w$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_pul101', 42, $study_guide$ith what, who, where, when, how, why; identify the basic question; formulate a restricted, organised thesis.\n• Test the idea: writing, credibility, friendly colleague, possibility.\n• Outline and materials: topic-specific, related, current and classic works (e.g. Obilade); read selectively, responsibly, critically.\n• Writing: at least four drafts (get it written; add detail; cut dead wood; review); chapters, sections, subsections.\n• General hints: brief engaging introduction, originality (no plagiarism), clarity, brevity, accuracy, organisation, paragraphs, mechanical accuracy.\n• Conclusion: choose reflective, looking-ahead or straightforward; following these steps produces an essay that impresses."}}}]}$study_guide$);
